Plot_GSE182018_HHT <- ggplot(data = GSE182018_HHT_data, aes(x = avg_counts, y = Normalized_MFE, color = condition)) +
  geom_point(alpha = 0.6) +
  theme_classic() +
  labs(
    title = "GSE182018 MFE vs. Avg Counts HHT",
    x = "Transcript Counts",
    y = "Normalized MFE (kcal/mol)"
  ) +
  ylim(-0.8, 0) +
  theme(
    axis.title = element_text(size = 15),
    plot.title = element_text(size = 15)
  ) +
  guides(color = FALSE)

GSE182018_combined_plots <- Plot_GSE182018_control + Plot_GSE182018_HHT
GSE182018_combined_plots

