MFE_GSE192446_JAR_DOWN <- dplyr::filter(MFE_GSE192446_JAR, log2FoldChange < 0)
Mean_MFE_GSE192446_JAR_DOWN <- mean(MFE_GSE192446_JAR_DOWN$Normalized_MFE)

TTEST_MFE_GSE192446_JAR_all_UP_vs_DOWN <- t.test(MFE_GSE192446_JAR_DOWN$Normalized_MFE, MFE_GSE192446_JAR_UP$Normalized_MFE, paired=FALSE)

ks_test_GSE192446_JAR_all_UP_vs_DOWN <- ks.test(MFE_GSE192446_JAR_DOWN$Normalized_MFE, MFE_GSE192446_JAR_UP$Normalized_MFE)

quantile_075_MFE_GSE192446_JAR_UP <- quantile(MFE_GSE192446_JAR_UP$Normalized_MFE, probs = c(0.75))
quantile_075_MFE_GSE192446_JAR_DOWN <- quantile(MFE_GSE192446_JAR_DOWN$Normalized_MFE, probs = c(0.75))
ks_test_MFE_GSE192446_JAR_075_above <- ks.test(MFE_GSE192446_JAR_UP$Normalized_MFE[MFE_GSE192446_JAR_UP$Normalized_MFE >= quantile_075_MFE_GSE192446_JAR_UP],
                                 MFE_GSE192446_JAR_DOWN$Normalized_MFE[MFE_GSE192446_JAR_DOWN$Normalized_MFE >= quantile_075_MFE_GSE192446_JAR_DOWN])

quantile_025_MFE_GSE192446_JAR_UP <- quantile(MFE_GSE192446_JAR_UP$Normalized_MFE, probs = c(0.25))
quantile_025_MFE_GSE192446_JAR_DOWN <- quantile(MFE_GSE192446_JAR_DOWN$Normalized_MFE, probs = c(0.25))
ks_test_MFE_GSE192446_JAR_025_below <- ks.test(MFE_GSE192446_JAR_UP$Normalized_MFE[MFE_GSE192446_JAR_UP$Normalized_MFE <= quantile_025_MFE_GSE192446_JAR_UP],
                                 MFE_GSE192446_JAR_DOWN$Normalized_MFE[MFE_GSE192446_JAR_DOWN$Normalized_MFE <= quantile_025_MFE_GSE192446_JAR_DOWN])

upregulated <- data.frame(MFE = MFE_GSE192446_JAR_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_GSE192446_JAR_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

GSE192446_JAR_observed_diff <- mean(MFE_GSE192446_JAR_UP$Normalized_MFE) - mean(MFE_GSE192446_JAR_DOWN$Normalized_MFE)

n_permutations <- 10000

GSE192446_JAR_permuted_diffs <- numeric(n_permutations)

set.seed(123)
for (i in 1:n_permutations) {
  permuted_labels <- sample(combined_data$Group)

  permuted_up_mean <- mean(combined_data$MFE[permuted_labels == "Up"])
  permuted_down_mean <- mean(combined_data$MFE[permuted_labels == "Down"])

  GSE192446_JAR_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

GSE192446_JAR_p_value <- (sum(abs(GSE192446_JAR_permuted_diffs) >= abs(GSE192446_JAR_observed_diff)) + 1) / (n_permutations + 1)

