TTEST_MFE_GSE192446_JEG3_all_UP_vs_DOWN <- t.test(MFE_GSE192446_JEG3_DOWN$Normalized_MFE, MFE_GSE192446_JEG3_UP$Normalized_MFE, paired=FALSE)

ks_test_GSE192446_JEG3_all_UP_vs_DOWN <- ks.test(MFE_GSE192446_JEG3_DOWN$Normalized_MFE, MFE_GSE192446_JEG3_UP$Normalized_MFE)

quantile_075_MFE_GSE192446_JEG3_UP <- quantile(MFE_GSE192446_JEG3_UP$Normalized_MFE, probs = c(0.75))
quantile_075_MFE_GSE192446_JEG3_DOWN <- quantile(MFE_GSE192446_JEG3_DOWN$Normalized_MFE, probs = c(0.75))
ks_test_MFE_GSE192446_JEG3_075_above <- ks.test(MFE_GSE192446_JEG3_UP$Normalized_MFE[MFE_GSE192446_JEG3_UP$Normalized_MFE >= quantile_075_MFE_GSE192446_JEG3_UP],
                                               MFE_GSE192446_JEG3_DOWN$Normalized_MFE[MFE_GSE192446_JEG3_DOWN$Normalized_MFE >= quantile_075_MFE_GSE192446_JEG3_DOWN])

quantile_025_MFE_GSE192446_JEG3_UP <- quantile(MFE_GSE192446_JEG3_UP$Normalized_MFE, probs = c(0.25))
quantile_025_MFE_GSE192446_JEG3_DOWN <- quantile(MFE_GSE192446_JEG3_DOWN$Normalized_MFE, probs = c(0.25))
ks_test_MFE_GSE192446_JEG3_025_below <- ks.test(MFE_GSE192446_JEG3_UP$Normalized_MFE[MFE_GSE192446_JEG3_UP$Normalized_MFE <= quantile_025_MFE_GSE192446_JEG3_UP],
                                               MFE_GSE192446_JEG3_DOWN$Normalized_MFE[MFE_GSE192446_JEG3_DOWN$Normalized_MFE <= quantile_025_MFE_GSE192446_JEG3_DOWN])

upregulated <- data.frame(MFE = MFE_GSE192446_JEG3_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_GSE192446_JEG3_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

GSE192446_JEG3_observed_diff <- mean(MFE_GSE192446_JEG3_UP$Normalized_MFE) - mean(MFE_GSE192446_JEG3_DOWN$Normalized_MFE)

n_permutations <- 10000

GSE192446_JEG3_permuted_diffs <- numeric(n_permutations)

set.seed(123)
for (i in 1:n_permutations) {
  permuted_labels <- sample(combined_data$Group)

  permuted_up_mean <- mean(combined_data$MFE[permuted_labels == "Up"])
  permuted_down_mean <- mean(combined_data$MFE[permuted_labels == "Down"])

  GSE192446_JEG3_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

GSE192446_JEG3_p_value <- (sum(abs(GSE192446_JEG3_permuted_diffs) >= abs(GSE192446_JEG3_observed_diff)) + 1) / (n_permutations + 1)

cat("Observed difference in GSE192446_JEG3 means MFE_UP - MFE_DOWN:", GSE192446_JEG3_observed_diff, "\n")
cat("GSE192446_JEG3 P-value from permutation test:", GSE192446_JEG3_p_value, "\n")

