GSE192446_JAR_high_MFE_TX_in_UP <- dplyr::filter(MFE_GSE192446_JAR_UP, ensembl_transcript_id_version %in% GSE192446_JAR_high_MFE_TX$ensembl_transcript_id_version)
GSE192446_JAR_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_GSE192446_JAR_DOWN, ensembl_transcript_id_version %in% GSE192446_JAR_high_MFE_TX$ensembl_transcript_id_version)

GSE192446_JAR_total_UP <- nrow(MFE_GSE192446_JAR_UP)
GSE192446_JAR_total_DOWN <- nrow(MFE_GSE192446_JAR_DOWN)

GSE192446_JAR_count_high_MFE_UP <- nrow(GSE192446_JAR_high_MFE_TX_in_UP)
GSE192446_JAR_count_high_MFE_DOWN <- nrow(GSE192446_JAR_high_MFE_TX_in_DOWN)

GSE192446_JAR_high_MFE_in_UP_fraction <- GSE192446_JAR_count_high_MFE_UP / GSE192446_JAR_total_UP
GSE192446_JAR_high_MFE_in_DOWN_fraction <- GSE192446_JAR_count_high_MFE_DOWN / GSE192446_JAR_total_DOWN

p_pool <- (GSE192446_JAR_count_high_MFE_UP + GSE192446_JAR_count_high_MFE_DOWN) / (GSE192446_JAR_total_UP + GSE192446_JAR_total_DOWN)

SE <- sqrt(p_pool * (1 - p_pool) * (1 / GSE192446_JAR_total_UP + 1 / GSE192446_JAR_total_DOWN))

z_value <- (GSE192446_JAR_high_MFE_in_UP_fraction - GSE192446_JAR_high_MFE_in_DOWN_fraction) / SE

