GSE192446_JEG3_control_high_MFE_TX_counts_fraction <- GSE192446_JEG3_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE192446_JEG3_control_total_counts$total_counts
cat("Control group high MFE fraction:", GSE192446_JEG3_control_high_MFE_TX_counts_fraction, "\n")

GSE192446_JEG3_vorinostat_total_counts <- dplyr::filter(GSE192446_JEG3_norm_TX_aggregated_data_avg_counts, condition == "vorinostat") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE192446_JEG3_vorinostat_high_MFE_TX_counts <- dplyr::filter(GSE192446_JEG3_norm_TX_aggregated_data_avg_counts, condition == "vorinostat") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE192446_JEG3_high_MFE_TX$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE192446_JEG3_vorinostat_high_MFE_TX_counts_fraction <- GSE192446_JEG3_vorinostat_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE192446_JEG3_vorinostat_total_counts$total_counts
cat("Vorinostat group high MFE fraction:", GSE192446_JEG3_vorinostat_high_MFE_TX_counts_fraction, "\n")

p1 <- GSE192446_JEG3_control_high_MFE_TX_counts_fraction
p2 <- GSE192446_JEG3_vorinostat_high_MFE_TX_counts_fraction

p_pool <- (GSE192446_JEG3_control_high_MFE_TX_counts$total_counts_high_MFE_TX + GSE192446_JEG3_vorinostat_high_MFE_TX_counts$total_counts_high_MFE_TX) /
  (GSE192446_JEG3_control_total_counts$total_counts + GSE192446_JEG3_vorinostat_total_counts$total_counts)

SE <- sqrt(p_pool * (1 - p_pool) * (1 / GSE192446_JEG3_control_total_counts$total_counts + 1 / GSE192446_JEG3_vorinostat_total_counts$total_counts))

z_value <- (p1 - p2) / SE

GSE192446_JEG3_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(z_value)))

cat("GSE192446_JEG3 Two-Proportion Z-test P-value for high MFE transcript counts between control and drug-treated groups:", GSE192446_JEG3_z_test_counts_75_p_value, "\n")
cat("Net change in proportions of high MFE transcript counts (vorinostat - control):", p2 - p1, "\n")

