all(rownames(Expdata_GSE165325) %in% colnames(Counts_GSE165325_GREIN))
all(colnames(Counts_GSE165325_GREIN) %in% rownames(Expdata_GSE165325))

dds_GSE165325 <- DESeqDataSetFromMatrix(countData = Counts_GSE165325_GREIN,
                                        colData = Expdata_GSE165325,
                                        design = ~ condition)
dds_GSE165325

ntd <- normTransform(dds_GSE165325)
select <- order(rowMeans(counts(dds_GSE165325,normalized=FALSE)),
                decreasing=TRUE)[1:20]
df <- as.data.frame(colData(dds_GSE165325)[,c("condition","type")])
pheatmap(assay(ntd)[select,], cluster_rows=FALSE, show_rownames=FALSE,
         cluster_cols=FALSE, annotation_col=df)

vsd <- vst(dds_GSE165325, blind=FALSE)
head(assay(vsd), 3)

sampleDists <- dist(t(assay(vsd)))

sampleDistMatrix <- as.matrix(sampleDists)
rownames(sampleDistMatrix) <- paste(vsd$condition, vsd$type, sep="-")
colnames(sampleDistMatrix) <- NULL
colors <- colorRampPalette( rev(brewer.pal(9, "Blues")) )(255)
pheatmap(sampleDistMatrix,
         clustering_distance_rows=sampleDists,
         clustering_distance_cols=sampleDists,
         col=colors)

plotPCA(vsd, intgroup="condition")

