ks_test_MFE_075_above <- ks.test(MFE_GSE137535_SH454_UP$Normalized_MFE[MFE_GSE137535_SH454_UP$Normalized_MFE >= quantile_075_MFE_GSE137535_SH454_UP],
                                 MFE_GSE137535_SH454_DOWN$Normalized_MFE[MFE_GSE137535_SH454_DOWN$Normalized_MFE >= quantile_075_MFE_GSE137535_SH454_DOWN])

quantile_025_MFE_GSE137535_SH454_UP <- quantile(MFE_GSE137535_SH454_UP$Normalized_MFE, probs = c(0.25))
quantile_025_MFE_GSE137535_SH454_DOWN <- quantile(MFE_GSE137535_SH454_DOWN$Normalized_MFE, probs = c(0.25))
ks_test_MFE_025_below <- ks.test(MFE_GSE137535_SH454_UP$Normalized_MFE[MFE_GSE137535_SH454_UP$Normalized_MFE <= quantile_025_MFE_GSE137535_SH454_UP],
                                 MFE_GSE137535_SH454_DOWN$Normalized_MFE[MFE_GSE137535_SH454_DOWN$Normalized_MFE <= quantile_025_MFE_GSE137535_SH454_DOWN])

upregulated <- data.frame(MFE = MFE_GSE137535_SH454_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_GSE137535_SH454_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

GSE137535_SH454_observed_diff <- mean(MFE_GSE137535_SH454_UP$Normalized_MFE) - mean(MFE_GSE137535_SH454_DOWN$Normalized_MFE)

n_permutations <- 10000

GSE137535_SH454_permuted_diffs <- numeric(n_permutations)

set.seed(123)
for (i in 1:n_permutations) {
  permuted_labels <- sample(combined_data$Group)

  permuted_up_mean <- mean(combined_data$MFE[permuted_labels == "Up"])
  permuted_down_mean <- mean(combined_data$MFE[permuted_labels == "Down"])

  GSE137535_SH454_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

GSE137535_SH454_p_value <- (sum(abs(GSE137535_SH454_permuted_diffs) >= abs(GSE137535_SH454_observed_diff)) + 1) / (n_permutations + 1)

cat("Observed difference in GSE137535_SH454 means MFE_UP - MFE_DOWN:", GSE137535_SH454_observed_diff, "\n")
cat("GSE137535_SH454 P-value from permutation test:", GSE137535_SH454_p_value, "\n")

