all(rownames(Expdata_GSE100327) %in% colnames(Counts_GSE100327_GREIN))
all(colnames(Counts_GSE100327_GREIN) %in% rownames(Expdata_GSE100327))

dds_GSE100327 <- DESeqDataSetFromMatrix(countData = Counts_GSE100327_GREIN,
                                        colData = Expdata_GSE100327,
                                        design = ~ condition)
dds_GSE100327

ntd <- normTransform(dds_GSE100327)
select <- order(rowMeans(counts(dds_GSE100327,normalized=FALSE)),
                decreasing=TRUE)[1:20]
df <- as.data.frame(colData(dds_GSE100327)[,c("condition","type")])
pheatmap(assay(ntd)[select,], cluster_rows=FALSE, show_rownames=FALSE,
         cluster_cols=FALSE, annotation_col=df)

vsd <- vst(dds_GSE100327, blind=FALSE)
head(assay(vsd), 3)

sampleDists <- dist(t(assay(vsd)))

sampleDistMatrix <- as.matrix(sampleDists)
rownames(sampleDistMatrix) <- paste(vsd$condition, vsd$type, sep="-")
colnames(sampleDistMatrix) <- NULL
colors <- colorRampPalette( rev(brewer.pal(9, "Blues")) )(255)
pheatmap(sampleDistMatrix,
         clustering_distance_rows=sampleDists,
         clustering_distance_cols=sampleDists,
         col=colors)

plotPCA(vsd, intgroup="condition")

keep <- rowSums(counts(dds_GSE100327)) >= 3
dds_GSE100327 <- dds_GSE100327[keep,]

dds_GSE100327 <- DESeq(dds_GSE100327)

