res_GSE100327_779e

res_GSE100327_BxPC_df <- data.frame(res_GSE100327_BxPC)
res_GSE100327_BxPC <- tibble::rownames_to_column(res_GSE100327_BxPC_df, "ensembl_transcript_id")

MFE_GSE100327_BxPC <- dplyr::inner_join(Table_ANNOTATED, res_GSE100327_BxPC, by="ensembl_transcript_id") %>%
  dplyr::filter(padj < 0.05)

Plot_GSE100327_BxPC <- ggplot(MFE_GSE100327_BxPC, aes(y=Normalized_MFE, x=log2FoldChange)) +
  geom_point(size=1.5, alpha=0.1)+
  theme_classic() +
  theme(legend.position="none") +
  geom_vline(xintercept = 0, size=0.3) +
  xlim(-15, 15) +
  theme(axis.title = element_text(size = 20)) +
  theme(plot.title = element_text(size = 15)) +
  labs(y="DGfold / nt (kcal/mol)",x="Log2_FC_expression",title="GSE100327_BxPC_Log2_FC_adj.P<0.05")
print(Plot_GSE100327_BxPC)

ggsave("Plot_GSE100327_BxPC.pdf", plot = Plot_GSE100327_BxPC, path = output_dir)

MFE_GSE100327_BxPC_UP <- dplyr::filter(MFE_GSE100327_BxPC, log2FoldChange > 0)
Mean_MFE_GSE100327_BxPC_UP <- mean(MFE_GSE100327_BxPC_UP$Normalized_MFE)

MFE_GSE100327_BxPC_DOWN <- dplyr::filter(MFE_GSE100327_BxPC, log2FoldChange < 0)
Mean_MFE_GSE100327_BxPC_DOWN <- mean(MFE_GSE100327_BxPC_DOWN$Normalized_MFE)

TTEST_MFE_GSE100327_BxPC_all_UP_vs_DOWN <- t.test(MFE_GSE100327_BxPC_DOWN$Normalized_MFE, MFE_GSE100327_BxPC_UP$Normalized_MFE, paired=FALSE)

ks_test_GSE100327_BxPC_all_UP_vs_DOWN <- ks.test(MFE_GSE100327_BxPC_DOWN$Normalized_MFE, MFE_GSE100327_BxPC_UP$Normalized_MFE)

quantile_075_MFE_GSE100327_BxPC_UP <- quantile(MFE_GSE100327_BxPC_UP$Normalized_MFE, probs = c(0.75))
quantile_075_MFE_GSE100327_BxPC_DOWN <- quantile(MFE_GSE100327_BxPC_DOWN$Normalized_MFE, probs = c(0.75))
ks_test_MFE_075_above <- ks.test(MFE_GSE100327_BxPC_UP$Normalized_MFE[MFE_GSE100327_BxPC_UP$Normalized_MFE >= quantile_075_MFE_GSE100327_BxPC_UP],
                                 MFE_GSE100327_BxPC_DOWN$Normalized_MFE[MFE_GSE100327_BxPC_DOWN$Normalized_MFE >= quantile_075_MFE_GSE100327_BxPC_DOWN])

quantile_025_MFE_GSE100327_BxPC_UP <- quantile(MFE_GSE100327_BxPC_UP$Normalized_MFE, probs = c(0.25))
quantile_025_MFE_GSE100327_BxPC_DOWN <- quantile(MFE_GSE100327_BxPC_DOWN$Normalized_MFE, probs = c(0.25))
ks_test_MFE_025_below <- ks.test(MFE_GSE100327_BxPC_UP$Normalized_MFE[MFE_GSE100327_BxPC_UP$Normalized_MFE <= quantile_025_MFE_GSE100327_BxPC_UP],
                                 MFE_GSE100327_BxPC_DOWN$Normalized_MFE[MFE_GSE100327_BxPC_DOWN$Normalized_MFE <= quantile_025_MFE_GSE100327_BxPC_DOWN])

upregulated <- data.frame(MFE = MFE_GSE100327_BxPC_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_GSE100327_BxPC_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

GSE100327_BxPC_observed_diff <- mean(MFE_GSE100327_BxPC_UP$Normalized_MFE) - mean(MFE_GSE100327_BxPC_DOWN$Normalized_MFE)

n_permutations <- 10000

GSE100327_BxPC_permuted_diffs <- numeric(n_permutations)

set.seed(123)
for (i in 1:n_permutations) {
  permuted_labels <- sample(combined_data$Group)

  permuted_up_mean <- mean(combined_data$MFE[permuted_labels == "Up"])
  permuted_down_mean <- mean(combined_data$MFE[permuted_labels == "Down"])

  GSE100327_BxPC_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

GSE100327_BxPC_p_value <- (sum(abs(GSE100327_BxPC_permuted_diffs) >= abs(GSE100327_BxPC_observed_diff)) + 1) / (n_permutations + 1)

cat("Observed difference in GSE100327_BxPC means MFE_UP - MFE_DOWN:", GSE100327_BxPC_observed_diff, "\n")
cat("GSE100327_BxPC P-value from permutation test:", GSE100327_BxPC_p_value, "\n")

