                GSM2677861, GSM2677862, GSM2677863, GSM2677864, GSM2677865, GSM2677866, Normalized_MFE) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_GSE100327_BxPC$ensembl_transcript_id)

quantile_075_GSE100327_BxPC_norm_TX_counts_MFE_df <- quantile(GSE100327_BxPC_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

