GSE100327_BxPC_high_MFE_TX_in_UP <- dplyr::filter(MFE_GSE100327_BxPC_UP, ensembl_transcript_id_version %in% GSE100327_BxPC_high_MFE_TX$ensembl_transcript_id_version)
GSE100327_BxPC_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_GSE100327_BxPC_DOWN, ensembl_transcript_id_version %in% GSE100327_BxPC_high_MFE_TX$ensembl_transcript_id_version)

GSE100327_BxPC_total_UP <- nrow(MFE_GSE100327_BxPC_UP)
GSE100327_BxPC_total_DOWN <- nrow(MFE_GSE100327_BxPC_DOWN)
GSE100327_BxPC_count_high_MFE_UP <- nrow(GSE100327_BxPC_high_MFE_TX_in_UP)
GSE100327_BxPC_count_high_MFE_DOWN <- nrow(GSE100327_BxPC_high_MFE_TX_in_DOWN)

p_UP <- GSE100327_BxPC_count_high_MFE_UP / GSE100327_BxPC_total_UP
p_DOWN <- GSE100327_BxPC_count_high_MFE_DOWN / GSE100327_BxPC_total_DOWN

p_pool <- (GSE100327_BxPC_count_high_MFE_UP + GSE100327_BxPC_count_high_MFE_DOWN) /
  (GSE100327_BxPC_total_UP + GSE100327_BxPC_total_DOWN)

SE <- sqrt(p_pool * (1 - p_pool) * (1 / GSE100327_BxPC_total_UP + 1 / GSE100327_BxPC_total_DOWN))

z_value <- (p_UP - p_DOWN) / SE

GSE100327_BxPC_z_test_MFE_p_value <- 2 * (1 - pnorm(abs(z_value)))

cat("GSE100327_BxPC Two-Proportion Z-test P-value for high MFE transcript counts between UP-regulated and DOWN-regulated genes:", GSE100327_BxPC_z_test_MFE_p_value, "\n")

