  (GSE100327_MIA_PaCa_control_total_counts$total_counts + GSE100327_MIA_PaCa_MIA_PaCa_total_counts$total_counts)

SE <- sqrt(p_pool * (1 - p_pool) * (1 / GSE100327_MIA_PaCa_control_total_counts$total_counts + 1 / GSE100327_MIA_PaCa_MIA_PaCa_total_counts$total_counts))

