GSE100327_MIA_PaCa_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(z_value)))

cat("GSE100327_MIA_PaCa Two-Proportion Z-test P-value for high MFE transcript counts between Control and MIA_PaCa:", GSE100327_MIA_PaCa_z_test_counts_75_p_value, "\n")

