cat("GSE100327_MIA_PaCa net change counts high MFE TX drug vs control:", GSE100327_MIA_PaCa_MIA_PaCa_high_MFE_TX_counts_fraction - GSE100327_MIA_PaCa_control_high_MFE_TX_counts_fraction, "\n")

