MFE_GSE105083_MIA_PACA2_6h_UP <- dplyr::filter(MFE_GSE105083_MIA_PACA2_6h, log2FoldChange > 0)
Mean_MFE_GSE105083_MIA_PACA2_6h_UP <- mean(MFE_GSE105083_MIA_PACA2_6h_UP$Normalized_MFE)

MFE_GSE105083_MIA_PACA2_6h_DOWN <- dplyr::filter(MFE_GSE105083_MIA_PACA2_6h, log2FoldChange < 0)
Mean_MFE_GSE105083_MIA_PACA2_6h_DOWN <- mean(MFE_GSE105083_MIA_PACA2_6h_DOWN$Normalized_MFE)

TTEST_MFE_GSE105083_MIA_PACA2_6h_all_UP_vs_DOWN <- t.test(MFE_GSE105083_MIA_PACA2_6h_DOWN$Normalized_MFE, MFE_GSE105083_MIA_PACA2_6h_UP$Normalized_MFE, paired=FALSE)

ks_test_GSE105083_MIA_PACA2_6h_all_UP_vs_DOWN <- ks.test(MFE_GSE105083_MIA_PACA2_6h_DOWN$Normalized_MFE, MFE_GSE105083_MIA_PACA2_6h_UP$Normalized_MFE)
print(ks_test_GSE105083_MIA_PACA2_6h_all_UP_vs_DOWN)

quantile_075_MFE_GSE105083_MIA_PACA2_6h_UP <- quantile(MFE_GSE105083_MIA_PACA2_6h_UP$Normalized_MFE, probs = c(0.75))
quantile_075_MFE_GSE105083_MIA_PACA2_6h_DOWN <- quantile(MFE_GSE105083_MIA_PACA2_6h_DOWN$Normalized_MFE, probs = c(0.75))
ks_test_MFE_075_above <- ks.test(MFE_GSE105083_MIA_PACA2_6h_UP$Normalized_MFE[MFE_GSE105083_MIA_PACA2_6h_UP$Normalized_MFE >= quantile_075_MFE_GSE105083_MIA_PACA2_6h_UP],
                                 MFE_GSE105083_MIA_PACA2_6h_DOWN$Normalized_MFE[MFE_GSE105083_MIA_PACA2_6h_DOWN$Normalized_MFE >= quantile_075_MFE_GSE105083_MIA_PACA2_6h_DOWN])

quantile_025_MFE_GSE105083_MIA_PACA2_6h_UP <- quantile(MFE_GSE105083_MIA_PACA2_6h_UP$Normalized_MFE, probs = c(0.25))
quantile_025_MFE_GSE105083_MIA_PACA2_6h_DOWN <- quantile(MFE_GSE105083_MIA_PACA2_6h_DOWN$Normalized_MFE, probs = c(0.25))
ks_test_MFE_025_below <- ks.test(MFE_GSE105083_MIA_PACA2_6h_UP$Normalized_MFE[MFE_GSE105083_MIA_PACA2_6h_UP$Normalized_MFE <= quantile_025_MFE_GSE105083_MIA_PACA2_6h_UP],
                                 MFE_GSE105083_MIA_PACA2_6h_DOWN$Normalized_MFE[MFE_GSE105083_MIA_PACA2_6h_DOWN$Normalized_MFE <= quantile_025_MFE_GSE105083_MIA_PACA2_6h_DOWN])

upregulated <- data.frame(MFE = MFE_GSE105083_MIA_PACA2_6h_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_GSE105083_MIA_PACA2_6h_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

GSE105083_MIA_PACA2_6h_observed_diff <- mean(MFE_GSE105083_MIA_PACA2_6h_UP$Normalized_MFE) - mean(MFE_GSE105083_MIA_PACA2_6h_DOWN$Normalized_MFE)

n_permutations <- 10000

GSE105083_MIA_PACA2_6h_permuted_diffs <- numeric(n_permutations)

set.seed(123)
for (i in 1:n_permutations) {
  permuted_labels <- sample(combined_data$Group)

  permuted_up_mean <- mean(combined_data$MFE[permuted_labels == "Up"])
  permuted_down_mean <- mean(combined_data$MFE[permuted_labels == "Down"])

  GSE105083_MIA_PACA2_6h_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

GSE105083_MIA_PACA2_6h_p_value <- (sum(abs(GSE105083_MIA_PACA2_6h_permuted_diffs) >= abs(GSE105083_MIA_PACA2_6h_observed_diff)) + 1) / (n_permutations + 1)

cat("Observed difference in GSE105083_MIA_PACA2_6h means MFE_UP - MFE_DOWN:", GSE105083_MIA_PACA2_6h_observed_diff, "\n")
cat("GSE105083_MIA_PACA2_6h P-value from permutation test:", GSE105083_MIA_PACA2_6h_p_value, "\n")

