GSE105083_MIA_PACA2_24h_total_UP <- nrow(MFE_GSE105083_MIA_PACA2_24h_UP)
GSE105083_MIA_PACA2_24h_total_DOWN <- nrow(MFE_GSE105083_MIA_PACA2_24h_DOWN)
GSE105083_MIA_PACA2_24h_count_high_MFE_UP <- nrow(GSE105083_MIA_PACA2_24h_high_MFE_TX_in_UP)
GSE105083_MIA_PACA2_24h_count_high_MFE_DOWN <- nrow(GSE105083_MIA_PACA2_24h_high_MFE_TX_in_DOWN)

p_up <- GSE105083_MIA_PACA2_24h_count_high_MFE_UP / GSE105083_MIA_PACA2_24h_total_UP
p_down <- GSE105083_MIA_PACA2_24h_count_high_MFE_DOWN / GSE105083_MIA_PACA2_24h_total_DOWN

