GSE105083_MIA_PACA2_24h_high_MFE_TX_counts_MIA_PACA2_CM03_24h_CT <- GSE105083_MIA_PACA2_24h_MIA_PACA2_CM03_24h_high_MFE_TX_counts_fraction * GSE105083_MIA_PACA2_24h_MIA_PACA2_CM03_24h_total_counts$total_counts
GSE105083_MIA_PACA2_24h_low_MFE_TX_counts_MIA_PACA2_CM03_24h_CT <- GSE105083_MIA_PACA2_24h_MIA_PACA2_CM03_24h_total_counts$total_counts - GSE105083_MIA_PACA2_24h_MIA_PACA2_CM03_24h_high_MFE_TX_counts$total_counts_high_MFE_TX

prop_control <- GSE105083_MIA_PACA2_24h_high_MFE_TX_counts_control_CT / GSE105083_MIA_PACA2_24h_control_total_counts$total_counts
prop_treated <- GSE105083_MIA_PACA2_24h_high_MFE_TX_counts_MIA_PACA2_CM03_24h_CT / GSE105083_MIA_PACA2_24h_MIA_PACA2_CM03_24h_total_counts$total_counts

pooled_prop <- (GSE105083_MIA_PACA2_24h_high_MFE_TX_counts_control_CT + GSE105083_MIA_PACA2_24h_high_MFE_TX_counts_MIA_PACA2_CM03_24h_CT) /
  (GSE105083_MIA_PACA2_24h_control_total_counts$total_counts + GSE105083_MIA_PACA2_24h_MIA_PACA2_CM03_24h_total_counts$total_counts)

se <- sqrt(pooled_prop * (1 - pooled_prop) * (1 / GSE105083_MIA_PACA2_24h_control_total_counts$total_counts + 1 / GSE105083_MIA_PACA2_24h_MIA_PACA2_CM03_24h_total_counts$total_counts))

z_stat <- (prop_control - prop_treated) / se

GSE105083_MIA_PACA2_24h_z_test_counts_75_p_value <- 2 * pnorm(-abs(z_stat))

cat("GSE105083_MIA_PACA2_24h Two-proportion Z-test p-value: ", GSE105083_MIA_PACA2_24h_z_test_counts_75_p_value, "\n")

