                GSM3702795, GSM3702796, GSM3702797, GSM3702798, GSM3702799, GSM3702800, Normalized_MFE) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_res_GSE129221_PC9$ensembl_transcript_id)

quantile_075_GSE129221_PC9_norm_TX_counts_MFE_df <- quantile(GSE129221_PC9_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

GSE129221_PC9_high_MFE_TX <- dplyr::filter(GSE129221_PC9_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE129221_PC9_norm_TX_counts_MFE_df)

GSE129221_PC9_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE129221_PC9_UP, ensembl_transcript_id_version %in% GSE129221_PC9_high_MFE_TX$ensembl_transcript_id_version)
GSE129221_PC9_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE129221_PC9_DOWN, ensembl_transcript_id_version %in% GSE129221_PC9_high_MFE_TX$ensembl_transcript_id_version)

GSE129221_PC9_total_UP <- nrow(MFE_res_GSE129221_PC9_UP)
GSE129221_PC9_total_DOWN <- nrow(MFE_res_GSE129221_PC9_DOWN)

GSE129221_PC9_count_high_MFE_UP <- nrow(GSE129221_PC9_high_MFE_TX_in_UP)
GSE129221_PC9_count_high_MFE_DOWN <- nrow(GSE129221_PC9_high_MFE_TX_in_DOWN)

GSE129221_PC9_high_MFE_in_UP_fraction <- GSE129221_PC9_count_high_MFE_UP / GSE129221_PC9_total_UP
GSE129221_PC9_high_MFE_in_DOWN_fraction <- GSE129221_PC9_count_high_MFE_DOWN / GSE129221_PC9_total_DOWN

pooled_prop <- (GSE129221_PC9_count_high_MFE_UP + GSE129221_PC9_count_high_MFE_DOWN) /
  (GSE129221_PC9_total_UP + GSE129221_PC9_total_DOWN)

se <- sqrt(pooled_prop * (1 - pooled_prop) * (1 / GSE129221_PC9_total_UP + 1 / GSE129221_PC9_total_DOWN))

z_stat <- (GSE129221_PC9_high_MFE_in_UP_fraction - GSE129221_PC9_high_MFE_in_DOWN_fraction) / se

GSE129221_PC9_z_test_MFE_p_value <- 2 * pnorm(-abs(z_stat))

cat("Two-proportion Z-test p-value:", GSE129221_PC9_z_test_MFE_p_value, "\n")
cat("Z-statistic for the test:", z_stat, "\n")

cat("Fraction of high MFE TX in UP-regulated genes:", GSE129221_PC9_high_MFE_in_UP_fraction, "\n")
cat("Fraction of high MFE TX in DOWN-regulated genes:", GSE129221_PC9_high_MFE_in_DOWN_fraction, "\n")
cat("Mean of high MFE TX in UP-regulated genes:", mean(GSE129221_PC9_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of high MFE TX in DOWN-regulated genes:", mean(GSE129221_PC9_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of high MFE TX in UP-regulated genes:", calculate_mode(GSE129221_PC9_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of high MFE TX in DOWN-regulated genes:", calculate_mode(GSE129221_PC9_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")

MFE_res_GSE129221_PC9$above_quantile_075 <- MFE_res_GSE129221_PC9$Normalized_MFE > quantile_075_GSE129221_PC9_norm_TX_counts_MFE_df

ggplot(MFE_res_GSE129221_PC9, aes(x = factor(log2FoldChange > 0), y = Normalized_MFE)) +
  geom_violin(fill = "white") +
  geom_jitter(aes(color = above_quantile_075), width = 0.1, size = 1, alpha = 0.1) +
  scale_color_manual(values = c("FALSE" = "black", "TRUE" = "blue")) +
  theme_classic() +
  theme(
    legend.position = "none",
    axis.title = element_text(size = 20),
    plot.title = element_text(size = 10),
    axis.text.x = element_text(size = 16, color = "black")
  ) +
  geom_vline(xintercept = 0, linewidth = 0.3) +
  labs(
    y = "Normalized_MFE",
    x = NULL,
    title = "GSE129221_PC9_Log2_FC_adj.P<0.05"
  ) +
  scale_x_discrete(labels = c("log2FoldChange < 0", "log2FoldChange > 0"))

