p_control_low <- GSE129221_PC9GR_control_low_MFE_TX_counts_fraction
p_apatinib_low <- GSE129221_PC9GR_apatinib_low_MFE_TX_counts_fraction

pooled_prop_low <- (GSE129221_PC9GR_control_low_MFE_TX_counts$total_counts_low_MFE_TX + GSE129221_PC9GR_apatinib_low_MFE_TX_counts$total_counts_low_MFE_TX) /
  (GSE129221_PC9GR_control_total_counts$total_counts + GSE129221_PC9GR_apatinib_total_counts$total_counts)

se_low <- sqrt(pooled_prop_low * (1 - pooled_prop_low) *
                 (1 / GSE129221_PC9GR_control_total_counts$total_counts + 1 / GSE129221_PC9GR_apatinib_total_counts$total_counts))

z_stat_low <- (p_control_low - p_apatinib_low) / se_low

GSE129221_PC9GR_z_test_counts_25_p_value <- 2 * pnorm(-abs(z_stat_low))

cat("Two-proportion Z-test p-value for low MFE TX counts in Control vs apatinib:", GSE129221_PC9GR_z_test_counts_25_p_value, "\n")
cat("Z-statistic for low MFE TX counts in Control vs apatinib:", z_stat_low, "\n")

