ks_test_MFE_075_above <- ks.test(MFE_res_GSE62056_CPI360_UP$Normalized_MFE[MFE_res_GSE62056_CPI360_UP$Normalized_MFE >= quantile_075_MFE_res_GSE62056_CPI360_UP],
