  dplyr::filter(ensembl_transcript_id_version %in% GSE135514_Das_72h_low_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_low_MFE_TX = sum(avg_counts))

GSE135514_Das_72h_control_low_MFE_TX_counts_fraction <- GSE135514_Das_72h_control_low_MFE_TX_counts$total_counts_low_MFE_TX / GSE135514_Das_72h_control_total_counts$total_counts
print(GSE135514_Das_72h_control_low_MFE_TX_counts_fraction)

GSE135514_Das_72h_total_counts <- dplyr::filter(GSE135514_Das_72h_norm_TX_aggregated_data_avg_counts, condition == "Das_72h") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE135514_Das_72h_low_MFE_TX_counts <- dplyr::filter(GSE135514_Das_72h_norm_TX_aggregated_data_avg_counts, condition == "Das_72h") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE135514_Das_72h_low_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_low_MFE_TX = sum(avg_counts))

GSE135514_Das_72h_low_MFE_TX_counts_fraction <- GSE135514_Das_72h_low_MFE_TX_counts$total_counts_low_MFE_TX / GSE135514_Das_72h_total_counts$total_counts
print(GSE135514_Das_72h_low_MFE_TX_counts_fraction)

p_control_low <- GSE135514_Das_72h_control_low_MFE_TX_counts_fraction
p_Das_72h_low <- GSE135514_Das_72h_low_MFE_TX_counts_fraction

pooled_prop_low <- (GSE135514_Das_72h_control_low_MFE_TX_counts$total_counts_low_MFE_TX + GSE135514_Das_72h_low_MFE_TX_counts$total_counts_low_MFE_TX) /
  (GSE135514_Das_72h_control_total_counts$total_counts + GSE135514_Das_72h_total_counts$total_counts)

se_low <- sqrt(pooled_prop_low * (1 - pooled_prop_low) * (1 / GSE135514_Das_72h_control_total_counts$total_counts + 1 / GSE135514_Das_72h_total_counts$total_counts))

z_stat_low <- (p_control_low - p_Das_72h_low) / se_low

GSE135514_Das_72h_z_test_counts_25_p_value <- 2 * pnorm(-abs(z_stat_low))

cat("Two-proportion Z-test p-value for low MFE TX counts in Control vs Das_72h:", GSE135514_Das_72h_z_test_counts_25_p_value, "\n")
cat("Z-statistic for low MFE TX counts in Control vs Das_72h:", z_stat_low, "\n")

cat("Fraction of low MFE TX in Control:", p_control_low, "\n")
cat("Fraction of low MFE TX in Das_72h:", p_Das_72h_low, "\n")

cat("Net change in low MFE TX counts (Das_72h vs Control):", p_Das_72h_low - p_control_low, "\n")

