GSE143462_TPM_file <- file.path(input_dir, "GSE143462_TranscriptLevel_TPM_data.csv")

if (!file.exists(GSE143462_TPM_file)) {
  stop(
    "The GSE143462 transcript-level TPM file was not found at:\n",
    GSE143462_TPM_file
  )
}

GSE143462_TranscriptLevel_TPM_raw <- read.csv(
  GSE143462_TPM_file,
  header = TRUE,
  stringsAsFactors = FALSE,
  check.names = FALSE
)

GSE143462_TPM_original_ID_column <-
  colnames(GSE143462_TranscriptLevel_TPM_raw)[1]

colnames(GSE143462_TranscriptLevel_TPM_raw)[1] <-
  "GREIN_transcript_id"

GSE143462_omipalisib_12h_control_samples <- c(
  "GSM4259875",
  "GSM4259876",
  "GSM4259877"
)

GSE143462_omipalisib_12h_treatment_samples <- c(
  "GSM4259878",
  "GSM4259879",
  "GSM4259880"
)

GSE143462_omipalisib_12h_required_samples <- c(
  GSE143462_omipalisib_12h_control_samples,
  GSE143462_omipalisib_12h_treatment_samples
)

GSE143462_generic_TPM_columns <- paste0(
  "X",
  1:6
)

if (
  !all(
    GSE143462_omipalisib_12h_required_samples %in%
    colnames(GSE143462_TranscriptLevel_TPM_raw)
  )
) {

  if (
    !all(
      GSE143462_generic_TPM_columns %in%
      colnames(GSE143462_TranscriptLevel_TPM_raw)
    )
  ) {
    stop(
      paste0(
        "The GSE143462 TPM file contains neither the required GSM headers ",
        "nor the expected generic X1-X6 headers."
      )
    )
  }

  GSE143462_raw_counts_for_TPM_mapping <- read.csv(
    file.path(input_dir, "GSE143462_TranscriptLevel_Raw_data.csv"),
    header = TRUE,
    stringsAsFactors = FALSE,
    check.names = FALSE
  )

  colnames(GSE143462_raw_counts_for_TPM_mapping)[1] <-
    "GREIN_transcript_id"

  if (
    !all(
      GSE143462_omipalisib_12h_required_samples %in%
      colnames(GSE143462_raw_counts_for_TPM_mapping)
    )
  ) {
    stop(
      "The six required GSM samples are missing from the raw-count file."
    )
  }

  if (
    anyDuplicated(
      GSE143462_TranscriptLevel_TPM_raw$
      GREIN_transcript_id
    ) > 0
  ) {
    stop(
      "Duplicated transcript identifiers were found in the TPM file."
    )
  }

  if (
    anyDuplicated(
      GSE143462_raw_counts_for_TPM_mapping$
      GREIN_transcript_id
    ) > 0
  ) {
    stop(
      "Duplicated transcript identifiers were found in the raw-count file."
    )
  }

  GSE143462_TPM_raw_mapping_data <-
    GSE143462_TranscriptLevel_TPM_raw %>%
    dplyr::select(
      GREIN_transcript_id,
      dplyr::all_of(
        GSE143462_generic_TPM_columns
      )
    ) %>%
    dplyr::inner_join(
      GSE143462_raw_counts_for_TPM_mapping %>%
        dplyr::select(
          GREIN_transcript_id,
          dplyr::all_of(
            GSE143462_omipalisib_12h_required_samples
          )
        ),
      by = "GREIN_transcript_id"
    )

  if (nrow(GSE143462_TPM_raw_mapping_data) == 0) {
    stop(
      "No transcript identifiers matched between the TPM and raw-count files."
    )
  }

  GSE143462_TPM_for_mapping <- as.matrix(
    GSE143462_TPM_raw_mapping_data[
      GSE143462_generic_TPM_columns
    ]
  )

  GSE143462_raw_counts_for_mapping <- as.matrix(
    GSE143462_TPM_raw_mapping_data[
      GSE143462_omipalisib_12h_required_samples
    ]
  )

  storage.mode(GSE143462_TPM_for_mapping) <- "double"

  storage.mode(GSE143462_raw_counts_for_mapping) <- "double"

  if (
    anyNA(GSE143462_TPM_for_mapping) ||
    anyNA(GSE143462_raw_counts_for_mapping)
  ) {
    stop(
      "Missing values were detected during GSE143462 sample mapping."
    )
  }

  if (
    any(GSE143462_TPM_for_mapping < 0) ||
    any(GSE143462_raw_counts_for_mapping < 0)
  ) {
    stop(
      "Negative values were detected during GSE143462 sample mapping."
    )
  }

  GSE143462_TPM_detected_for_mapping <-
    GSE143462_TPM_for_mapping > 0

  GSE143462_raw_detected_for_mapping <-
    GSE143462_raw_counts_for_mapping > 0

  GSE143462_shared_detected_transcripts <-
    crossprod(
      GSE143462_TPM_detected_for_mapping,
      GSE143462_raw_detected_for_mapping
    )

  GSE143462_TPM_raw_mismatch_matrix <-
    outer(
      colSums(GSE143462_TPM_detected_for_mapping),
      colSums(GSE143462_raw_detected_for_mapping),
      "+"
    ) -
    2 * GSE143462_shared_detected_transcripts

  rownames(GSE143462_TPM_raw_mismatch_matrix) <-
    GSE143462_generic_TPM_columns

  colnames(GSE143462_TPM_raw_mismatch_matrix) <-
    GSE143462_omipalisib_12h_required_samples

  GSE143462_best_GSM_index <- apply(
    GSE143462_TPM_raw_mismatch_matrix,
    1,
    which.min
  )

  GSE143462_best_matching_GSM <- unname(
    colnames(
      GSE143462_TPM_raw_mismatch_matrix
    )[
      GSE143462_best_GSM_index
    ]
  )

  GSE143462_best_mapping_mismatches <- vapply(
    seq_len(
      nrow(GSE143462_TPM_raw_mismatch_matrix)
    ),
    function(i) {
      GSE143462_TPM_raw_mismatch_matrix[
        i,
        GSE143462_best_GSM_index[i]
      ]
    },
    numeric(1)
  )

  GSE143462_TPM_to_GSM_mapping <- data.frame(
    TPM_column =
      GSE143462_generic_TPM_columns,

    Best_matching_GSM =
      GSE143462_best_matching_GSM,

    Zero_status_mismatches =
      GSE143462_best_mapping_mismatches,

    Expected_GSM =
      GSE143462_omipalisib_12h_required_samples,

    Match_agrees_with_expected_order =
      GSE143462_best_matching_GSM ==
      GSE143462_omipalisib_12h_required_samples,

    row.names = NULL
  )

  cat("\nGSE143462 verified TPM-to-GSM mapping:\n")

  print(
    GSE143462_TPM_to_GSM_mapping,
    row.names = FALSE
  )

  if (
    length(
      unique(
        GSE143462_best_matching_GSM
      )
    ) != 6
  ) {
    stop(
      "The GSE143462 TPM-to-GSM mapping is not one-to-one."
    )
  }

  if (
    !all(
      GSE143462_best_matching_GSM ==
      GSE143462_omipalisib_12h_required_samples
    )
  ) {
    stop(
      "The verified GSE143462 TPM-to-GSM mapping does not agree with the expected sample order."
    )
  }

  if (
    !all(
      GSE143462_best_mapping_mismatches == 0
    )
  ) {
    stop(
      "The corresponding GSE143462 TPM and raw-count samples do not have identical transcript detection patterns."
    )
  }

  GSE143462_TPM_column_positions <- match(
    GSE143462_generic_TPM_columns,
    colnames(GSE143462_TranscriptLevel_TPM_raw)
  )

  colnames(GSE143462_TranscriptLevel_TPM_raw)[
    GSE143462_TPM_column_positions
  ] <- GSE143462_omipalisib_12h_required_samples
}

