GSE143462_omipalisib_12h_TPM_long <-
  GSE143462_omipalisib_12h_TPM_thermodynamic %>%
  tidyr::pivot_longer(
    cols = dplyr::all_of(
      GSE143462_omipalisib_12h_required_samples
    ),
    names_to = "Sample",
    values_to = "TPM"
  ) %>%
  dplyr::mutate(
    Dataset = "GSE143462",

    Treatment = "Omipalisib 12h",

    Condition = dplyr::case_when(
      Sample %in%
        GSE143462_omipalisib_12h_control_samples ~
        "Control",

      Sample %in%
        GSE143462_omipalisib_12h_treatment_samples ~
        "Omipalisib",

      TRUE ~ NA_character_
    ),

    TPM = as.numeric(TPM)
  ) %>%
  dplyr::filter(
    !is.na(Condition),
    is.finite(TPM),
    TPM >= 0
  ) %>%
  dplyr::group_by(
    Sample,
    Condition
  ) %>%
  dplyr::mutate(
    retained_TPM_MFE = sum(
      ifelse(
        is.finite(Normalized_MFE),
        TPM,
        0
      )
    ),

    relative_transcript_abundance_MFE = ifelse(
      is.finite(Normalized_MFE),
      TPM / retained_TPM_MFE,
      NA_real_
    ),

    TPM_weighted_DGfold_contribution = ifelse(
      is.finite(Normalized_MFE),
      relative_transcript_abundance_MFE *
        Normalized_MFE,
      NA_real_
    )

) %>%
  dplyr::ungroup() %>%
  dplyr::mutate(
    Condition = factor(
      Condition,
      levels = c(
        "Control",
        "Omipalisib"
      )
    )
  )

GSE143462_omipalisib_12h_TPM_weight_validation <-
  GSE143462_omipalisib_12h_TPM_long %>%
  dplyr::group_by(
    Dataset,
    Treatment,
    Sample,
    Condition
  ) %>%
  dplyr::summarise(
    annotated_transcripts =
      dplyr::n_distinct(
        ensembl_transcript_id
      ),

    expressed_annotated_transcripts =
      dplyr::n_distinct(
        ensembl_transcript_id[TPM > 0]
      ),

    retained_TPM_MFE =
      dplyr::first(
        retained_TPM_MFE
      ),

    sum_MFE_weights = sum(
      relative_transcript_abundance_MFE,
      na.rm = TRUE
    ),

    TPM_weighted_Normalized_MFE = sum(
      TPM_weighted_DGfold_contribution,
      na.rm = TRUE
    ),

    .groups = "drop"
  )

if (
  any(
    abs(
