MFE_res_GSE143462_UP <- dplyr::filter(MFE_res_GSE143462, log2FoldChange > 0)
Mean_MFE_res_GSE143462_UP <- mean(MFE_res_GSE143462_UP$Normalized_MFE)

MFE_res_GSE143462_DOWN <- dplyr::filter(MFE_res_GSE143462, log2FoldChange < 0)
Mean_MFE_res_GSE143462_DOWN <- mean(MFE_res_GSE143462_DOWN$Normalized_MFE)

TTEST_MFE_res_GSE143462_all_UP_vs_DOWN <- t.test(MFE_res_GSE143462_DOWN$Normalized_MFE, MFE_res_GSE143462_UP$Normalized_MFE, paired=FALSE)

ks_test_res_GSE143462_all_UP_vs_DOWN <- ks.test(MFE_res_GSE143462_DOWN$Normalized_MFE, MFE_res_GSE143462_UP$Normalized_MFE)

quantile_075_MFE_res_GSE143462_UP <- quantile(MFE_res_GSE143462_UP$Normalized_MFE, probs = c(0.75))
quantile_075_MFE_res_GSE143462_DOWN <- quantile(MFE_res_GSE143462_DOWN$Normalized_MFE, probs = c(0.75))
ks_test_MFE_075_above <- ks.test(MFE_res_GSE143462_UP$Normalized_MFE[MFE_res_GSE143462_UP$Normalized_MFE >= quantile_075_MFE_res_GSE143462_UP],
                                 MFE_res_GSE143462_DOWN$Normalized_MFE[MFE_res_GSE143462_DOWN$Normalized_MFE >= quantile_075_MFE_res_GSE143462_DOWN])

quantile_025_MFE_res_GSE143462_UP <- quantile(MFE_res_GSE143462_UP$Normalized_MFE, probs = c(0.25))
quantile_025_MFE_res_GSE143462_DOWN <- quantile(MFE_res_GSE143462_DOWN$Normalized_MFE, probs = c(0.25))
ks_test_MFE_025_below <- ks.test(MFE_res_GSE143462_UP$Normalized_MFE[MFE_res_GSE143462_UP$Normalized_MFE <= quantile_025_MFE_res_GSE143462_UP],
                                 MFE_res_GSE143462_DOWN$Normalized_MFE[MFE_res_GSE143462_DOWN$Normalized_MFE <= quantile_025_MFE_res_GSE143462_DOWN])

upregulated <- data.frame(MFE = MFE_res_GSE143462_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_res_GSE143462_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

GSE143462_observed_diff <- mean(MFE_res_GSE143462_UP$Normalized_MFE) - mean(MFE_res_GSE143462_DOWN$Normalized_MFE)

n_permutations <- 10000

GSE143462_permuted_diffs <- numeric(n_permutations)

set.seed(123)
for (i in 1:n_permutations) {
  permuted_labels <- sample(combined_data$Group)

  permuted_up_mean <- mean(combined_data$MFE[permuted_labels == "Up"])
  permuted_down_mean <- mean(combined_data$MFE[permuted_labels == "Down"])

  GSE143462_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

GSE143462_p_value <- (sum(abs(GSE143462_permuted_diffs) >= abs(GSE143462_observed_diff)) + 1) / (n_permutations + 1)

cat("Observed difference in GSE143462 means MFE_UP - MFE_DOWN:", GSE143462_observed_diff, "\n")
cat("GSE143462 P-value from permutation test:", GSE143462_p_value, "\n")

GSE143462_norm_TX_counts <- counts(dds_GSE143462, normalized=TRUE)
GSE143462_norm_TX_counts_df <- as.data.frame(GSE143462_norm_TX_counts)
GSE143462_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE143462_norm_TX_counts_df)
rownames(GSE143462_norm_TX_counts_df) <- NULL

GSE143462_norm_TX_counts_df <- GSE143462_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE143462_norm_TX_counts_df), "ensembl_transcript_id"))]

GSE143462_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE143462_norm_TX_counts_df$ensembl_transcript_id)

GSE143462_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE143462_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length,
                GSM4259875, GSM4259876, GSM4259877, GSM4259878, GSM4259879, GSM4259880,
                Normalized_MFE)

GSE143462_norm_TX_counts_MFE_df <- dplyr::select(GSE143462_norm_TX_counts_MFE_df, ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length,
                                                 GSM4259875, GSM4259876, GSM4259877, GSM4259878, GSM4259879, GSM4259880, Normalized_MFE) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_res_GSE143462$ensembl_transcript_id)

quantile_075_GSE143462_norm_TX_counts_MFE_df <- quantile(GSE143462_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

GSE143462_high_MFE_TX <- dplyr::filter(GSE143462_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE143462_norm_TX_counts_MFE_df)

GSE143462_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE143462_UP, ensembl_transcript_id_version %in% GSE143462_high_MFE_TX$ensembl_transcript_id_version)
GSE143462_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE143462_DOWN, ensembl_transcript_id_version %in% GSE143462_high_MFE_TX$ensembl_transcript_id_version)

GSE143462_total_UP <- nrow(MFE_res_GSE143462_UP)
GSE143462_total_DOWN <- nrow(MFE_res_GSE143462_DOWN)

GSE143462_count_high_MFE_UP <- nrow(GSE143462_high_MFE_TX_in_UP)
GSE143462_count_high_MFE_DOWN <- nrow(GSE143462_high_MFE_TX_in_DOWN)

p_UP_high <- GSE143462_count_high_MFE_UP / GSE143462_total_UP
p_DOWN_high <- GSE143462_count_high_MFE_DOWN / GSE143462_total_DOWN

pooled_prop_high <- (GSE143462_count_high_MFE_UP + GSE143462_count_high_MFE_DOWN) /
  (GSE143462_total_UP + GSE143462_total_DOWN)

se_high <- sqrt(pooled_prop_high * (1 - pooled_prop_high) *
                  (1 / GSE143462_total_UP + 1 / GSE143462_total_DOWN))

z_stat_high <- (p_UP_high - p_DOWN_high) / se_high

GSE143462_z_test_MFE_p_value <- 2 * pnorm(-abs(z_stat_high))

cat("Two-proportion Z-test p-value for high MFE TX in UP vs DOWN-regulated genes:", GSE143462_z_test_MFE_p_value, "\n")
cat("Z-statistic for high MFE TX in UP vs DOWN-regulated genes:", z_stat_high, "\n")

GSE143462_high_MFE_in_UP_fraction <- GSE143462_count_high_MFE_UP / GSE143462_total_UP
GSE143462_high_MFE_in_DOWN_fraction <- GSE143462_count_high_MFE_DOWN / GSE143462_total_DOWN

cat("Fraction of GSE143462 high MFE TX in UP-regulated genes:", GSE143462_high_MFE_in_UP_fraction, "\n")
cat("Fraction of GSE143462 high MFE TX in DOWN-regulated genes:", GSE143462_high_MFE_in_DOWN_fraction, "\n")
cat("Mean of GSE143462 high MFE TX in UP-regulated genes:", mean(GSE143462_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of GSE143462 high MFE TX in DOWN-regulated genes:", mean(GSE143462_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of GSE143462 high MFE TX in UP-regulated genes:", calculate_mode(GSE143462_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of GSE143462 high MFE TX in DOWN-regulated genes:", calculate_mode(GSE143462_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")

MFE_res_GSE143462$above_quantile_075 <- MFE_res_GSE143462$Normalized_MFE > quantile_075_GSE143462_norm_TX_counts_MFE_df

Plot_MFE_GSE143462 <- ggplot(MFE_res_GSE143462, aes(x = factor(log2FoldChange > 0), y = Normalized_MFE)) +
  geom_violin(fill = "white", size = 1.5) +
  geom_jitter(aes(color = above_quantile_075), width = 0.1, size = 1, alpha = 1) +
  scale_color_manual(values = c("FALSE" = "black", "TRUE" = "dodgerblue3")) +
  theme_classic() +
  ylim(-0.6, 0) +
  theme(
    legend.position = "none",
    axis.title = element_text(size = 20),
    plot.title = element_text(size = 10),
    axis.text.x = element_text(size = 16, color = "black")
  ) +
  geom_vline(xintercept = 0, linewidth = 0.3) +
  labs(
    y = "Normalized_MFE",
    x = NULL,
    title = "GSE143462_Log2_FC_adj.P<0.05"
  ) +
  scale_x_discrete(labels = c("log2_FC < 0", "log2_FC > 0"))

print(Plot_MFE_GSE143462)

GSE143462_long_data <- GSE143462_norm_TX_counts_MFE_df %>%
  pivot_longer(
    cols = starts_with("GSM"),
    names_to = "replicate",
    values_to = "counts"
  )

GSE143462_long_data <- GSE143462_long_data %>%
  mutate(condition = ifelse(replicate %in% c("GSM4259875", "GSM4259876", "GSM4259877"), "Control", "Omipalisib"))

GSE143462_norm_TX_aggregated_data_avg_counts <- GSE143462_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE) %>%
  summarise(
    avg_counts = mean(counts),
    .groups = 'drop'
  )

GSE143462_MFE_all_TX_75_percentile <- quantile(GSE143462_norm_TX_aggregated_data_avg_counts$Normalized_MFE, 0.75)

GSE143462_high_MFE_TX_total <- dplyr::filter(GSE143462_norm_TX_counts_MFE_df, Normalized_MFE > GSE143462_MFE_all_TX_75_percentile)

GSE143462_control_total_counts <- dplyr::filter(GSE143462_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE143462_control_high_MFE_TX_counts <- dplyr::filter(GSE143462_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE143462_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE143462_control_high_MFE_TX_counts_fraction <- GSE143462_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE143462_control_total_counts$total_counts
print(GSE143462_control_high_MFE_TX_counts_fraction)

GSE143462_Omipalisib_total_counts <- dplyr::filter(GSE143462_norm_TX_aggregated_data_avg_counts, condition == "Omipalisib") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE143462_Omipalisib_high_MFE_TX_counts <- dplyr::filter(GSE143462_norm_TX_aggregated_data_avg_counts, condition == "Omipalisib") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE143462_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE143462_Omipalisib_high_MFE_TX_counts_fraction <- GSE143462_Omipalisib_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE143462_Omipalisib_total_counts$total_counts
print(GSE143462_Omipalisib_high_MFE_TX_counts_fraction)

p_control_high <- GSE143462_control_high_MFE_TX_counts_fraction
p_omipalisib_high <- GSE143462_Omipalisib_high_MFE_TX_counts_fraction

pooled_prop_high <- (GSE143462_control_high_MFE_TX_counts$total_counts_high_MFE_TX + GSE143462_Omipalisib_high_MFE_TX_counts$total_counts_high_MFE_TX) /
  (GSE143462_control_total_counts$total_counts + GSE143462_Omipalisib_total_counts$total_counts)

se_high <- sqrt(pooled_prop_high * (1 - pooled_prop_high) *
                  (1 / GSE143462_control_total_counts$total_counts + 1 / GSE143462_Omipalisib_total_counts$total_counts))

z_stat_high <- (p_control_high - p_omipalisib_high) / se_high

GSE143462_z_test_counts_75_p_value <- 2 * pnorm(-abs(z_stat_high))

cat("Two-proportion Z-test p-value for high MFE TX counts in Control vs Omipalisib:", GSE143462_z_test_counts_75_p_value, "\n")
cat("Z-statistic for high MFE TX counts in Control vs Omipalisib:", z_stat_high, "\n")

