summary(res_GSE130161)

plotMA(res_GSE130161,alpha = 0.05)
abline(h=c(-2,2),col = "red")

res_GSE130161_df <- data.frame(res_GSE130161)
res_GSE130161 <- tibble::rownames_to_column(res_GSE130161_df, "ensembl_transcript_id")

MFE_res_GSE130161 <- dplyr::inner_join(Table_ANNOTATED, res_GSE130161, by="ensembl_transcript_id") %>%
  dplyr::filter(padj < 0.05)

Plot_GSE130161 <- ggplot(MFE_res_GSE130161, aes(y=Normalized_MFE, x=log2FoldChange)) +
  geom_point(size=1.5, alpha=0.05)+
  theme_classic() +
  theme(legend.position="none") +
  geom_vline(xintercept = 0, size=0.3) +
  theme(axis.title = element_text(size = 20)) +
  theme(plot.title = element_text(size = 15)) +
  labs(y="DGfold / nt (kcal/mol)",x="Log2_FC_expression",title="GSE130161_Log2_FC_adj.P<0.05")
print(Plot_GSE130161)

ggsave("Plot_GSE130161.pdf", plot = Plot_GSE130161, path = output_dir)

MFE_res_GSE130161_UP <- dplyr::filter(MFE_res_GSE130161, log2FoldChange > 0)
Mean_MFE_res_GSE130161_UP <- mean(MFE_res_GSE130161_UP$Normalized_MFE)

MFE_res_GSE130161_DOWN <- dplyr::filter(MFE_res_GSE130161, log2FoldChange < 0)
Mean_MFE_res_GSE130161_DOWN <- mean(MFE_res_GSE130161_DOWN$Normalized_MFE)

TTEST_MFE_res_GSE130161_all_UP_vs_DOWN <- t.test(MFE_res_GSE130161_DOWN$Normalized_MFE, MFE_res_GSE130161_UP$Normalized_MFE, paired=FALSE)

ks_test_res_GSE130161_all_UP_vs_DOWN <- ks.test(MFE_res_GSE130161_DOWN$Normalized_MFE, MFE_res_GSE130161_UP$Normalized_MFE)

quantile_075_MFE_res_GSE130161_UP <- quantile(MFE_res_GSE130161_UP$Normalized_MFE, probs = c(0.75))
quantile_075_MFE_res_GSE130161_DOWN <- quantile(MFE_res_GSE130161_DOWN$Normalized_MFE, probs = c(0.75))
ks_test_MFE_075_above <- ks.test(MFE_res_GSE130161_UP$Normalized_MFE[MFE_res_GSE130161_UP$Normalized_MFE >= quantile_075_MFE_res_GSE130161_UP],
                                 MFE_res_GSE130161_DOWN$Normalized_MFE[MFE_res_GSE130161_DOWN$Normalized_MFE >= quantile_075_MFE_res_GSE130161_DOWN])

quantile_025_MFE_res_GSE130161_UP <- quantile(MFE_res_GSE130161_UP$Normalized_MFE, probs = c(0.25))
quantile_025_MFE_res_GSE130161_DOWN <- quantile(MFE_res_GSE130161_DOWN$Normalized_MFE, probs = c(0.25))
ks_test_MFE_025_below <- ks.test(MFE_res_GSE130161_UP$Normalized_MFE[MFE_res_GSE130161_UP$Normalized_MFE <= quantile_025_MFE_res_GSE130161_UP],
                                 MFE_res_GSE130161_DOWN$Normalized_MFE[MFE_res_GSE130161_DOWN$Normalized_MFE <= quantile_025_MFE_res_GSE130161_DOWN])

upregulated <- data.frame(MFE = MFE_res_GSE130161_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_res_GSE130161_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

GSE130161_observed_diff <- mean(MFE_res_GSE130161_UP$Normalized_MFE) - mean(MFE_res_GSE130161_DOWN$Normalized_MFE)

n_permutations <- 10000

GSE130161_permuted_diffs <- numeric(n_permutations)

set.seed(123)
for (i in 1:n_permutations) {
  permuted_labels <- sample(combined_data$Group)

  permuted_up_mean <- mean(combined_data$MFE[permuted_labels == "Up"])
  permuted_down_mean <- mean(combined_data$MFE[permuted_labels == "Down"])

  GSE130161_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

GSE130161_p_value <- (sum(abs(GSE130161_permuted_diffs) >= abs(GSE130161_observed_diff)) + 1) / (n_permutations + 1)

cat("Observed difference in GSE130161 means MFE_UP - MFE_DOWN:", GSE130161_observed_diff, "\n")
cat("GSE130161 P-value from permutation test:", GSE130161_p_value, "\n")

GSE130161_norm_TX_counts <- counts(dds_GSE130161, normalized=TRUE)
GSE130161_norm_TX_counts_df <- as.data.frame(GSE130161_norm_TX_counts)
GSE130161_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE130161_norm_TX_counts_df)
rownames(GSE130161_norm_TX_counts_df) <- NULL

GSE130161_norm_TX_counts_df <- GSE130161_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE130161_norm_TX_counts_df), "ensembl_transcript_id"))]

GSE130161_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE130161_norm_TX_counts_df$ensembl_transcript_id)

GSE130161_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE130161_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length,
                GSM3733269, GSM3733270, GSM3733271, GSM3733272, GSM3733273, GSM3733274, GSM3733275, GSM3733276,
                Normalized_MFE)

quantile_075_GSE130161_norm_TX_counts_MFE_df <- quantile(GSE130161_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

GSE130161_high_MFE_TX <- dplyr::filter(GSE130161_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE130161_norm_TX_counts_MFE_df)

GSE130161_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE130161_UP, ensembl_transcript_id_version %in% GSE130161_high_MFE_TX$ensembl_transcript_id_version)
GSE130161_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE130161_DOWN, ensembl_transcript_id_version %in% GSE130161_high_MFE_TX$ensembl_transcript_id_version)

GSE130161_total_UP <- nrow(MFE_res_GSE130161_UP)
GSE130161_total_DOWN <- nrow(MFE_res_GSE130161_DOWN)

GSE130161_count_high_MFE_UP <- nrow(GSE130161_high_MFE_TX_in_UP)
GSE130161_count_high_MFE_DOWN <- nrow(GSE130161_high_MFE_TX_in_DOWN)

p_UP_high <- GSE130161_count_high_MFE_UP / GSE130161_total_UP
p_DOWN_high <- GSE130161_count_high_MFE_DOWN / GSE130161_total_DOWN

pooled_prop <- (GSE130161_count_high_MFE_UP + GSE130161_count_high_MFE_DOWN) /
  (GSE130161_total_UP + GSE130161_total_DOWN)

se <- sqrt(pooled_prop * (1 - pooled_prop) *
             (1 / GSE130161_total_UP + 1 / GSE130161_total_DOWN))

z_stat <- (p_UP_high - p_DOWN_high) / se

GSE130161_z_test_MFE_p_value <- 2 * pnorm(-abs(z_stat))

cat("Two-proportion Z-test p-value for high MFE TX between UP-regulated and DOWN-regulated genes:", GSE130161_z_test_MFE_p_value, "\n")
cat("Z-statistic for high MFE TX between UP-regulated and DOWN-regulated genes:", z_stat, "\n")

GSE130161_high_MFE_in_UP_fraction <- GSE130161_count_high_MFE_UP / GSE130161_total_UP
GSE130161_high_MFE_in_DOWN_fraction <- GSE130161_count_high_MFE_DOWN / GSE130161_total_DOWN

cat("Fraction of GSE130161 high MFE TX in UP-regulated genes:", GSE130161_high_MFE_in_UP_fraction, "\n")
cat("Fraction of GSE130161 high MFE TX in DOWN-regulated genes:", GSE130161_high_MFE_in_DOWN_fraction, "\n")
