quantile_075_GSE185141_norm_TX_counts_MFE_df <- quantile(GSE185141_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

GSE185141_high_MFE_TX <- dplyr::filter(GSE185141_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE185141_norm_TX_counts_MFE_df)

GSE185141_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE185141_UP, ensembl_transcript_id_version %in% GSE185141_high_MFE_TX$ensembl_transcript_id_version)
GSE185141_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE185141_DOWN, ensembl_transcript_id_version %in% GSE185141_high_MFE_TX$ensembl_transcript_id_version)

GSE185141_total_UP <- nrow(MFE_res_GSE185141_UP)
GSE185141_total_DOWN <- nrow(MFE_res_GSE185141_DOWN)
GSE185141_count_high_MFE_UP <- nrow(GSE185141_high_MFE_TX_in_UP)
GSE185141_count_high_MFE_DOWN <- nrow(GSE185141_high_MFE_TX_in_DOWN)

GSE185141_counts_contingency_table <- matrix(c(GSE185141_count_high_MFE_UP, GSE185141_total_UP - GSE185141_count_high_MFE_UP,
                                               GSE185141_count_high_MFE_DOWN, GSE185141_total_DOWN - GSE185141_count_high_MFE_DOWN),
                                             nrow = 2, byrow = TRUE,
                                             dimnames = list(UP = c("UP-regulated", "DOWN-regulated"),
                                                             DOWN = c("High MFE TX", "Not High MFE TX")))

GSE185141_fisher_result <- fisher.test(GSE185141_counts_contingency_table)
cat("GSE185141 P-value from Fisher test:", GSE185141_fisher_result$p.value, "\n")

GSE185141_high_MFE_in_UP_fraction <- GSE185141_count_high_MFE_UP / GSE185141_total_UP
GSE185141_high_MFE_in_DOWN_fraction <- GSE185141_count_high_MFE_DOWN / GSE185141_total_DOWN

cat("Fraction of GSE185141 high MFE TX in UP-regulated genes:", GSE185141_high_MFE_in_UP_fraction, "\n")
cat("Fraction of GSE185141 high MFE TX in DOWN-regulated genes:", GSE185141_high_MFE_in_DOWN_fraction, "\n")

pooled_prop <- (GSE185141_count_high_MFE_UP + GSE185141_count_high_MFE_DOWN) / (GSE185141_total_UP + GSE185141_total_DOWN)

se <- sqrt(pooled_prop * (1 - pooled_prop) * (1 / GSE185141_total_UP + 1 / GSE185141_total_DOWN))

z_stat <- (GSE185141_high_MFE_in_UP_fraction - GSE185141_high_MFE_in_DOWN_fraction) / se

GSE185141_z_test_MFE_p_value <- 2 * pnorm(-abs(z_stat))

cat("Two-proportion Z-test p-value for high MFE TX between UP-regulated and DOWN-regulated conditions:", GSE185141_z_test_MFE_p_value, "\n")
cat("Z-statistic for high MFE TX between UP-regulated and DOWN-regulated conditions:", z_stat, "\n")

cat("Mean of GSE185141 high MFE TX in UP-regulated genes:", mean(GSE185141_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of GSE185141 high MFE TX in DOWN-regulated genes:", mean(GSE185141_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of GSE185141 high MFE TX in UP-regulated genes:", calculate_mode(GSE185141_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of GSE185141 high MFE TX in DOWN-regulated genes:", calculate_mode(GSE185141_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")

MFE_res_GSE185141$above_quantile_075 <- MFE_res_GSE185141$Normalized_MFE > quantile_075_GSE185141_norm_TX_counts_MFE_df

ggplot(MFE_res_GSE185141, aes(x = factor(log2FoldChange > 0), y = Normalized_MFE)) +
  geom_violin(fill = "white") +
  geom_jitter(aes(color = above_quantile_075), width = 0.1, size = 1, alpha = 0.1) +
  scale_color_manual(values = c("FALSE" = "black", "TRUE" = "blue")) +
  theme_classic() +
  theme(
    legend.position = "none",
    axis.title = element_text(size = 20),
    plot.title = element_text(size = 10),
    axis.text.x = element_text(size = 16, color = "black")
  ) +
  geom_vline(xintercept = 0, linewidth = 0.3) +
  labs(
    y = "Normalized_MFE",
    x = NULL,
    title = "GSE185141_Log2_FC_adj.P<0.05"
  ) +
  scale_x_discrete(labels = c("log2FoldChange < 0", "log2FoldChange > 0"))

GSE185141_long_data <- GSE185141_norm_TX_counts_MFE_df %>%
  pivot_longer(
    cols = starts_with("GSM"),
    names_to = "replicate",
    values_to = "counts"
  )

GSE185141_long_data <- GSE185141_long_data %>%
  mutate(condition = ifelse(replicate %in% c("GSM5606949", "GSM5606950", "GSM5606951"), "Control", "Dihydroartemisinin"))

GSE185141_norm_TX_aggregated_data_avg_counts <- GSE185141_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE) %>%
  summarise(
    avg_counts = mean(counts),
    .groups = 'drop'
  )

GSE185141_MFE_all_TX_75_percentile <- quantile(GSE185141_norm_TX_aggregated_data_avg_counts$Normalized_MFE, 0.75)

GSE185141_high_MFE_TX_total <- dplyr::filter(GSE185141_norm_TX_counts_MFE_df, Normalized_MFE > GSE185141_MFE_all_TX_75_percentile)

GSE185141_control_total_counts <- dplyr::filter(GSE185141_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE185141_control_high_MFE_TX_counts <- dplyr::filter(GSE185141_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE185141_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE185141_control_high_MFE_TX_counts_fraction <- GSE185141_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE185141_control_total_counts$total_counts
cat("GSE185141 control high MFE TX as fraction of total counts:", GSE185141_control_high_MFE_TX_counts_fraction, "\n")

GSE185141_Dihydroartemisinin_total_counts <- dplyr::filter(GSE185141_norm_TX_aggregated_data_avg_counts, condition == "Dihydroartemisinin") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE185141_Dihydroartemisinin_high_MFE_TX_counts <- dplyr::filter(GSE185141_norm_TX_aggregated_data_avg_counts, condition == "Dihydroartemisinin") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE185141_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE185141_Dihydroartemisinin_high_MFE_TX_counts_fraction <- GSE185141_Dihydroartemisinin_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE185141_Dihydroartemisinin_total_counts$total_counts
cat("GSE185141 Dihydroartemisinin high MFE TX as fraction of total counts:", GSE185141_Dihydroartemisinin_high_MFE_TX_counts_fraction, "\n")

p_control <- GSE185141_control_high_MFE_TX_counts_fraction
p_dihydroartemisinin <- GSE185141_Dihydroartemisinin_high_MFE_TX_counts_fraction

n_control <- GSE185141_control_total_counts$total_counts
n_dihydroartemisinin <- GSE185141_Dihydroartemisinin_total_counts$total_counts

pooled_prop <- (GSE185141_control_high_MFE_TX_counts$total_counts_high_MFE_TX + GSE185141_Dihydroartemisinin_high_MFE_TX_counts$total_counts_high_MFE_TX) / (n_control + n_dihydroartemisinin)

se <- sqrt(pooled_prop * (1 - pooled_prop) * (1 / n_control + 1 / n_dihydroartemisinin))

z_stat <- (p_control - p_dihydroartemisinin) / se

GSE185141_z_test_counts_75_p_value <- 2 * pnorm(-abs(z_stat))

cat("Two-proportion Z-test p-value for high MFE TX between Control and Dihydroartemisinin:", GSE185141_z_test_counts_75_p_value, "\n")
cat("Z-statistic for high MFE TX between Control and Dihydroartemisinin:", z_stat, "\n")

net_change_high_MFE_TX_fraction <- GSE185141_Dihydroartemisinin_high_MFE_TX_counts_fraction - GSE185141_control_high_MFE_TX_counts_fraction
cat("GSE185141 net change in high MFE TX counts (Dihydroartemisinin vs Control):", net_change_high_MFE_TX_fraction, "\n")

