cat("\nGSE241735 retained TPM abundance by sample:\n")

GSE241735_Futibatinib_4h_TPM_long <-
  GSE241735_TPM_thermodynamic %>%
  tidyr::pivot_longer(
    cols = dplyr::all_of(
      GSE241735_Futibatinib_4h_required_samples
    ),
    names_to = "Sample",
    values_to = "TPM"
  ) %>%
  dplyr::mutate(
    Dataset = "GSE241735",

    Treatment = "Futibatinib 4h",

    Condition = dplyr::case_when(
      Sample %in%
        GSE241735_control_samples ~
        "Control",

      Sample %in%
        GSE241735_Futibatinib_4h_treatment_samples ~
        "Futibatinib 4h",

      TRUE ~ NA_character_
    ),

    TPM = as.numeric(TPM)
  ) %>%
  dplyr::filter(
    !is.na(Condition),
    is.finite(TPM),
    TPM >= 0
  ) %>%
  dplyr::group_by(
    Sample,
    Condition
  ) %>%
  dplyr::mutate(
    retained_TPM_MFE = sum(
      ifelse(
        is.finite(Normalized_MFE),
        TPM,
        0
      )
    ),

    relative_transcript_abundance_MFE = ifelse(
      is.finite(Normalized_MFE),
      TPM / retained_TPM_MFE,
      NA_real_
    ),

    TPM_weighted_DGfold_contribution = ifelse(
      is.finite(Normalized_MFE),
      relative_transcript_abundance_MFE *
        Normalized_MFE,
      NA_real_
    )

) %>%
  dplyr::ungroup() %>%
  dplyr::mutate(
    Condition = factor(
      Condition,
      levels = c(
        "Control",
        "Futibatinib 4h"
      )
    )
  )

GSE241735_Futibatinib_4h_TPM_weight_validation <-
  GSE241735_Futibatinib_4h_TPM_long %>%
  dplyr::group_by(
    Dataset,
    Treatment,
    Sample,
    Condition
  ) %>%
  dplyr::summarise(
    annotated_transcripts =
      dplyr::n_distinct(
        ensembl_transcript_id
      ),

    expressed_annotated_transcripts =
      dplyr::n_distinct(
        ensembl_transcript_id[TPM > 0]
      ),

    retained_TPM_MFE =
      dplyr::first(
        retained_TPM_MFE
      ),

    sum_MFE_weights = sum(
      relative_transcript_abundance_MFE,
      na.rm = TRUE
    ),

    TPM_weighted_Normalized_MFE = sum(
      TPM_weighted_DGfold_contribution,
      na.rm = TRUE
    ),

    .groups = "drop"
  )

if (
  any(
    abs(
      GSE241735_Futibatinib_4h_TPM_weight_validation$
      sum_MFE_weights - 1
    ) > 1e-8
  )
) {
  stop(
    "The GSE241735 futibatinib 4h TPM-derived ΔGfold weights do not sum to one."
  )
}

cat(
  "\nGSE241735 futibatinib 4h common TPM-weight validation:\n"
)

print(
  GSE241735_Futibatinib_4h_TPM_weight_validation,
  row.names = FALSE,
  digits = 10
)

