Data_GSE241735 <- getGEO(GEO = "GSE241735")

Expdata_GSE241735 <- Data_GSE241735[["GSE241735_series_matrix.txt.gz"]]@phenoData@data

Expdata_GSE241735$condition <- NA_character_
Expdata_GSE241735[c("GSM7734630", "GSM7734631", "GSM7734632"), "condition"] <- "DMSO"
Expdata_GSE241735[c("GSM7734633", "GSM7734634", "GSM7734635"), "condition"] <- "Futibatinib_4h"
Expdata_GSE241735[c("GSM7734636", "GSM7734637", "GSM7734638"), "condition"] <- "Futibatinib_12h"
Expdata_GSE241735[c("GSM7734639", "GSM7734640", "GSM7734641"), "condition"] <- "Futibatinib_24h"

Expdata_GSE241735$type <- "RNA-seq"

Expdata_GSE241735_Futibatinib_4h <- Expdata_GSE241735[c("GSM7734630", "GSM7734631", "GSM7734632", "GSM7734633", "GSM7734634", "GSM7734635"), ]
Expdata_GSE241735_Futibatinib_12h <- Expdata_GSE241735[c("GSM7734630", "GSM7734631", "GSM7734632", "GSM7734636", "GSM7734637", "GSM7734638"), ]
Expdata_GSE241735_Futibatinib_24h <- Expdata_GSE241735[c("GSM7734630", "GSM7734631", "GSM7734632", "GSM7734639", "GSM7734640", "GSM7734641"), ]

all(rownames(Expdata_GSE241735_Futibatinib_4h) %in% colnames(Counts_GSE241735_Futibatinib_4h_GREIN))
all(colnames(Counts_GSE241735_Futibatinib_4h_GREIN) %in% rownames(Expdata_GSE241735_Futibatinib_4h))

Expdata_GSE241735_Futibatinib_4h <-
  Expdata_GSE241735_Futibatinib_4h[
    colnames(Counts_GSE241735_Futibatinib_4h_GREIN),
    ,
    drop = FALSE
  ]

Expdata_GSE241735_Futibatinib_4h$condition <- factor(
  Expdata_GSE241735_Futibatinib_4h$condition,
  levels = c("DMSO", "Futibatinib_4h")
)

stopifnot(
  identical(
    rownames(Expdata_GSE241735_Futibatinib_4h),
    colnames(Counts_GSE241735_Futibatinib_4h_GREIN)
  )
)

dds_GSE241735_Futibatinib_4h <- DESeqDataSetFromMatrix(countData = Counts_GSE241735_Futibatinib_4h_GREIN,
                                                       colData = Expdata_GSE241735_Futibatinib_4h,
                                                       design = ~ condition)
dds_GSE241735_Futibatinib_4h

ntd <- normTransform(dds_GSE241735_Futibatinib_4h)
select <- order(rowMeans(counts(dds_GSE241735_Futibatinib_4h,normalized=FALSE)),
                decreasing=TRUE)[1:25]
df <- as.data.frame(colData(dds_GSE241735_Futibatinib_4h)[,c("condition","type")])
pheatmap(assay(ntd)[select,], cluster_rows=FALSE, show_rownames=FALSE,
         cluster_cols=FALSE, annotation_col=df)

vsd <- vst(dds_GSE241735_Futibatinib_4h, blind=FALSE)
head(assay(vsd), 3)

sampleDists <- dist(t(assay(vsd)))

sampleDistMatrix <- as.matrix(sampleDists)
rownames(sampleDistMatrix) <- paste(vsd$condition, vsd$type, sep="-")
colnames(sampleDistMatrix) <- NULL
colors <- colorRampPalette( rev(brewer.pal(9, "Blues")) )(255)
pheatmap(sampleDistMatrix,
         clustering_distance_rows=sampleDists,
         clustering_distance_cols=sampleDists,
         col=colors)

plotPCA(vsd, intgroup="condition")

keep <- rowSums(counts(dds_GSE241735_Futibatinib_4h)) >= 3
dds_GSE241735_Futibatinib_4h <- dds_GSE241735_Futibatinib_4h[keep,]
table(keep)
nrow(dds_GSE241735_Futibatinib_4h)

dds_GSE241735_Futibatinib_4h <- DESeq(dds_GSE241735_Futibatinib_4h)

res_GSE241735_Futibatinib_4h <- results(dds_GSE241735_Futibatinib_4h, contrast=c("condition","Futibatinib_4h","DMSO"))
res_GSE241735_Futibatinib_4h

mcols(res_GSE241735_Futibatinib_4h)$description

summary(res_GSE241735_Futibatinib_4h)

plotMA(res_GSE241735_Futibatinib_4h,alpha = 0.05)
abline(h=c(-2,2),col = "red")

res_GSE241735_Futibatinib_4h_df <- data.frame(res_GSE241735_Futibatinib_4h)
