TTEST_MFE_res_GSE241735_Futibatinib_4h_all_UP_vs_DOWN <- t.test(MFE_res_GSE241735_Futibatinib_4h_DOWN$Normalized_MFE, MFE_res_GSE241735_Futibatinib_4h_UP$Normalized_MFE, paired=FALSE)

ks_test_res_GSE241735_Futibatinib_4h_all_UP_vs_DOWN <- ks.test(MFE_res_GSE241735_Futibatinib_4h_DOWN$Normalized_MFE, MFE_res_GSE241735_Futibatinib_4h_UP$Normalized_MFE)

quantile_075_MFE_res_GSE241735_Futibatinib_4h_UP <- quantile(MFE_res_GSE241735_Futibatinib_4h_UP$Normalized_MFE, probs = c(0.75))
quantile_075_MFE_res_GSE241735_Futibatinib_4h_DOWN <- quantile(MFE_res_GSE241735_Futibatinib_4h_DOWN$Normalized_MFE, probs = c(0.75))
ks_test_MFE_GSE241735_Futibatinib_4h_075_above <- ks.test(MFE_res_GSE241735_Futibatinib_4h_UP$Normalized_MFE[MFE_res_GSE241735_Futibatinib_4h_UP$Normalized_MFE >= quantile_075_MFE_res_GSE241735_Futibatinib_4h_UP],
                                 MFE_res_GSE241735_Futibatinib_4h_DOWN$Normalized_MFE[MFE_res_GSE241735_Futibatinib_4h_DOWN$Normalized_MFE >= quantile_075_MFE_res_GSE241735_Futibatinib_4h_DOWN])

quantile_025_MFE_res_GSE241735_Futibatinib_4h_UP <- quantile(MFE_res_GSE241735_Futibatinib_4h_UP$Normalized_MFE, probs = c(0.25))
quantile_025_MFE_res_GSE241735_Futibatinib_4h_DOWN <- quantile(MFE_res_GSE241735_Futibatinib_4h_DOWN$Normalized_MFE, probs = c(0.25))
ks_test_MFE_GSE241735_Futibatinib_4h_025_below <- ks.test(MFE_res_GSE241735_Futibatinib_4h_UP$Normalized_MFE[MFE_res_GSE241735_Futibatinib_4h_UP$Normalized_MFE <= quantile_025_MFE_res_GSE241735_Futibatinib_4h_UP],
                                 MFE_res_GSE241735_Futibatinib_4h_DOWN$Normalized_MFE[MFE_res_GSE241735_Futibatinib_4h_DOWN$Normalized_MFE <= quantile_025_MFE_res_GSE241735_Futibatinib_4h_DOWN])

upregulated <- data.frame(MFE = MFE_res_GSE241735_Futibatinib_4h_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_res_GSE241735_Futibatinib_4h_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

GSE241735_Futibatinib_4h_observed_diff <- mean(MFE_res_GSE241735_Futibatinib_4h_UP$Normalized_MFE) - mean(MFE_res_GSE241735_Futibatinib_4h_DOWN$Normalized_MFE)

n_permutations <- 10000

GSE241735_Futibatinib_4h_permuted_diffs <- numeric(n_permutations)

set.seed(123)
for (i in 1:n_permutations) {
  permuted_labels <- sample(combined_data$Group)

  permuted_up_mean <- mean(combined_data$MFE[permuted_labels == "Up"])
  permuted_down_mean <- mean(combined_data$MFE[permuted_labels == "Down"])

  GSE241735_Futibatinib_4h_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

GSE241735_Futibatinib_4h_p_value <- (sum(abs(GSE241735_Futibatinib_4h_permuted_diffs) >= abs(GSE241735_Futibatinib_4h_observed_diff)) + 1) / (n_permutations + 1)

cat("Observed difference in GSE241735_Futibatinib_4h means MFE_UP - MFE_DOWN:", GSE241735_Futibatinib_4h_observed_diff, "\n")
cat("GSE241735_Futibatinib_4h P-value from permutation test:", GSE241735_Futibatinib_4h_p_value, "\n")

