GSE241735_Futibatinib_4h_Futibatinib_4h_total_counts <- dplyr::filter(GSE241735_Futibatinib_4h_norm_TX_aggregated_data_avg_counts, condition == "Futibatinib_4h") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE241735_Futibatinib_4h_Futibatinib_4h_low_MFE_TX_counts <- dplyr::filter(GSE241735_Futibatinib_4h_norm_TX_aggregated_data_avg_counts, condition == "Futibatinib_4h") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE241735_Futibatinib_4h_low_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_low_MFE_TX = sum(avg_counts))

GSE241735_Futibatinib_4h_Futibatinib_4h_low_MFE_TX_counts_fraction <- GSE241735_Futibatinib_4h_Futibatinib_4h_low_MFE_TX_counts$total_counts_low_MFE_TX / GSE241735_Futibatinib_4h_Futibatinib_4h_total_counts$total_counts
print(GSE241735_Futibatinib_4h_Futibatinib_4h_low_MFE_TX_counts_fraction)

GSE241735_Futibatinib_4h_p_control_low <- GSE241735_Futibatinib_4h_control_low_MFE_TX_counts_fraction
GSE241735_Futibatinib_4h_p_Futibatinib_4h_low <- GSE241735_Futibatinib_4h_Futibatinib_4h_low_MFE_TX_counts_fraction

GSE241735_Futibatinib_4h_pooled_prop_low <- (GSE241735_Futibatinib_4h_control_low_MFE_TX_counts$total_counts_low_MFE_TX + GSE241735_Futibatinib_4h_Futibatinib_4h_low_MFE_TX_counts$total_counts_low_MFE_TX) /
  (GSE241735_Futibatinib_4h_control_total_counts$total_counts + GSE241735_Futibatinib_4h_Futibatinib_4h_total_counts$total_counts)

GSE241735_Futibatinib_4h_se_low <- sqrt(GSE241735_Futibatinib_4h_pooled_prop_low * (1 - GSE241735_Futibatinib_4h_pooled_prop_low) *
                 (1 / GSE241735_Futibatinib_4h_control_total_counts$total_counts + 1 / GSE241735_Futibatinib_4h_Futibatinib_4h_total_counts$total_counts))

GSE241735_Futibatinib_4h_z_stat_low <- (GSE241735_Futibatinib_4h_p_control_low - GSE241735_Futibatinib_4h_p_Futibatinib_4h_low) / GSE241735_Futibatinib_4h_se_low

GSE241735_Futibatinib_4h_z_test_counts_25_p_value <- 2 * pnorm(-abs(GSE241735_Futibatinib_4h_z_stat_low))

cat("Two-proportion Z-test p-value for low MFE TX counts in Control vs Futibatinib_4h:", GSE241735_Futibatinib_4h_z_test_counts_25_p_value, "\n")
cat("Z-statistic for low MFE TX counts in Control vs Futibatinib_4h:", GSE241735_Futibatinib_4h_z_stat_low, "\n")

