                  (1 / GSE241735_Futibatinib_12h_total_UP + 1 / GSE241735_Futibatinib_12h_total_DOWN))

GSE241735_Futibatinib_12h_z_stat_high <- (GSE241735_Futibatinib_12h_p_UP_high - GSE241735_Futibatinib_12h_p_DOWN_high) / GSE241735_Futibatinib_12h_se_high

GSE241735_Futibatinib_12h_z_test_MFE_p_value <- 2 * pnorm(-abs(GSE241735_Futibatinib_12h_z_stat_high))

