GSE241735_Futibatinib_24h_count_high_MFE_DOWN <- nrow(GSE241735_Futibatinib_24h_high_MFE_TX_in_DOWN)

GSE241735_Futibatinib_24h_p_UP_high <- GSE241735_Futibatinib_24h_count_high_MFE_UP / GSE241735_Futibatinib_24h_total_UP
GSE241735_Futibatinib_24h_p_DOWN_high <- GSE241735_Futibatinib_24h_count_high_MFE_DOWN / GSE241735_Futibatinib_24h_total_DOWN

GSE241735_Futibatinib_24h_pooled_prop_high <- (GSE241735_Futibatinib_24h_count_high_MFE_UP + GSE241735_Futibatinib_24h_count_high_MFE_DOWN) /
  (GSE241735_Futibatinib_24h_total_UP + GSE241735_Futibatinib_24h_total_DOWN)

GSE241735_Futibatinib_24h_se_high <- sqrt(GSE241735_Futibatinib_24h_pooled_prop_high * (1 - GSE241735_Futibatinib_24h_pooled_prop_high) *
                  (1 / GSE241735_Futibatinib_24h_total_UP + 1 / GSE241735_Futibatinib_24h_total_DOWN))

