GSE148096_TPM_MFE_annotation <-
  Table_ANNOTATED %>%
  dplyr::select(
    ensembl_transcript_id,
    Normalized_MFE
  ) %>%
  dplyr::mutate(
    ensembl_transcript_id =
      as.character(ensembl_transcript_id)
  ) %>%
  dplyr::distinct(
    ensembl_transcript_id,
    .keep_all = TRUE
  ) %>%
  dplyr::filter(
    is.finite(Normalized_MFE)
  )

GSE148096_Erlotinib_TPM_MFE <-
  GSE148096_TranscriptLevel_TPM %>%
  dplyr::select(
    GREIN_transcript_id,
    ensembl_transcript_id,
    dplyr::all_of(
      GSE148096_Erlotinib_required_samples
    )
  ) %>%
  dplyr::inner_join(
    GSE148096_TPM_MFE_annotation,
    by = "ensembl_transcript_id"
  )

GSE148096_Erlotinib_TPM_long <-
  GSE148096_Erlotinib_TPM_MFE %>%
  tidyr::pivot_longer(
    cols = dplyr::all_of(
      GSE148096_Erlotinib_required_samples
    ),
    names_to = "Sample",
    values_to = "TPM"
  ) %>%
  dplyr::mutate(
    Dataset = "GSE148096",

    Treatment = "Erlotinib",

    Condition = dplyr::case_when(
      Sample %in%
        GSE148096_Erlotinib_control_samples ~
        "Control",

      Sample %in%
        GSE148096_Erlotinib_treatment_samples ~
        "Erlotinib",

      TRUE ~ NA_character_
    ),

    TPM = as.numeric(TPM)
  ) %>%
  dplyr::filter(
    !is.na(Condition),
    is.finite(TPM),
    TPM >= 0
  ) %>%
  dplyr::group_by(
    Sample,
    Condition
  ) %>%
  dplyr::mutate(
    retained_TPM_MFE =
      sum(TPM),

    relative_transcript_abundance_MFE =
      TPM / retained_TPM_MFE,

    TPM_weighted_DGfold_contribution =
      relative_transcript_abundance_MFE *
      Normalized_MFE
  ) %>%
  dplyr::ungroup() %>%
  dplyr::mutate(
    Condition = factor(
      Condition,
      levels = c(
        "Control",
        "Erlotinib"
      )
    )
  )

GSE148096_Erlotinib_TPM_weight_validation <-
  GSE148096_Erlotinib_TPM_long %>%
  dplyr::group_by(
    Dataset,
    Treatment,
    Sample,
    Condition
  ) %>%
  dplyr::summarise(
    annotated_transcripts =
      dplyr::n_distinct(
        ensembl_transcript_id
      ),

    expressed_annotated_transcripts =
      dplyr::n_distinct(
        ensembl_transcript_id[TPM > 0]
      ),

    retained_TPM_MFE =
      dplyr::first(retained_TPM_MFE),

    sum_MFE_weights =
      sum(
        relative_transcript_abundance_MFE
      ),

    TPM_weighted_Normalized_MFE =
      sum(
        TPM_weighted_DGfold_contribution
      ),

    .groups = "drop"
  )

