GSE148096_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE148096_UP, ensembl_transcript_id_version %in% GSE148096_high_MFE_TX$ensembl_transcript_id_version)
GSE148096_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE148096_DOWN, ensembl_transcript_id_version %in% GSE148096_high_MFE_TX$ensembl_transcript_id_version)

GSE148096_total_UP <- nrow(MFE_res_GSE148096_UP)
GSE148096_total_DOWN <- nrow(MFE_res_GSE148096_DOWN)

GSE148096_count_high_MFE_UP <- nrow(GSE148096_high_MFE_TX_in_UP)
GSE148096_count_high_MFE_DOWN <- nrow(GSE148096_high_MFE_TX_in_DOWN)

GSE148096_high_MFE_in_UP_fraction <- GSE148096_count_high_MFE_UP / GSE148096_total_UP
GSE148096_high_MFE_in_DOWN_fraction <- GSE148096_count_high_MFE_DOWN / GSE148096_total_DOWN

cat("Fraction of GSE148096 high MFE TX in UP-regulated genes:", GSE148096_high_MFE_in_UP_fraction, "\n")
cat("Fraction of GSE148096 high MFE TX in DOWN-regulated genes:", GSE148096_high_MFE_in_DOWN_fraction, "\n")

p_up <- GSE148096_high_MFE_in_UP_fraction
p_down <- GSE148096_high_MFE_in_DOWN_fraction

n_up <- GSE148096_total_UP
n_down <- GSE148096_total_DOWN

pooled_prop <- (GSE148096_count_high_MFE_UP + GSE148096_count_high_MFE_DOWN) / (n_up + n_down)

se <- sqrt(pooled_prop * (1 - pooled_prop) * (1 / n_up + 1 / n_down))

z_stat <- (p_up - p_down) / se

GSE148096_z_test_MFE_p_value <- 2 * pnorm(-abs(z_stat))

cat("Two-proportion Z-test p-value for high MFE TX between UP-regulated and DOWN-regulated genes:", GSE148096_z_test_MFE_p_value, "\n")
cat("Z-statistic for high MFE TX between UP-regulated and DOWN-regulated genes:", z_stat, "\n")

cat("Mean of GSE148096 high MFE TX in UP-regulated genes:", mean(GSE148096_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of GSE148096 high MFE TX in DOWN-regulated genes:", mean(GSE148096_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")

cat("Mode of GSE148096 high MFE TX in UP-regulated genes:", calculate_mode(GSE148096_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of GSE148096 high MFE TX in DOWN-regulated genes:", calculate_mode(GSE148096_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")

