    cols = dplyr::all_of(
      GSE178755_Erlotinib_required_samples
    ),
    names_to = "Sample",
    values_to = "TPM"
  ) %>%
  dplyr::mutate(
    Dataset = "GSE178755",

    Treatment = "Erlotinib",

    Condition = dplyr::case_when(
      Sample %in%
        GSE178755_Erlotinib_control_samples ~
        "Control",

      Sample %in%
        GSE178755_Erlotinib_treatment_samples ~
        "Erlotinib",

      TRUE ~ NA_character_
    ),

    TPM = as.numeric(TPM)
  ) %>%
  dplyr::filter(
    !is.na(Condition),
    is.finite(TPM),
    TPM >= 0
  ) %>%
  dplyr::group_by(
    Sample,
    Condition
  ) %>%
  dplyr::mutate(
    retained_TPM_MFE =
      sum(TPM),

    relative_transcript_abundance_MFE =
      TPM / retained_TPM_MFE,

    TPM_weighted_DGfold_contribution =
      relative_transcript_abundance_MFE *
      Normalized_MFE
  ) %>%
  dplyr::ungroup() %>%
  dplyr::mutate(
    Condition = factor(
      Condition,
      levels = c(
        "Control",
        "Erlotinib"
      )
    )
  )

