GSE178755_low_MFE_TX_total <- dplyr::filter(GSE178755_norm_TX_counts_MFE_df, Normalized_MFE < GSE178755_MFE_all_TX_25_percentile)

GSE178755_control_total_counts <- dplyr::filter(GSE178755_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE178755_control_low_MFE_TX_counts <- dplyr::filter(GSE178755_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE178755_low_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_low_MFE_TX = sum(avg_counts))

GSE178755_control_low_MFE_TX_counts_fraction <- GSE178755_control_low_MFE_TX_counts$total_counts_low_MFE_TX / GSE178755_control_total_counts$total_counts
print(GSE178755_control_low_MFE_TX_counts_fraction)

GSE178755_Erlotinib_total_counts <- dplyr::filter(GSE178755_norm_TX_aggregated_data_avg_counts, condition == "Erlotinib") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE178755_Erlotinib_low_MFE_TX_counts <- dplyr::filter(GSE178755_norm_TX_aggregated_data_avg_counts, condition == "Erlotinib") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE178755_low_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_low_MFE_TX = sum(avg_counts))

GSE178755_Erlotinib_low_MFE_TX_counts_fraction <- GSE178755_Erlotinib_low_MFE_TX_counts$total_counts_low_MFE_TX / GSE178755_Erlotinib_total_counts$total_counts
print(GSE178755_Erlotinib_low_MFE_TX_counts_fraction)

p_control_low <- GSE178755_control_low_MFE_TX_counts_fraction
p_Erlotinib_low <- GSE178755_Erlotinib_low_MFE_TX_counts_fraction

pooled_prop_low <- (GSE178755_control_low_MFE_TX_counts$total_counts_low_MFE_TX + GSE178755_Erlotinib_low_MFE_TX_counts$total_counts_low_MFE_TX) /
  (GSE178755_control_total_counts$total_counts + GSE178755_Erlotinib_total_counts$total_counts)

se_low <- sqrt(pooled_prop_low * (1 - pooled_prop_low) *
                 (1 / GSE178755_control_total_counts$total_counts + 1 / GSE178755_Erlotinib_total_counts$total_counts))

z_stat_low <- (p_control_low - p_Erlotinib_low) / se_low

GSE178755_z_test_counts_25_p_value <- 2 * pnorm(-abs(z_stat_low))

cat("Two-proportion Z-test p-value for low MFE TX counts in Control vs Erlotinib:", GSE178755_z_test_counts_25_p_value, "\n")
cat("Z-statistic for low MFE TX counts in Control vs Erlotinib:", z_stat_low, "\n")

