  Table_ANNOTATED %>%
  dplyr::select(
    ensembl_transcript_id,
    Normalized_MFE
  ) %>%
  dplyr::mutate(
    ensembl_transcript_id =
      as.character(ensembl_transcript_id)
  ) %>%
  dplyr::distinct(
    ensembl_transcript_id,
    .keep_all = TRUE
  )

if (
  !is.numeric(
    GSE103021_TPM_thermodynamic_annotation$Normalized_MFE
  )
) {
  stop("Normalized_MFE is not stored as a numeric variable.")
}

GSE103021_ARS_1620_LU65_TPM_thermodynamic <-
  GSE103021_TranscriptLevel_TPM %>%
  dplyr::select(
    GREIN_transcript_id,
    ensembl_transcript_id,
    dplyr::all_of(
      GSE103021_ARS_1620_LU65_required_samples
    )
  ) %>%
  dplyr::inner_join(
    GSE103021_TPM_thermodynamic_annotation,
    by = "ensembl_transcript_id"
  )

GSE103021_TPM_joined_duplicate_IDs <- sum(
  duplicated(
    GSE103021_ARS_1620_LU65_TPM_thermodynamic$
      ensembl_transcript_id
  )
)

if (GSE103021_TPM_joined_duplicate_IDs > 0) {
  stop(
    "Duplicated transcript identifiers were generated by the annotation join."
  )
}

cat("\nGSE103021 transcript annotation summary:\n")

cat("\nGSE103021 retained TPM abundance by sample:\n")

GSE103021_ARS_1620_LU65_TPM_long <-
  GSE103021_ARS_1620_LU65_TPM_thermodynamic %>%
  tidyr::pivot_longer(
    cols = dplyr::all_of(
      GSE103021_ARS_1620_LU65_required_samples
    ),
    names_to = "Sample",
    values_to = "TPM"
  ) %>%
  dplyr::mutate(
    Dataset = "GSE103021",

    Treatment = "ARS-1620 LU65",

    Condition = dplyr::case_when(
      Sample %in%
        GSE103021_ARS_1620_LU65_control_samples ~
        "Control",

      Sample %in%
        GSE103021_ARS_1620_LU65_treatment_samples ~
        "ARS-1620",

      TRUE ~ NA_character_
    ),

    TPM = as.numeric(TPM)
  ) %>%
  dplyr::filter(
    !is.na(Condition),
    is.finite(TPM),
    TPM >= 0
  ) %>%
  dplyr::group_by(
    Sample,
    Condition
  ) %>%
  dplyr::mutate(
    retained_TPM_MFE = sum(
      ifelse(
        is.finite(Normalized_MFE),
        TPM,
        0
      )
    ),

    relative_transcript_abundance_MFE = ifelse(
      is.finite(Normalized_MFE),
      TPM / retained_TPM_MFE,
      NA_real_
    ),

    TPM_weighted_DGfold_contribution = ifelse(
      is.finite(Normalized_MFE),
      relative_transcript_abundance_MFE *
        Normalized_MFE,
      NA_real_
    )

) %>%
  dplyr::ungroup() %>%
  dplyr::mutate(
    Condition = factor(
      Condition,
      levels = c(
        "Control",
        "ARS-1620"
      )
    )
  )

GSE103021_ARS_1620_LU65_TPM_weight_validation <-
  GSE103021_ARS_1620_LU65_TPM_long %>%
  dplyr::group_by(
    Dataset,
    Treatment,
    Sample,
    Condition
  ) %>%
  dplyr::summarise(
    annotated_transcripts =
      dplyr::n_distinct(ensembl_transcript_id),

    expressed_annotated_transcripts =
      dplyr::n_distinct(
        ensembl_transcript_id[TPM > 0]
      ),

    retained_TPM_MFE =
      dplyr::first(retained_TPM_MFE),

    sum_MFE_weights = sum(
      relative_transcript_abundance_MFE,
      na.rm = TRUE
    ),

    TPM_weighted_Normalized_MFE = sum(
      TPM_weighted_DGfold_contribution,
      na.rm = TRUE
    ),

    .groups = "drop"
  )

if (
  any(
    abs(
      GSE103021_ARS_1620_LU65_TPM_weight_validation$
      sum_MFE_weights - 1
    ) > 1e-8
  )
) {
  stop("The GSE103021 TPM-derived ΔGfold weights do not sum to one.")
}

cat("\nGSE103021 common TPM-weight validation:\n")

print(
  GSE103021_ARS_1620_LU65_TPM_weight_validation,
  row.names = FALSE,
  digits = 10
)

