Expdata_GSE103021$condition <- gsub("ARS-1620 treated 1uM-LU65", "ARS_1620_LU65", Expdata_GSE103021$condition)
Expdata_GSE103021$condition <- gsub("DMSO treated-LU65", "DMSO_LU65", Expdata_GSE103021$condition)
Expdata_GSE103021$condition <- gsub("trametinib treated 50nM-LU65", "trametinib_LU65", Expdata_GSE103021$condition)
Expdata_GSE103021$condition <- gsub("DMSO treated-A549", "DMSO_A549", Expdata_GSE103021$condition)
Expdata_GSE103021$condition <- gsub("ARS-1620 treated 1uM-A549", "ARS_1620_A549", Expdata_GSE103021$condition)
