ks_test_res_GSE103021_trametinib_LU65_all_UP_vs_DOWN <- ks.test(MFE_res_GSE103021_trametinib_LU65_DOWN$Normalized_MFE, MFE_res_GSE103021_trametinib_LU65_UP$Normalized_MFE)

quantile_075_MFE_res_GSE103021_trametinib_LU65_UP <- quantile(MFE_res_GSE103021_trametinib_LU65_UP$Normalized_MFE, probs = c(0.75))
quantile_075_MFE_res_GSE103021_trametinib_LU65_DOWN <- quantile(MFE_res_GSE103021_trametinib_LU65_DOWN$Normalized_MFE, probs = c(0.75))
ks_test_MFE_075_above <- ks.test(MFE_res_GSE103021_trametinib_LU65_UP$Normalized_MFE[MFE_res_GSE103021_trametinib_LU65_UP$Normalized_MFE >= quantile_075_MFE_res_GSE103021_trametinib_LU65_UP],
                                 MFE_res_GSE103021_trametinib_LU65_DOWN$Normalized_MFE[MFE_res_GSE103021_trametinib_LU65_DOWN$Normalized_MFE >= quantile_075_MFE_res_GSE103021_trametinib_LU65_DOWN])

quantile_025_MFE_res_GSE103021_trametinib_LU65_UP <- quantile(MFE_res_GSE103021_trametinib_LU65_UP$Normalized_MFE, probs = c(0.25))
quantile_025_MFE_res_GSE103021_trametinib_LU65_DOWN <- quantile(MFE_res_GSE103021_trametinib_LU65_DOWN$Normalized_MFE, probs = c(0.25))
ks_test_MFE_025_below <- ks.test(MFE_res_GSE103021_trametinib_LU65_UP$Normalized_MFE[MFE_res_GSE103021_trametinib_LU65_UP$Normalized_MFE <= quantile_025_MFE_res_GSE103021_trametinib_LU65_UP],
                                 MFE_res_GSE103021_trametinib_LU65_DOWN$Normalized_MFE[MFE_res_GSE103021_trametinib_LU65_DOWN$Normalized_MFE <= quantile_025_MFE_res_GSE103021_trametinib_LU65_DOWN])

upregulated <- data.frame(MFE = MFE_res_GSE103021_trametinib_LU65_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_res_GSE103021_trametinib_LU65_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

GSE103021_trametinib_LU65_observed_diff <- mean(MFE_res_GSE103021_trametinib_LU65_UP$Normalized_MFE) - mean(MFE_res_GSE103021_trametinib_LU65_DOWN$Normalized_MFE)

n_permutations <- 10000

GSE103021_trametinib_LU65_permuted_diffs <- numeric(n_permutations)

set.seed(123)
for (i in 1:n_permutations) {
  permuted_labels <- sample(combined_data$Group)

  permuted_up_mean <- mean(combined_data$MFE[permuted_labels == "Up"])
  permuted_down_mean <- mean(combined_data$MFE[permuted_labels == "Down"])

  GSE103021_trametinib_LU65_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

GSE103021_trametinib_LU65_p_value <- (sum(abs(GSE103021_trametinib_LU65_permuted_diffs) >= abs(GSE103021_trametinib_LU65_observed_diff)) + 1) / (n_permutations + 1)

cat("Observed difference in GSE103021_trametinib_LU65 means MFE_UP - MFE_DOWN:", GSE103021_trametinib_LU65_observed_diff, "\n")
cat("GSE103021_trametinib_LU65 P-value from permutation test:", GSE103021_trametinib_LU65_p_value, "\n")

