GSE103021_H358_ARS_1620_total_UP <- nrow(MFE_res_GSE103021_H358_ARS_1620_UP)
GSE103021_H358_ARS_1620_total_DOWN <- nrow(MFE_res_GSE103021_H358_ARS_1620_DOWN)
GSE103021_H358_ARS_1620_count_high_MFE_UP <- nrow(GSE103021_H358_ARS_1620_high_MFE_TX_in_UP)
GSE103021_H358_ARS_1620_count_high_MFE_DOWN <- nrow(GSE103021_H358_ARS_1620_high_MFE_TX_in_DOWN)

GSE103021_H358_ARS_1620_high_MFE_in_UP_fraction <- GSE103021_H358_ARS_1620_count_high_MFE_UP / GSE103021_H358_ARS_1620_total_UP
GSE103021_H358_ARS_1620_high_MFE_in_DOWN_fraction <- GSE103021_H358_ARS_1620_count_high_MFE_DOWN / GSE103021_H358_ARS_1620_total_DOWN

pooled_proportion <- (GSE103021_H358_ARS_1620_count_high_MFE_UP + GSE103021_H358_ARS_1620_count_high_MFE_DOWN) /
  (GSE103021_H358_ARS_1620_total_UP + GSE103021_H358_ARS_1620_total_DOWN)

SE <- sqrt(pooled_proportion * (1 - pooled_proportion) * (1 / GSE103021_H358_ARS_1620_total_UP + 1 / GSE103021_H358_ARS_1620_total_DOWN))

z_score <- (GSE103021_H358_ARS_1620_high_MFE_in_UP_fraction - GSE103021_H358_ARS_1620_high_MFE_in_DOWN_fraction) / SE

