GSE103021_trametinib_LU65_long_data <- GSE103021_trametinib_LU65_norm_TX_counts_MFE_df %>%
  pivot_longer(
    cols = starts_with("GSM"),
    names_to = "replicate",
    values_to = "counts"
  )

GSE103021_trametinib_LU65_long_data <- GSE103021_trametinib_LU65_long_data %>%
  mutate(condition = ifelse(replicate %in% c("GSM2752547", "GSM2752548", "GSM2752549"), "Control", "trametinib_LU65"))

GSE103021_trametinib_LU65_norm_TX_aggregated_data_avg_counts <- GSE103021_trametinib_LU65_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE) %>%
  summarise(
    avg_counts = mean(counts),
    .groups = 'drop'
  )

GSE103021_trametinib_LU65_MFE_all_TX_75_percentile <- quantile(GSE103021_trametinib_LU65_norm_TX_aggregated_data_avg_counts$Normalized_MFE, 0.75)

GSE103021_trametinib_LU65_high_MFE_TX_total <- dplyr::filter(GSE103021_trametinib_LU65_norm_TX_counts_MFE_df, Normalized_MFE > GSE103021_trametinib_LU65_MFE_all_TX_75_percentile)

GSE103021_trametinib_LU65_control_total_counts <- dplyr::filter(GSE103021_trametinib_LU65_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE103021_trametinib_LU65_control_high_MFE_TX_counts <- dplyr::filter(GSE103021_trametinib_LU65_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE103021_trametinib_LU65_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE103021_trametinib_LU65_control_high_MFE_TX_counts_fraction <- GSE103021_trametinib_LU65_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE103021_trametinib_LU65_control_total_counts$total_counts
print(GSE103021_trametinib_LU65_control_high_MFE_TX_counts_fraction)

GSE103021_trametinib_LU65_trametinib_LU65_total_counts <- dplyr::filter(GSE103021_trametinib_LU65_norm_TX_aggregated_data_avg_counts, condition == "trametinib_LU65") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE103021_trametinib_LU65_trametinib_LU65_high_MFE_TX_counts <- dplyr::filter(GSE103021_trametinib_LU65_norm_TX_aggregated_data_avg_counts, condition == "trametinib_LU65") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE103021_trametinib_LU65_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE103021_trametinib_LU65_trametinib_LU65_high_MFE_TX_counts_fraction <- GSE103021_trametinib_LU65_trametinib_LU65_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE103021_trametinib_LU65_trametinib_LU65_total_counts$total_counts
print(GSE103021_trametinib_LU65_trametinib_LU65_high_MFE_TX_counts_fraction)

prop_control_high_MFE <- GSE103021_trametinib_LU65_control_high_MFE_TX_counts_fraction
prop_trametinib_LU65_high_MFE <- GSE103021_trametinib_LU65_trametinib_LU65_high_MFE_TX_counts_fraction

total_control_counts <- GSE103021_trametinib_LU65_control_total_counts$total_counts
total_trametinib_LU65_counts <- GSE103021_trametinib_LU65_trametinib_LU65_total_counts$total_counts

pooled_prop <- (GSE103021_trametinib_LU65_control_high_MFE_TX_counts$total_counts_high_MFE_TX +
                  GSE103021_trametinib_LU65_trametinib_LU65_high_MFE_TX_counts$total_counts_high_MFE_TX) /
  (total_control_counts + total_trametinib_LU65_counts)

se <- sqrt(pooled_prop * (1 - pooled_prop) * (1 / total_control_counts + 1 / total_trametinib_LU65_counts))

z_score <- (prop_control_high_MFE - prop_trametinib_LU65_high_MFE) / se

GSE103021_trametinib_LU65_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(z_score)))

cat("Z-score for high MFE transcripts between Control and trametinib_LU65:", z_score, "\n")
cat("P-value for the two-proportion z-test:", GSE103021_trametinib_LU65_z_test_counts_75_p_value, "\n")

cat("Control high MFE TX as fraction of total counts:", prop_control_high_MFE, "\n")
cat("trametinib_LU65 high MFE TX as fraction of total counts:", prop_trametinib_LU65_high_MFE, "\n")
cat("Net change in counts of high MFE TX drug vs control:", prop_trametinib_LU65_high_MFE - prop_control_high_MFE, "\n")

