GSE118548_common_mapping_transcripts <- intersect(
  GSE118548_TPM_for_mapping$
    GREIN_transcript_id,
  GSE118548_raw_for_mapping$
    GREIN_transcript_id
)

cat(
  "\nTranscripts shared by GSE118548 TPM and raw matrices:",
  length(
    GSE118548_common_mapping_transcripts
  ),
  "\n"
)

if (
  length(
