    "Too few transcripts were shared by the GSE118548 TPM and raw-count matrices."
  )
}

GSE118548_TPM_mapping_matrix <- data.matrix(
  GSE118548_TPM_for_mapping[
    match(
      GSE118548_common_mapping_transcripts,
      GSE118548_TPM_for_mapping$
        GREIN_transcript_id
    ),
    names(
      GSE118548_TPM_expected_column_map
    ),
    drop = FALSE
  ]
)

GSE118548_raw_mapping_matrix <- data.matrix(
  GSE118548_raw_for_mapping[
    match(
      GSE118548_common_mapping_transcripts,
      GSE118548_raw_for_mapping$
        GREIN_transcript_id
    ),
    unname(
      GSE118548_TPM_expected_column_map
    ),
    drop = FALSE
  ]
)

if (
  anyNA(
    GSE118548_TPM_mapping_matrix
  ) ||
  anyNA(
    GSE118548_raw_mapping_matrix
  )
) {
  stop(
    "Missing values were detected during GSE118548 TPM-column mapping."
  )
}

GSE118548_TPM_expressed <-
  GSE118548_TPM_mapping_matrix > 0

GSE118548_raw_expressed <-
  GSE118548_raw_mapping_matrix > 0

GSE118548_TPM_mapping_validation <- data.frame(
  TPM_column =
    colnames(
      GSE118548_TPM_expressed
    ),

  Expected_GSM_sample =
    unname(
      GSE118548_TPM_expected_column_map[
        colnames(
          GSE118548_TPM_expressed
        )
      ]
    ),

  Number_exact_matches =
    NA_integer_,

  Matched_GSM_sample =
    NA_character_,

  row.names = NULL,
  stringsAsFactors = FALSE
)

for (
  TPM_column_index in
  seq_len(
    ncol(
      GSE118548_TPM_expressed
    )
  )
) {

  current_exact_matches <- character(0)

  for (
    raw_column_index in
    seq_len(
      ncol(
        GSE118548_raw_expressed
      )
    )
  ) {

    current_patterns_identical <- identical(
      unname(
        GSE118548_TPM_expressed[
          ,
          TPM_column_index
        ]
      ),
      unname(
        GSE118548_raw_expressed[
          ,
          raw_column_index
        ]
      )
    )

    if (current_patterns_identical) {
      current_exact_matches <- c(
        current_exact_matches,
        colnames(
          GSE118548_raw_expressed
        )[raw_column_index]
      )
    }
  }

  GSE118548_TPM_mapping_validation$
    Number_exact_matches[
      TPM_column_index
    ] <-
    length(
      current_exact_matches
    )

  GSE118548_TPM_mapping_validation$
    Matched_GSM_sample[
      TPM_column_index
    ] <-
    if (
      length(
        current_exact_matches
      ) == 0
    ) {
      NA_character_
    } else {
      paste(
        current_exact_matches,
        collapse = ", "
      )
    }
}

GSE118548_TPM_mapping_validation <-
  GSE118548_TPM_mapping_validation %>%
  dplyr::mutate(
    Mapping_correct =
      Number_exact_matches == 1 &
      Matched_GSM_sample ==
      Expected_GSM_sample
  )

cat(
  "\nGSE118548 TPM-column mapping validation:\n"
)

print(
  GSE118548_TPM_mapping_validation,
  row.names = FALSE
)

if (
  any(
    !GSE118548_TPM_mapping_validation$
    Mapping_correct
  )
) {
  stop(
    "The expected GSE118548 TPM-to-GSM mapping was not verified."
  )
}

