GSE118548_Trametinib_TPM_MFE_annotation <-
  Table_ANNOTATED %>%
  dplyr::select(
    ensembl_transcript_id,
    Normalized_MFE
  ) %>%
  dplyr::mutate(
    ensembl_transcript_id =
      as.character(
        ensembl_transcript_id
      )
  ) %>%
  dplyr::distinct(
    ensembl_transcript_id,
    .keep_all = TRUE
  ) %>%
  dplyr::filter(
    is.finite(
      Normalized_MFE
    )
  )

GSE118548_Trametinib_TPM_MFE <-
  GSE118548_TranscriptLevel_TPM %>%
  dplyr::select(
    GREIN_transcript_id,
    ensembl_transcript_id,
    dplyr::all_of(
      GSE118548_Trametinib_required_samples
    )
  ) %>%
  dplyr::inner_join(
    GSE118548_Trametinib_TPM_MFE_annotation,
    by = "ensembl_transcript_id"
  )

if (
  nrow(
    GSE118548_Trametinib_TPM_MFE
  ) < 100000
) {
  stop(
    "Too few GSE118548 transcripts were matched to finite Normalized_MFE annotations."
  )
}

GSE118548_Trametinib_TPM_long <-
  GSE118548_Trametinib_TPM_MFE %>%
  tidyr::pivot_longer(
    cols = dplyr::all_of(
      GSE118548_Trametinib_required_samples
    ),
    names_to = "Sample",
    values_to = "TPM"
  ) %>%
  dplyr::mutate(
    Dataset = "GSE118548",

    Treatment = "Trametinib",

    Condition = dplyr::case_when(
      Sample %in%
        GSE118548_Trametinib_control_samples ~
        "Control",

      Sample %in%
        GSE118548_Trametinib_treatment_samples ~
        "Trametinib",

      TRUE ~
        NA_character_
    ),

    TPM =
      as.numeric(TPM)
  ) %>%
  dplyr::filter(
    !is.na(Condition),
    is.finite(TPM),
    TPM >= 0
  ) %>%
  dplyr::group_by(
    Sample,
    Condition
  ) %>%
  dplyr::mutate(
    retained_TPM_MFE =
      sum(TPM),

    relative_transcript_abundance_MFE =
      TPM /
      retained_TPM_MFE,

    TPM_weighted_DGfold_contribution =
      relative_transcript_abundance_MFE *
      Normalized_MFE
  ) %>%
  dplyr::ungroup() %>%
  dplyr::mutate(
    Condition = factor(
      Condition,
      levels = c(
        "Control",
        "Trametinib"
      )
    )
  )

GSE118548_Trametinib_TPM_weight_validation <-
  GSE118548_Trametinib_TPM_long %>%
  dplyr::group_by(
    Dataset,
    Treatment,
    Sample,
    Condition
  ) %>%
  dplyr::summarise(
    annotated_transcripts =
      dplyr::n_distinct(
        ensembl_transcript_id
      ),

    expressed_annotated_transcripts =
      dplyr::n_distinct(
        ensembl_transcript_id[
          TPM > 0
        ]
      ),

    retained_TPM_MFE =
      dplyr::first(
        retained_TPM_MFE
      ),

    sum_MFE_weights =
      sum(
        relative_transcript_abundance_MFE
      ),

    TPM_weighted_Normalized_MFE =
      sum(
        TPM_weighted_DGfold_contribution
      ),

    .groups = "drop"
  )

if (
  nrow(
    GSE118548_Trametinib_TPM_weight_validation
  ) != 6
) {
  stop(
    "The GSE118548 TPM-weighted table does not contain six samples."
  )
}

if (
  any(
    GSE118548_Trametinib_TPM_weight_validation$
    retained_TPM_MFE <= 0
  )
) {
  stop(
    "At least one GSE118548 sample has no retained annotated TPM."
  )
}

if (
  any(
    abs(
      GSE118548_Trametinib_TPM_weight_validation$
      sum_MFE_weights - 1
    ) > 1e-10
  )
) {
  stop(
    "At least one GSE118548 sample's TPM weights do not sum to one."
  )
}

if (
  any(
    !is.finite(
      GSE118548_Trametinib_TPM_weight_validation$
      TPM_weighted_Normalized_MFE
    )
  )
) {
  stop(
    "Non-finite TPM-weighted ΔGfold values were detected."
  )
}

cat(
  "\nGSE118548 trametinib TPM-weight validation:\n"
)

print(
  as.data.frame(
    GSE118548_Trametinib_TPM_weight_validation
  ),
  row.names = FALSE,
  digits = 12
)

Data_GSE118548 <- readRDS(file.path(input_dir, "Data_GSE118548.rds"))

Expdata_GSE118548 <- Data_GSE118548[["GSE118548_series_matrix.txt.gz"]]@phenoData@data

colnames(Expdata_GSE118548)[colnames(Expdata_GSE118548) == "treatment:ch1"] <- "condition"
Expdata_GSE118548$condition <- gsub("Trametinib 30nM", "Trametinib", Expdata_GSE118548$condition)
Expdata_GSE118548$condition <- gsub("JQ1 1µM", "JQ1", Expdata_GSE118548$condition)

all(rownames(Expdata_GSE118548) %in% colnames(Counts_GSE118548_GREIN))
all(colnames(Counts_GSE118548_GREIN) %in% rownames(Expdata_GSE118548))

dds_GSE118548 <- DESeqDataSetFromMatrix(countData = Counts_GSE118548_GREIN,
                                        colData = Expdata_GSE118548,
                                        design = ~ condition)
dds_GSE118548

ntd <- normTransform(dds_GSE118548)
select <- order(rowMeans(counts(dds_GSE118548,normalized=FALSE)),
                decreasing=TRUE)[1:25]
df <- as.data.frame(colData(dds_GSE118548)[,c("condition","type")])
pheatmap(assay(ntd)[select,], cluster_rows=FALSE, show_rownames=FALSE,
         cluster_cols=FALSE, annotation_col=df)

vsd <- vst(dds_GSE118548, blind=FALSE)
head(assay(vsd), 3)

sampleDists <- dist(t(assay(vsd)))

sampleDistMatrix <- as.matrix(sampleDists)
rownames(sampleDistMatrix) <- paste(vsd$condition, vsd$type, sep="-")
colnames(sampleDistMatrix) <- NULL
colors <- colorRampPalette( rev(brewer.pal(9, "Blues")) )(255)
pheatmap(sampleDistMatrix,
         clustering_distance_rows=sampleDists,
         clustering_distance_cols=sampleDists,
         col=colors)

plotPCA(vsd, intgroup="condition")

keep <- rowSums(counts(dds_GSE118548)) >= 10
dds_GSE118548 <- dds_GSE118548[keep,]
table(keep)
nrow(dds_GSE118548)

dds_GSE118548 <- DESeq(dds_GSE118548)

res_GSE118548_JQ1 <- results(dds_GSE118548, contrast=c("condition","JQ1","DMSO"))
res_GSE118548_JQ1
summary(res_GSE118548_JQ1)

plotMA(res_GSE118548_JQ1,alpha = 0.05)
abline(h=c(-2,2),col = "red")

res_GSE118548_JQ1_df <- data.frame(res_GSE118548_JQ1)
res_GSE118548_JQ1 <- tibble::rownames_to_column(res_GSE118548_JQ1_df, "ensembl_transcript_id")

MFE_res_GSE118548_JQ1 <- dplyr::inner_join(Table_ANNOTATED, res_GSE118548_JQ1, by="ensembl_transcript_id") %>%
  dplyr::filter(padj < 0.05) %>%
  dplyr::filter(log2FoldChange < 15 & log2FoldChange > -15)

Plot_GSE118548_JQ1 <- ggplot(MFE_res_GSE118548_JQ1, aes(y=Normalized_MFE, x=log2FoldChange)) +
  geom_point(size=1.5, alpha=0.3)+
  theme_classic() +
  theme(legend.position="none") +
  geom_vline(xintercept = 0, size=0.3) +
  theme(axis.title = element_text(size = 20)) +
  theme(plot.title = element_text(size = 15)) +
  labs(y="DGfold / nt (kcal/mol)",x="Log2_FC_expression",title="GSE118548_JQ1_Log2_FC_adj.P<0.05")
print(Plot_GSE118548_JQ1)

ggsave("Plot_GSE118548_JQ1.pdf", plot = Plot_GSE118548_JQ1, path = output_dir)

MFE_res_GSE118548_JQ1_UP <- dplyr::filter(MFE_res_GSE118548_JQ1, log2FoldChange > 0)
Mean_MFE_res_GSE118548_JQ1_UP <- mean(MFE_res_GSE118548_JQ1_UP$Normalized_MFE)

