GSE118548_Trametinib_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE118548_Trametinib_DOWN, ensembl_transcript_id_version %in% GSE118548_Trametinib_high_MFE_TX$ensembl_transcript_id_version)

