high_MFE_Trametinib_count <- GSE118548_Trametinib_Trametinib_high_MFE_TX_counts$total_counts_high_MFE_TX
low_MFE_Trametinib_count <- GSE118548_Trametinib_Trametinib_total_counts$total_counts - high_MFE_Trametinib_count

