Counts_GSE177054_GREIN <- read.delim(file.path(input_dir, "GSE177054_TranscriptLevel_Raw_data.csv"), sep = ",", header = T, stringsAsFactors = F)
Counts_GSE177054_GREIN <- Counts_GSE177054_GREIN %>% remove_rownames %>% column_to_rownames(var="X")
Counts_GSE177054_GREIN <- floor(Counts_GSE177054_GREIN)

Data_GSE177054 <- readRDS(file.path(input_dir, "Data_GSE177054.rds"))

Expdata_GSE177054 <- Data_GSE177054[["GSE177054_series_matrix.txt.gz"]]@phenoData@data

colnames(Expdata_GSE177054)[colnames(Expdata_GSE177054) == "treatment:ch1"] <- "condition"
Expdata_GSE177054$condition <- gsub("Ribociclib&D 4476", "Ribociclib_D4476", Expdata_GSE177054$condition)

all(rownames(Expdata_GSE177054) %in% colnames(Counts_GSE177054_GREIN))
all(colnames(Counts_GSE177054_GREIN) %in% rownames(Expdata_GSE177054))

dds_GSE177054 <- DESeqDataSetFromMatrix(countData = Counts_GSE177054_GREIN,
                                        colData = Expdata_GSE177054,
                                        design = ~ condition)
dds_GSE177054

ntd <- normTransform(dds_GSE177054)
select <- order(rowMeans(counts(dds_GSE177054,normalized=FALSE)),
                decreasing=TRUE)[1:25]
df <- as.data.frame(colData(dds_GSE177054)[,c("condition","type")])
pheatmap(assay(ntd)[select,], cluster_rows=FALSE, show_rownames=FALSE,
         cluster_cols=FALSE, annotation_col=df)

vsd <- vst(dds_GSE177054, blind=FALSE)
head(assay(vsd), 3)

sampleDists <- dist(t(assay(vsd)))

sampleDistMatrix <- as.matrix(sampleDists)
rownames(sampleDistMatrix) <- paste(vsd$condition, vsd$type, sep="-")
colnames(sampleDistMatrix) <- NULL
colors <- colorRampPalette( rev(brewer.pal(9, "Blues")) )(255)
pheatmap(sampleDistMatrix,
         clustering_distance_rows=sampleDists,
         clustering_distance_cols=sampleDists,
         col=colors)

plotPCA(vsd, intgroup="condition")

keep <- rowSums(counts(dds_GSE177054)) >= 5
dds_GSE177054 <- dds_GSE177054[keep,]
table(keep)
nrow(dds_GSE177054)

dds_GSE177054 <- DESeq(dds_GSE177054)

res_GSE177054_Ribociclib <- results(dds_GSE177054, contrast=c("condition","Ribociclib","DMSO"))
res_GSE177054_Ribociclib
summary(res_GSE177054_Ribociclib)

plotMA(res_GSE177054_Ribociclib,alpha = 0.05)
abline(h=c(-2,2),col = "red")

res_GSE177054_Ribociclib_df <- data.frame(res_GSE177054_Ribociclib)
res_GSE177054_Ribociclib <- tibble::rownames_to_column(res_GSE177054_Ribociclib_df, "ensembl_transcript_id")

MFE_res_GSE177054_Ribociclib <- dplyr::inner_join(Table_ANNOTATED, res_GSE177054_Ribociclib, by="ensembl_transcript_id") %>%
  dplyr::filter(padj < 0.05)

Plot_GSE177054_Ribociclib <- ggplot(MFE_res_GSE177054_Ribociclib, aes(y=Normalized_MFE, x=log2FoldChange)) +
  geom_point(size=1.5, alpha=0.3)+
  theme_classic() +
  theme(legend.position="none") +
  geom_vline(xintercept = 0, size=0.3) +
  theme(axis.title = element_text(size = 20)) +
  theme(plot.title = element_text(size = 15)) +
  labs(y="DGfold / nt (kcal/mol)",x="Log2_FC_expression",title="GSE177054_Ribociclib_Log2_FC_adj.P<0.05")
print(Plot_GSE177054_Ribociclib)

ggsave("Plot_GSE177054_Ribociclib.pdf", plot = Plot_GSE177054_Ribociclib, path = output_dir)

MFE_res_GSE177054_Ribociclib_UP <- dplyr::filter(MFE_res_GSE177054_Ribociclib, log2FoldChange > 0)
Mean_MFE_res_GSE177054_Ribociclib_UP <- mean(MFE_res_GSE177054_Ribociclib_UP$Normalized_MFE)

MFE_res_GSE177054_Ribociclib_DOWN <- dplyr::filter(MFE_res_GSE177054_Ribociclib, log2FoldChange < 0)
Mean_MFE_res_GSE177054_Ribociclib_DOWN <- mean(MFE_res_GSE177054_Ribociclib_DOWN$Normalized_MFE)

TTEST_MFE_res_GSE177054_Ribociclib_all_UP_vs_DOWN <- t.test(MFE_res_GSE177054_Ribociclib_DOWN$Normalized_MFE, MFE_res_GSE177054_Ribociclib_UP$Normalized_MFE, paired=FALSE)

ks_test_res_GSE177054_Ribociclib_all_UP_vs_DOWN <- ks.test(MFE_res_GSE177054_Ribociclib_DOWN$Normalized_MFE, MFE_res_GSE177054_Ribociclib_UP$Normalized_MFE)

quantile_075_MFE_res_GSE177054_Ribociclib_UP <- quantile(MFE_res_GSE177054_Ribociclib_UP$Normalized_MFE, probs = c(0.75))
quantile_075_MFE_res_GSE177054_Ribociclib_DOWN <- quantile(MFE_res_GSE177054_Ribociclib_DOWN$Normalized_MFE, probs = c(0.75))
ks_test_MFE_075_above <- ks.test(MFE_res_GSE177054_Ribociclib_UP$Normalized_MFE[MFE_res_GSE177054_Ribociclib_UP$Normalized_MFE >= quantile_075_MFE_res_GSE177054_Ribociclib_UP],
                                 MFE_res_GSE177054_Ribociclib_DOWN$Normalized_MFE[MFE_res_GSE177054_Ribociclib_DOWN$Normalized_MFE >= quantile_075_MFE_res_GSE177054_Ribociclib_DOWN])

quantile_025_MFE_res_GSE177054_Ribociclib_UP <- quantile(MFE_res_GSE177054_Ribociclib_UP$Normalized_MFE, probs = c(0.25))
quantile_025_MFE_res_GSE177054_Ribociclib_DOWN <- quantile(MFE_res_GSE177054_Ribociclib_DOWN$Normalized_MFE, probs = c(0.25))
ks_test_MFE_025_below <- ks.test(MFE_res_GSE177054_Ribociclib_UP$Normalized_MFE[MFE_res_GSE177054_Ribociclib_UP$Normalized_MFE <= quantile_025_MFE_res_GSE177054_Ribociclib_UP],
                                 MFE_res_GSE177054_Ribociclib_DOWN$Normalized_MFE[MFE_res_GSE177054_Ribociclib_DOWN$Normalized_MFE <= quantile_025_MFE_res_GSE177054_Ribociclib_DOWN])

upregulated <- data.frame(MFE = MFE_res_GSE177054_Ribociclib_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_res_GSE177054_Ribociclib_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

GSE177054_Ribociclib_observed_diff <- mean(MFE_res_GSE177054_Ribociclib_UP$Normalized_MFE) - mean(MFE_res_GSE177054_Ribociclib_DOWN$Normalized_MFE)

n_permutations <- 10000

GSE177054_Ribociclib_permuted_diffs <- numeric(n_permutations)

set.seed(123)
for (i in 1:n_permutations) {
  permuted_labels <- sample(combined_data$Group)

  permuted_up_mean <- mean(combined_data$MFE[permuted_labels == "Up"])
  permuted_down_mean <- mean(combined_data$MFE[permuted_labels == "Down"])

  GSE177054_Ribociclib_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

GSE177054_Ribociclib_p_value <- (sum(abs(GSE177054_Ribociclib_permuted_diffs) >= abs(GSE177054_Ribociclib_observed_diff)) + 1) / (n_permutations + 1)

cat("Observed difference in GSE177054_Ribociclib means MFE_UP - MFE_DOWN:", GSE177054_Ribociclib_observed_diff, "\n")
cat("GSE177054_Ribociclib P-value from permutation test:", GSE177054_Ribociclib_p_value, "\n")

