                                 MFE_res_GSE177054_Ribociclib_D4476_DOWN$Normalized_MFE[MFE_res_GSE177054_Ribociclib_D4476_DOWN$Normalized_MFE >= quantile_075_MFE_res_GSE177054_Ribociclib_D4476_DOWN])

quantile_025_MFE_res_GSE177054_Ribociclib_D4476_UP <- quantile(MFE_res_GSE177054_Ribociclib_D4476_UP$Normalized_MFE, probs = c(0.25))
quantile_025_MFE_res_GSE177054_Ribociclib_D4476_DOWN <- quantile(MFE_res_GSE177054_Ribociclib_D4476_DOWN$Normalized_MFE, probs = c(0.25))
ks_test_MFE_025_below <- ks.test(MFE_res_GSE177054_Ribociclib_D4476_UP$Normalized_MFE[MFE_res_GSE177054_Ribociclib_D4476_UP$Normalized_MFE <= quantile_025_MFE_res_GSE177054_Ribociclib_D4476_UP],
                                 MFE_res_GSE177054_Ribociclib_D4476_DOWN$Normalized_MFE[MFE_res_GSE177054_Ribociclib_D4476_DOWN$Normalized_MFE <= quantile_025_MFE_res_GSE177054_Ribociclib_D4476_DOWN])

upregulated <- data.frame(MFE = MFE_res_GSE177054_Ribociclib_D4476_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_res_GSE177054_Ribociclib_D4476_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

GSE177054_Ribociclib_D4476_observed_diff <- mean(MFE_res_GSE177054_Ribociclib_D4476_UP$Normalized_MFE) - mean(MFE_res_GSE177054_Ribociclib_D4476_DOWN$Normalized_MFE)

n_permutations <- 10000

GSE177054_Ribociclib_D4476_permuted_diffs <- numeric(n_permutations)

set.seed(123)
for (i in 1:n_permutations) {
  permuted_labels <- sample(combined_data$Group)

  permuted_up_mean <- mean(combined_data$MFE[permuted_labels == "Up"])
  permuted_down_mean <- mean(combined_data$MFE[permuted_labels == "Down"])

  GSE177054_Ribociclib_D4476_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

GSE177054_Ribociclib_D4476_p_value <- (sum(abs(GSE177054_Ribociclib_D4476_permuted_diffs) >= abs(GSE177054_Ribociclib_D4476_observed_diff)) + 1) / (n_permutations + 1)

cat("Observed difference in GSE177054_Ribociclib_D4476 means MFE_UP - MFE_DOWN:", GSE177054_Ribociclib_D4476_observed_diff, "\n")
cat("GSE177054_Ribociclib_D4476 P-value from permutation test:", GSE177054_Ribociclib_D4476_p_value, "\n")

