GSE177054_Ribociclib_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE177054_Ribociclib_DOWN, ensembl_transcript_id_version %in% GSE177054_Ribociclib_high_MFE_TX$ensembl_transcript_id_version)

p_UP <- nrow(GSE177054_Ribociclib_high_MFE_TX_in_UP) / nrow(MFE_res_GSE177054_Ribociclib_UP)
p_DOWN <- nrow(GSE177054_Ribociclib_high_MFE_TX_in_DOWN) / nrow(MFE_res_GSE177054_Ribociclib_DOWN)

n_UP <- nrow(MFE_res_GSE177054_Ribociclib_UP)
n_DOWN <- nrow(MFE_res_GSE177054_Ribociclib_DOWN)

SE <- sqrt((p_UP * (1 - p_UP)) / n_UP + (p_DOWN * (1 - p_DOWN)) / n_DOWN)

Z <- (p_UP - p_DOWN) / SE

GSE177054_Ribociclib_z_test_MFE_p_value <- 2 * (1 - pnorm(abs(Z)))

