GSE177054_Ribociclib_D4476_control_high_MFE_TX_counts_fraction <- GSE177054_Ribociclib_D4476_control_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE177054_Ribociclib_D4476_control_total_counts$total_counts
cat("GSE177054_Ribociclib_D4476 control high MFE TX as fraction of total counts:", GSE177054_Ribociclib_D4476_control_high_MFE_TX_counts_fraction, "\n")

GSE177054_Ribociclib_D4476_Ribociclib_D4476_total_counts <- dplyr::filter(GSE177054_Ribociclib_D4476_norm_TX_aggregated_data_avg_counts, condition == "Ribociclib_D4476") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE177054_Ribociclib_D4476_Ribociclib_D4476_high_MFE_TX_counts <- dplyr::filter(GSE177054_Ribociclib_D4476_norm_TX_aggregated_data_avg_counts, condition == "Ribociclib_D4476") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE177054_Ribociclib_D4476_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE177054_Ribociclib_D4476_Ribociclib_D4476_high_MFE_TX_counts_fraction <- GSE177054_Ribociclib_D4476_Ribociclib_D4476_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE177054_Ribociclib_D4476_Ribociclib_D4476_total_counts$total_counts
cat("GSE177054_Ribociclib_D4476 Ribociclib_D4476 high MFE TX as fraction of total counts:", GSE177054_Ribociclib_D4476_Ribociclib_D4476_high_MFE_TX_counts_fraction, "\n")

p_control <- GSE177054_Ribociclib_D4476_control_high_MFE_TX_counts_fraction
p_ribociclib <- GSE177054_Ribociclib_D4476_Ribociclib_D4476_high_MFE_TX_counts_fraction

n_control <- GSE177054_Ribociclib_D4476_control_total_counts$total_counts
n_ribociclib <- GSE177054_Ribociclib_D4476_Ribociclib_D4476_total_counts$total_counts

p_pool <- (GSE177054_Ribociclib_D4476_control_high_MFE_TX_counts$total_counts_high_MFE_TX + GSE177054_Ribociclib_D4476_Ribociclib_D4476_high_MFE_TX_counts$total_counts_high_MFE_TX) / (n_control + n_ribociclib)

SE <- sqrt(p_pool * (1 - p_pool) * (1 / n_control + 1 / n_ribociclib))

Z <- (p_control - p_ribociclib) / SE

GGSE177054_Ribociclib_D4476_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(Z)))

cat("Z-test statistic:", Z, "\n")
cat("P-value from Z-test:", GGSE177054_Ribociclib_D4476_z_test_counts_75_p_value, "\n")

net_change <- p_ribociclib - p_control
cat("Net change in high MFE TX counts (drug vs control):", net_change, "\n")

