GSE99060_MCF7_abemaciclib_total_DOWN <- nrow(MFE_res_GSE99060_MCF7_abemaciclib_DOWN)
GSE99060_MCF7_abemaciclib_count_high_MFE_UP <- nrow(GSE99060_MCF7_abemaciclib_high_MFE_TX_in_UP)
GSE99060_MCF7_abemaciclib_count_high_MFE_DOWN <- nrow(GSE99060_MCF7_abemaciclib_high_MFE_TX_in_DOWN)

GSE99060_MCF7_abemaciclib_high_MFE_in_UP_fraction <- GSE99060_MCF7_abemaciclib_count_high_MFE_UP / GSE99060_MCF7_abemaciclib_total_UP
GSE99060_MCF7_abemaciclib_high_MFE_in_DOWN_fraction <- GSE99060_MCF7_abemaciclib_count_high_MFE_DOWN / GSE99060_MCF7_abemaciclib_total_DOWN

p_pool <- (GSE99060_MCF7_abemaciclib_count_high_MFE_UP + GSE99060_MCF7_abemaciclib_count_high_MFE_DOWN) /
  (GSE99060_MCF7_abemaciclib_total_UP + GSE99060_MCF7_abemaciclib_total_DOWN)

SE <- sqrt(p_pool * (1 - p_pool) * (1 / GSE99060_MCF7_abemaciclib_total_UP + 1 / GSE99060_MCF7_abemaciclib_total_DOWN))

Z <- (GSE99060_MCF7_abemaciclib_high_MFE_in_UP_fraction - GSE99060_MCF7_abemaciclib_high_MFE_in_DOWN_fraction) / SE

GSE99060_MCF7_abemaciclib_z_test_MFE_p_value <- 2 * (1 - pnorm(abs(Z)))

cat("GSE99060_MCF7_abemaciclib Two-Proportion Z-Test Results:\n")
cat("Z-test statistic:", Z, "\n")
cat("P-value from Z-test:", GSE99060_MCF7_abemaciclib_z_test_MFE_p_value, "\n")

