cat("Fraction of high MFE TX in DOWN-regulated genes:", GSE99060_MCF7_abemaciclib_high_MFE_in_DOWN_fraction, "\n")
cat("Mean of high MFE TX in UP-regulated genes:", mean(GSE99060_MCF7_abemaciclib_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of high MFE TX in DOWN-regulated genes:", mean(GSE99060_MCF7_abemaciclib_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of high MFE TX in UP-regulated genes:", calculate_mode(GSE99060_MCF7_abemaciclib_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of high MFE TX in DOWN-regulated genes:", calculate_mode(GSE99060_MCF7_abemaciclib_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")

