Counts_GSE93124_GREIN <- dplyr::rename(Counts_GSE93124_GREIN, GSM2454872 = SRR5170592_GSM2454872) %>%
  dplyr::rename(GSM2454873 = SRR5170593_GSM2454873) %>%
  dplyr::rename(GSM2454874 = SRR5170594_GSM2454874) %>%
  dplyr::rename(GSM2454875 = SRR5170595_GSM2454875) %>%
  dplyr::rename(GSM2454876 = SRR5170596_GSM2454876) %>%
  dplyr::rename(GSM2454877 = SRR5170597_GSM2454877)

GSE93124_TPM_file <- file.path(input_dir, "GSE93124_TranscriptLevel_TPM_data.csv")

if (!file.exists(GSE93124_TPM_file)) {
  stop(
    "The GSE93124 transcript-level TPM file was not found."
  )
}

GSE93124_TranscriptLevel_TPM_raw <- read.csv(
  GSE93124_TPM_file,
  header = TRUE,
  stringsAsFactors = FALSE,
  check.names = FALSE
)

colnames(GSE93124_TranscriptLevel_TPM_raw)[1] <-
  "GREIN_transcript_id"

GSE93124_TranscriptLevel_TPM <-
  GSE93124_TranscriptLevel_TPM_raw %>%
  dplyr::mutate(
    GREIN_transcript_id =
      as.character(GREIN_transcript_id),

    ensembl_transcript_id =
      sub("\\..*$", "", GREIN_transcript_id)
  )

GSE93124_SW480_crizotinib_control_samples <- c(
  "GSM2454872",
  "GSM2454873",
  "GSM2454874"
)

GSE93124_SW480_crizotinib_treatment_samples <- c(
  "GSM2454875",
  "GSM2454876",
  "GSM2454877"
)

GSE93124_SW480_crizotinib_required_samples <- c(
  GSE93124_SW480_crizotinib_control_samples,
  GSE93124_SW480_crizotinib_treatment_samples
)

GSE93124_TPM_missing_samples <- setdiff(
  GSE93124_SW480_crizotinib_required_samples,
  colnames(GSE93124_TranscriptLevel_TPM)
)

if (length(GSE93124_TPM_missing_samples) > 0) {
  stop(
    paste0(
      "Missing required GSE93124 TPM samples: ",
      paste(
        GSE93124_TPM_missing_samples,
        collapse = ", "
      )
    )
  )
}

GSE93124_TPM_MFE_annotation <-
  Table_ANNOTATED %>%
  dplyr::select(
    ensembl_transcript_id,
    Normalized_MFE
  ) %>%
  dplyr::mutate(
    ensembl_transcript_id =
      as.character(ensembl_transcript_id)
  ) %>%
  dplyr::distinct(
    ensembl_transcript_id,
    .keep_all = TRUE
  ) %>%
  dplyr::filter(
    is.finite(Normalized_MFE)
  )

GSE93124_SW480_crizotinib_TPM_MFE <-
  GSE93124_TranscriptLevel_TPM %>%
  dplyr::select(
    GREIN_transcript_id,
    ensembl_transcript_id,
    dplyr::all_of(
      GSE93124_SW480_crizotinib_required_samples
    )
  ) %>%
  dplyr::inner_join(
    GSE93124_TPM_MFE_annotation,
    by = "ensembl_transcript_id"
  )

GSE93124_SW480_crizotinib_TPM_long <-
  GSE93124_SW480_crizotinib_TPM_MFE %>%
  tidyr::pivot_longer(
    cols = dplyr::all_of(
      GSE93124_SW480_crizotinib_required_samples
    ),
    names_to = "Sample",
    values_to = "TPM"
  ) %>%
  dplyr::mutate(
    Dataset = "GSE93124",

    Treatment = "Crizotinib",

    Condition = dplyr::case_when(
      Sample %in%
        GSE93124_SW480_crizotinib_control_samples ~
        "Control",

      Sample %in%
        GSE93124_SW480_crizotinib_treatment_samples ~
        "crizotinib",

      TRUE ~ NA_character_
    ),

    TPM = as.numeric(TPM)
  ) %>%
  dplyr::filter(
    !is.na(Condition),
    is.finite(TPM),
    TPM >= 0
  ) %>%
  dplyr::group_by(
    Sample,
    Condition
  ) %>%
  dplyr::mutate(
    retained_TPM_MFE =
      sum(TPM),

    relative_transcript_abundance_MFE =
      TPM / retained_TPM_MFE,

    TPM_weighted_DGfold_contribution =
      relative_transcript_abundance_MFE *
      Normalized_MFE
  ) %>%
  dplyr::ungroup() %>%
  dplyr::mutate(
    Condition = factor(
      Condition,
      levels = c(
        "Control",
        "crizotinib"
      )
    )
  )

GSE93124_SW480_crizotinib_TPM_weight_validation <-
  GSE93124_SW480_crizotinib_TPM_long %>%
  dplyr::group_by(
    Dataset,
    Treatment,
    Sample,
    Condition
  ) %>%
  dplyr::summarise(
    annotated_transcripts =
      dplyr::n_distinct(
        ensembl_transcript_id
      ),

    expressed_annotated_transcripts =
      dplyr::n_distinct(
        ensembl_transcript_id[TPM > 0]
      ),

    retained_TPM_MFE =
      dplyr::first(retained_TPM_MFE),

    sum_MFE_weights =
      sum(
        relative_transcript_abundance_MFE
      ),

    TPM_weighted_Normalized_MFE =
      sum(
        TPM_weighted_DGfold_contribution
      ),

    .groups = "drop"
  )

