colnames(Expdata_GSE93124)[colnames(Expdata_GSE93124) == "agent:ch1"] <- "condition"

Expdata_GSE93124$condition <- gsub("control", "DMSO", Expdata_GSE93124$condition)

all(rownames(Expdata_GSE93124) %in% colnames(Counts_GSE93124_GREIN))
all(colnames(Counts_GSE93124_GREIN) %in% rownames(Expdata_GSE93124))

dds_GSE93124 <- DESeqDataSetFromMatrix(countData = Counts_GSE93124_GREIN,
                                       colData = Expdata_GSE93124,
                                       design = ~ condition)
dds_GSE93124

ntd <- normTransform(dds_GSE93124)
select <- order(rowMeans(counts(dds_GSE93124,normalized=FALSE)),
                decreasing=TRUE)[1:25]
df <- as.data.frame(colData(dds_GSE93124)[,c("condition","type")])
pheatmap(assay(ntd)[select,], cluster_rows=FALSE, show_rownames=FALSE,
         cluster_cols=FALSE, annotation_col=df)

vsd <- vst(dds_GSE93124, blind=FALSE)
head(assay(vsd), 3)

sampleDists <- dist(t(assay(vsd)))

sampleDistMatrix <- as.matrix(sampleDists)
rownames(sampleDistMatrix) <- paste(vsd$condition, vsd$type, sep="-")
colnames(sampleDistMatrix) <- NULL
colors <- colorRampPalette( rev(brewer.pal(9, "Blues")) )(255)
pheatmap(sampleDistMatrix,
         clustering_distance_rows=sampleDists,
         clustering_distance_cols=sampleDists,
         col=colors)

plotPCA(vsd, intgroup="condition")

keep <- rowSums(counts(dds_GSE93124)) >= 3
dds_GSE93124 <- dds_GSE93124[keep,]
table(keep)
nrow(dds_GSE93124)

