  dplyr::filter(ensembl_transcript_id_version %in% GSE93124_SW480_low_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_low_MFE_TX = sum(avg_counts))

GSE93124_SW480_crizotinib_low_MFE_TX_counts_fraction <- GSE93124_SW480_crizotinib_low_MFE_TX_counts$total_counts_low_MFE_TX / GSE93124_SW480_crizotinib_total_counts$total_counts
print(GSE93124_SW480_crizotinib_low_MFE_TX_counts_fraction)

p_control_low <- GSE93124_SW480_control_low_MFE_TX_counts_fraction
p_crizotinib_low <- GSE93124_SW480_crizotinib_low_MFE_TX_counts_fraction

pooled_prop_low <- (GSE93124_SW480_control_low_MFE_TX_counts$total_counts_low_MFE_TX + GSE93124_SW480_crizotinib_low_MFE_TX_counts$total_counts_low_MFE_TX) /
  (GSE93124_SW480_control_total_counts$total_counts + GSE93124_SW480_crizotinib_total_counts$total_counts)

se_low <- sqrt(pooled_prop_low * (1 - pooled_prop_low) *
                 (1 / GSE93124_SW480_control_total_counts$total_counts + 1 / GSE93124_SW480_crizotinib_total_counts$total_counts))

z_stat_low <- (p_control_low - p_crizotinib_low) / se_low

GSE93124_SW480_z_test_counts_25_p_value <- 2 * pnorm(-abs(z_stat_low))

cat("Two-proportion Z-test p-value for low MFE TX counts in Control vs crizotinib:", GSE93124_SW480_z_test_counts_25_p_value, "\n")
cat("Z-statistic for low MFE TX counts in Control vs crizotinib:", z_stat_low, "\n")

