GSE121105_trastuzumab_pertuzumab_norm_TX_counts_MFE_df <- GSE121105_norm_TX_counts_MFE_df %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length,
                GSM3426212, GSM3426213, GSM3426214, GSM3426218, GSM3426219, GSM3426220,
                Normalized_MFE) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_res_GSE121105_trastuzumab_pertuzumab$ensembl_transcript_id)

quantile_075_GSE121105_trastuzumab_pertuzumab_norm_TX_counts_MFE_df <- quantile(GSE121105_trastuzumab_pertuzumab_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

GSE121105_trastuzumab_pertuzumab_high_MFE_TX <- dplyr::filter(GSE121105_trastuzumab_pertuzumab_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE121105_trastuzumab_pertuzumab_norm_TX_counts_MFE_df)

GSE121105_trastuzumab_pertuzumab_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE121105_trastuzumab_pertuzumab_UP, ensembl_transcript_id_version %in% GSE121105_trastuzumab_pertuzumab_high_MFE_TX$ensembl_transcript_id_version)
GSE121105_trastuzumab_pertuzumab_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE121105_trastuzumab_pertuzumab_DOWN, ensembl_transcript_id_version %in% GSE121105_trastuzumab_pertuzumab_high_MFE_TX$ensembl_transcript_id_version)

GSE121105_trastuzumab_pertuzumab_total_UP <- nrow(MFE_res_GSE121105_trastuzumab_pertuzumab_UP)
GSE121105_trastuzumab_pertuzumab_total_DOWN <- nrow(MFE_res_GSE121105_trastuzumab_pertuzumab_DOWN)
GSE121105_trastuzumab_pertuzumab_count_high_MFE_UP <- nrow(GSE121105_trastuzumab_pertuzumab_high_MFE_TX_in_UP)
GSE121105_trastuzumab_pertuzumab_count_high_MFE_DOWN <- nrow(GSE121105_trastuzumab_pertuzumab_high_MFE_TX_in_DOWN)

p_UP <- GSE121105_trastuzumab_pertuzumab_count_high_MFE_UP / GSE121105_trastuzumab_pertuzumab_total_UP
p_DOWN <- GSE121105_trastuzumab_pertuzumab_count_high_MFE_DOWN / GSE121105_trastuzumab_pertuzumab_total_DOWN

P_pool <- (GSE121105_trastuzumab_pertuzumab_count_high_MFE_UP + GSE121105_trastuzumab_pertuzumab_count_high_MFE_DOWN) /
  (GSE121105_trastuzumab_pertuzumab_total_UP + GSE121105_trastuzumab_pertuzumab_total_DOWN)

Z <- (p_UP - p_DOWN) / sqrt(P_pool * (1 - P_pool) * (1/GSE121105_trastuzumab_pertuzumab_total_UP + 1/GSE121105_trastuzumab_pertuzumab_total_DOWN))

GSE121105_trastuzumab_pertuzumab_z_test_MFE_p_value <- 2 * (1 - pnorm(abs(Z)))

cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE121105_trastuzumab_pertuzumab_z_test_MFE_p_value, "\n")

