GSE121105_trastuzumab_pertuzumab_low_MFE_TX_total <- dplyr::filter(GSE121105_trastuzumab_pertuzumab_norm_TX_counts_MFE_df, Normalized_MFE < GSE121105_trastuzumab_pertuzumab_MFE_all_TX_25_percentile)

GSE121105_trastuzumab_pertuzumab_control_total_counts <- dplyr::filter(GSE121105_trastuzumab_pertuzumab_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE121105_trastuzumab_pertuzumab_control_low_MFE_TX_counts <- dplyr::filter(GSE121105_trastuzumab_pertuzumab_norm_TX_aggregated_data_avg_counts, condition == "Control") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE121105_trastuzumab_pertuzumab_low_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_low_MFE_TX = sum(avg_counts))

GSE121105_trastuzumab_pertuzumab_control_low_MFE_TX_counts_fraction <- GSE121105_trastuzumab_pertuzumab_control_low_MFE_TX_counts$total_counts_low_MFE_TX / GSE121105_trastuzumab_pertuzumab_control_total_counts$total_counts
print(GSE121105_trastuzumab_pertuzumab_control_low_MFE_TX_counts_fraction)

GSE121105_trastuzumab_pertuzumab_trastuzumab_total_counts <- dplyr::filter(GSE121105_trastuzumab_pertuzumab_norm_TX_aggregated_data_avg_counts, condition == "trastuzumab_pertuzumab") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE121105_trastuzumab_pertuzumab_trastuzumab_low_MFE_TX_counts <- dplyr::filter(GSE121105_trastuzumab_pertuzumab_norm_TX_aggregated_data_avg_counts, condition == "trastuzumab_pertuzumab") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE121105_trastuzumab_pertuzumab_low_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_low_MFE_TX = sum(avg_counts))

GSE121105_trastuzumab_pertuzumab_trastuzumab_low_MFE_TX_counts_fraction <- GSE121105_trastuzumab_pertuzumab_trastuzumab_low_MFE_TX_counts$total_counts_low_MFE_TX / GSE121105_trastuzumab_pertuzumab_trastuzumab_total_counts$total_counts
print(GSE121105_trastuzumab_pertuzumab_trastuzumab_low_MFE_TX_counts_fraction)

p_control <- GSE121105_trastuzumab_pertuzumab_control_low_MFE_TX_counts_fraction
p_trastuzumab <- GSE121105_trastuzumab_pertuzumab_trastuzumab_low_MFE_TX_counts_fraction

P_pool <- (GSE121105_trastuzumab_pertuzumab_control_low_MFE_TX_counts$total_counts_low_MFE_TX + GSE121105_trastuzumab_pertuzumab_trastuzumab_low_MFE_TX_counts$total_counts_low_MFE_TX) /
  (GSE121105_trastuzumab_pertuzumab_control_total_counts$total_counts + GSE121105_trastuzumab_pertuzumab_trastuzumab_total_counts$total_counts)

Z <- (p_control - p_trastuzumab) / sqrt(P_pool * (1 - P_pool) * (1/GSE121105_trastuzumab_pertuzumab_control_total_counts$total_counts + 1/GSE121105_trastuzumab_pertuzumab_trastuzumab_total_counts$total_counts))

GSE121105_trastuzumab_pertuzumab_z_test_counts_25_p_value <- 2 * (1 - pnorm(abs(Z)))

cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE121105_trastuzumab_pertuzumab_z_test_counts_25_p_value, "\n")

cat("GSE121105_trastuzumab_pertuzumab control low MFE TX as fraction of total counts:", GSE121105_trastuzumab_pertuzumab_control_low_MFE_TX_counts_fraction, "\n")
cat("GSE121105_trastuzumab_pertuzumab trastuzumab low MFE TX as fraction of total counts:", GSE121105_trastuzumab_pertuzumab_trastuzumab_low_MFE_TX_counts_fraction, "\n")
cat("GSE121105_trastuzumab_pertuzumab net change counts low MFE TX drug vs control:", GSE121105_trastuzumab_pertuzumab_trastuzumab_low_MFE_TX_counts_fraction - GSE121105_trastuzumab_pertuzumab_control_low_MFE_TX_counts_fraction, "\n")

