print(ViolinPlot_GSE73318_HCT_116)

MFE_res_GSE73318_HCT_116_UP <- dplyr::filter(MFE_res_GSE73318_HCT_116, log2FoldChange > 0)
Mean_MFE_res_GSE73318_HCT_116_UP <- mean(MFE_res_GSE73318_HCT_116_UP$Normalized_MFE, na.rm = TRUE)

MFE_res_GSE73318_HCT_116_DOWN <- dplyr::filter(MFE_res_GSE73318_HCT_116, log2FoldChange < 0)
Mean_MFE_res_GSE73318_HCT_116_DOWN <- mean(MFE_res_GSE73318_HCT_116_DOWN$Normalized_MFE, na.rm = TRUE)

TTEST_MFE_res_GSE73318_HCT_116_all_UP_vs_DOWN <- t.test(MFE_res_GSE73318_HCT_116_DOWN$Normalized_MFE, MFE_res_GSE73318_HCT_116_UP$Normalized_MFE, paired=FALSE)
print(TTEST_MFE_res_GSE73318_HCT_116_all_UP_vs_DOWN)

ks_test_res_GSE73318_HCT_116_all_UP_vs_DOWN <- ks.test(MFE_res_GSE73318_HCT_116_DOWN$Normalized_MFE, MFE_res_GSE73318_HCT_116_UP$Normalized_MFE)
print(ks_test_res_GSE73318_HCT_116_all_UP_vs_DOWN)

quantile_075_MFE_res_GSE73318_HCT_116_UP <- quantile(MFE_res_GSE73318_HCT_116_UP$Normalized_MFE, probs = c(0.75))
quantile_075_MFE_res_GSE73318_HCT_116_DOWN <- quantile(MFE_res_GSE73318_HCT_116_DOWN$Normalized_MFE, probs = c(0.75))
ks_test_MFE_075_above <- ks.test(MFE_res_GSE73318_HCT_116_UP$Normalized_MFE[MFE_res_GSE73318_HCT_116_UP$Normalized_MFE >= quantile_075_MFE_res_GSE73318_HCT_116_UP],
                                 MFE_res_GSE73318_HCT_116_DOWN$Normalized_MFE[MFE_res_GSE73318_HCT_116_DOWN$Normalized_MFE >= quantile_075_MFE_res_GSE73318_HCT_116_DOWN])
print(ks_test_MFE_075_above)

quantile_025_MFE_res_GSE73318_HCT_116_UP <- quantile(MFE_res_GSE73318_HCT_116_UP$Normalized_MFE, probs = c(0.25))
quantile_025_MFE_res_GSE73318_HCT_116_DOWN <- quantile(MFE_res_GSE73318_HCT_116_DOWN$Normalized_MFE, probs = c(0.25))
ks_test_MFE_025_below <- ks.test(MFE_res_GSE73318_HCT_116_UP$Normalized_MFE[MFE_res_GSE73318_HCT_116_UP$Normalized_MFE <= quantile_025_MFE_res_GSE73318_HCT_116_UP],
                                 MFE_res_GSE73318_HCT_116_DOWN$Normalized_MFE[MFE_res_GSE73318_HCT_116_DOWN$Normalized_MFE <= quantile_025_MFE_res_GSE73318_HCT_116_DOWN])
print(ks_test_MFE_025_below)

upregulated <- data.frame(MFE = MFE_res_GSE73318_HCT_116_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_res_GSE73318_HCT_116_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

GSE73318_HCT_116_observed_diff <- mean(MFE_res_GSE73318_HCT_116_UP$Normalized_MFE, na.rm = TRUE) - mean(MFE_res_GSE73318_HCT_116_DOWN$Normalized_MFE, na.rm = TRUE)

n_permutations <- 10000

GSE73318_HCT_116_permuted_diffs <- numeric(n_permutations)

set.seed(123)
for (i in 1:n_permutations) {
  combined_data <- combined_data %>%
    mutate(Permuted_Group = sample(Group))

  permuted_up_mean <- mean(combined_data$MFE[combined_data$Permuted_Group == "Up"], na.rm = TRUE)
  permuted_down_mean <- mean(combined_data$MFE[combined_data$Permuted_Group == "Down"], na.rm = TRUE)

  GSE73318_HCT_116_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

GSE73318_HCT_116_p_value <- (sum(abs(GSE73318_HCT_116_permuted_diffs) >= abs(GSE73318_HCT_116_observed_diff)) + 1) / (n_permutations + 1)

cat("Observed difference in GSE73318_HCT_116 means MFE_UP - MFE_DOWN:", GSE73318_HCT_116_observed_diff, "\n")
cat("GSE73318_HCT_116 P-value from permutation test:", GSE73318_HCT_116_p_value, "\n")

GSE73318_norm_TX_counts <- counts(dds_GSE73318, normalized=TRUE)
GSE73318_norm_TX_counts_df <- as.data.frame(GSE73318_norm_TX_counts)
GSE73318_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE73318_norm_TX_counts_df)
rownames(GSE73318_norm_TX_counts_df) <- NULL

GSE73318_norm_TX_counts_df <- GSE73318_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE73318_norm_TX_counts_df), "ensembl_transcript_id"))]

GSE73318_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE73318_norm_TX_counts_df$ensembl_transcript_id)

GSE73318_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE73318_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length,
                GSM1890694, GSM1890695, GSM1890696, GSM1890697, GSM1890698, GSM1890699,
                Normalized_MFE)

GSE73318_HCT_116_norm_TX_counts_MFE_df <- GSE73318_norm_TX_counts_MFE_df %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length,
                GSM1890694, GSM1890695, GSM1890696, GSM1890697, GSM1890698, GSM1890699,
                Normalized_MFE) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_res_GSE73318_HCT_116$ensembl_transcript_id)

quantile_075_GSE73318_HCT_116_norm_TX_counts_MFE_df <- quantile(GSE73318_HCT_116_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

GSE73318_HCT_116_high_MFE_TX <- dplyr::filter(GSE73318_HCT_116_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE73318_HCT_116_norm_TX_counts_MFE_df)

GSE73318_HCT_116_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE73318_HCT_116_UP, ensembl_transcript_id_version %in% GSE73318_HCT_116_high_MFE_TX$ensembl_transcript_id_version)
GSE73318_HCT_116_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE73318_HCT_116_DOWN, ensembl_transcript_id_version %in% GSE73318_HCT_116_high_MFE_TX$ensembl_transcript_id_version)

GSE73318_HCT_116_total_UP <- nrow(MFE_res_GSE73318_HCT_116_UP)
GSE73318_HCT_116_total_DOWN <- nrow(MFE_res_GSE73318_HCT_116_DOWN)
GSE73318_HCT_116_count_high_MFE_UP <- nrow(GSE73318_HCT_116_high_MFE_TX_in_UP)
GSE73318_HCT_116_count_high_MFE_DOWN <- nrow(GSE73318_HCT_116_high_MFE_TX_in_DOWN)

p_UP <- GSE73318_HCT_116_count_high_MFE_UP / GSE73318_HCT_116_total_UP
p_DOWN <- GSE73318_HCT_116_count_high_MFE_DOWN / GSE73318_HCT_116_total_DOWN

P_pool <- (GSE73318_HCT_116_count_high_MFE_UP + GSE73318_HCT_116_count_high_MFE_DOWN) /
  (GSE73318_HCT_116_total_UP + GSE73318_HCT_116_total_DOWN)

Z <- (p_UP - p_DOWN) / sqrt(P_pool * (1 - P_pool) * (1/GSE73318_HCT_116_total_UP + 1/GSE73318_HCT_116_total_DOWN))

GSE73318_HCT_116_z_test_MFE_p_value <- 2 * (1 - pnorm(abs(Z)))

cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE73318_HCT_116_z_test_MFE_p_value, "\n")

GSE73318_HCT_116_high_MFE_in_UP_fraction <- GSE73318_HCT_116_count_high_MFE_UP / GSE73318_HCT_116_total_UP
GSE73318_HCT_116_high_MFE_in_DOWN_fraction <- GSE73318_HCT_116_count_high_MFE_DOWN / GSE73318_HCT_116_total_DOWN

cat("Fraction of GSE73318_HCT_116 high MFE TX in UP-regulated genes:", GSE73318_HCT_116_high_MFE_in_UP_fraction, "\n")
cat("Fraction of GSE73318_HCT_116 high MFE TX in DOWN-regulated genes:", GSE73318_HCT_116_high_MFE_in_DOWN_fraction, "\n")
cat("Mean of GSE73318_HCT_116 high MFE TX in UP-regulated genes:", mean(GSE73318_HCT_116_high_MFE_TX_in_UP$Normalized_MFE), "\n")
