quantile_075_MFE_res_GSE73318_HT_29_UP <- quantile(MFE_res_GSE73318_HT_29_UP$Normalized_MFE, probs = c(0.75))
quantile_075_MFE_res_GSE73318_HT_29_DOWN <- quantile(MFE_res_GSE73318_HT_29_DOWN$Normalized_MFE, probs = c(0.75))
ks_test_MFE_075_above <- ks.test(MFE_res_GSE73318_HT_29_UP$Normalized_MFE[MFE_res_GSE73318_HT_29_UP$Normalized_MFE >= quantile_075_MFE_res_GSE73318_HT_29_UP],
                                 MFE_res_GSE73318_HT_29_DOWN$Normalized_MFE[MFE_res_GSE73318_HT_29_DOWN$Normalized_MFE >= quantile_075_MFE_res_GSE73318_HT_29_DOWN])
print(ks_test_MFE_075_above)

quantile_025_MFE_res_GSE73318_HT_29_UP <- quantile(MFE_res_GSE73318_HT_29_UP$Normalized_MFE, probs = c(0.25))
quantile_025_MFE_res_GSE73318_HT_29_DOWN <- quantile(MFE_res_GSE73318_HT_29_DOWN$Normalized_MFE, probs = c(0.25))
ks_test_MFE_025_below <- ks.test(MFE_res_GSE73318_HT_29_UP$Normalized_MFE[MFE_res_GSE73318_HT_29_UP$Normalized_MFE <= quantile_025_MFE_res_GSE73318_HT_29_UP],
                                 MFE_res_GSE73318_HT_29_DOWN$Normalized_MFE[MFE_res_GSE73318_HT_29_DOWN$Normalized_MFE <= quantile_025_MFE_res_GSE73318_HT_29_DOWN])
print(ks_test_MFE_025_below)

upregulated <- data.frame(MFE = MFE_res_GSE73318_HT_29_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_res_GSE73318_HT_29_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

GSE73318_HT_29_observed_diff <- mean(MFE_res_GSE73318_HT_29_UP$Normalized_MFE, na.rm = TRUE) - mean(MFE_res_GSE73318_HT_29_DOWN$Normalized_MFE, na.rm = TRUE)

n_permutations <- 10000

GSE73318_HT_29_permuted_diffs <- numeric(n_permutations)

set.seed(123)
for (i in 1:n_permutations) {
  combined_data <- combined_data %>%
    mutate(Permuted_Group = sample(Group))

  permuted_up_mean <- mean(combined_data$MFE[combined_data$Permuted_Group == "Up"], na.rm = TRUE)
  permuted_down_mean <- mean(combined_data$MFE[combined_data$Permuted_Group == "Down"], na.rm = TRUE)

  GSE73318_HT_29_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

GSE73318_HT_29_p_value <- (sum(abs(GSE73318_HT_29_permuted_diffs) >= abs(GSE73318_HT_29_observed_diff)) + 1) / (n_permutations + 1)

cat("Observed difference in GSE73318_HT_29 means MFE_UP - MFE_DOWN:", GSE73318_HT_29_observed_diff, "\n")
cat("GSE73318_HT_29 P-value from permutation test:", GSE73318_HT_29_p_value, "\n")

