GSE73318_HT_29_total_UP <- nrow(MFE_res_GSE73318_HT_29_UP)
GSE73318_HT_29_total_DOWN <- nrow(MFE_res_GSE73318_HT_29_DOWN)
GSE73318_HT_29_count_high_MFE_UP <- nrow(GSE73318_HT_29_high_MFE_TX_in_UP)
GSE73318_HT_29_count_high_MFE_DOWN <- nrow(GSE73318_HT_29_high_MFE_TX_in_DOWN)

p_UP <- GSE73318_HT_29_count_high_MFE_UP / GSE73318_HT_29_total_UP
p_DOWN <- GSE73318_HT_29_count_high_MFE_DOWN / GSE73318_HT_29_total_DOWN

P_pool <- (GSE73318_HT_29_count_high_MFE_UP + GSE73318_HT_29_count_high_MFE_DOWN) /
  (GSE73318_HT_29_total_UP + GSE73318_HT_29_total_DOWN)

Z <- (p_UP - p_DOWN) / sqrt(P_pool * (1 - P_pool) * (1/GSE73318_HT_29_total_UP + 1/GSE73318_HT_29_total_DOWN))

