print(GSE73318_COLO_205_COLO_205_low_MFE_TX_counts_fraction)

p_control <- GSE73318_COLO_205_control_low_MFE_TX_counts_fraction
p_COLO_205 <- GSE73318_COLO_205_COLO_205_low_MFE_TX_counts_fraction

P_pool <- (GSE73318_COLO_205_control_low_MFE_TX_counts$total_counts_low_MFE_TX + GSE73318_COLO_205_COLO_205_low_MFE_TX_counts$total_counts_low_MFE_TX) /
  (GSE73318_COLO_205_control_total_counts$total_counts + GSE73318_COLO_205_COLO_205_total_counts$total_counts)

var_control <- p_control * (1 - p_control) / GSE73318_COLO_205_control_total_counts$total_counts
var_COLO_205 <- p_COLO_205 * (1 - p_COLO_205) / GSE73318_COLO_205_COLO_205_total_counts$total_counts

P_pool_variance <- P_pool * (1 - P_pool) * (1 / GSE73318_COLO_205_control_total_counts$total_counts + 1 / GSE73318_COLO_205_COLO_205_total_counts$total_counts)

Z <- (p_control - p_COLO_205) / sqrt(P_pool_variance)

GSE73318_COLO_205_z_test_counts_25_p_value <- 2 * (1 - pnorm(abs(Z)))

cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE73318_COLO_205_z_test_counts_25_p_value, "\n")

