cat("GSE73318_COLO_205 net change counts low MFE TX drug vs control:", GSE73318_COLO_205_COLO_205_low_MFE_TX_counts_fraction - GSE73318_COLO_205_control_low_MFE_TX_counts_fraction, "\n")

