downregulated <- data.frame(MFE = MFE_res_GSE73318_COLO_320_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

GSE73318_COLO_320_observed_diff <- mean(MFE_res_GSE73318_COLO_320_UP$Normalized_MFE, na.rm = TRUE) - mean(MFE_res_GSE73318_COLO_320_DOWN$Normalized_MFE, na.rm = TRUE)

n_permutations <- 10000

GSE73318_COLO_320_permuted_diffs <- numeric(n_permutations)

set.seed(123)
for (i in 1:n_permutations) {
  combined_data <- combined_data %>%
    mutate(Permuted_Group = sample(Group))

  permuted_up_mean <- mean(combined_data$MFE[combined_data$Permuted_Group == "Up"], na.rm = TRUE)
  permuted_down_mean <- mean(combined_data$MFE[combined_data$Permuted_Group == "Down"], na.rm = TRUE)

  GSE73318_COLO_320_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

GSE73318_COLO_320_p_value <- (sum(abs(GSE73318_COLO_320_permuted_diffs) >= abs(GSE73318_COLO_320_observed_diff)) + 1) / (n_permutations + 1)

cat("Observed difference in GSE73318_COLO_320 means MFE_UP - MFE_DOWN:", GSE73318_COLO_320_observed_diff, "\n")
cat("GSE73318_COLO_320 P-value from permutation test:", GSE73318_COLO_320_p_value, "\n")

