GSE126779_DU145_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE126779_DU145_DOWN, ensembl_transcript_id_version %in% GSE126779_DU145_high_MFE_TX$ensembl_transcript_id_version)

GSE126779_DU145_total_UP <- nrow(MFE_res_GSE126779_DU145_UP)
GSE126779_DU145_total_DOWN <- nrow(MFE_res_GSE126779_DU145_DOWN)
GSE126779_DU145_count_high_MFE_UP <- nrow(GSE126779_DU145_high_MFE_TX_in_UP)
GSE126779_DU145_count_high_MFE_DOWN <- nrow(GSE126779_DU145_high_MFE_TX_in_DOWN)

p_UP <- GSE126779_DU145_count_high_MFE_UP / GSE126779_DU145_total_UP
p_DOWN <- GSE126779_DU145_count_high_MFE_DOWN / GSE126779_DU145_total_DOWN

P_pool <- (GSE126779_DU145_count_high_MFE_UP + GSE126779_DU145_count_high_MFE_DOWN) /
  (GSE126779_DU145_total_UP + GSE126779_DU145_total_DOWN)

Z <- (p_UP - p_DOWN) / sqrt(P_pool * (1 - P_pool) * (1/GSE126779_DU145_total_UP + 1/GSE126779_DU145_total_DOWN))

GSE126779_DU145_z_test_MFE_p_value <- 2 * (1 - pnorm(abs(Z)))

