MFE_res_GSE126779_PC3 <- dplyr::inner_join(Table_ANNOTATED, res_GSE126779_PC3, by="ensembl_transcript_id") %>%
  dplyr::filter(padj < 0.05) %>%
  dplyr::filter(log2FoldChange > -10 & log2FoldChange < 10)

Plot_GSE126779_PC3 <- ggplot(MFE_res_GSE126779_PC3, aes(y=Normalized_MFE, x=log2FoldChange)) +
  geom_point(size=1.5, alpha=0.3)+
  theme_classic() +
  theme(legend.position="none") +
