cat("Mode of GSE126779_PC3 high MFE TX in DOWN-regulated genes:", calculate_mode(GSE126779_PC3_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")

MFE_res_GSE126779_PC3$above_quantile_075 <- MFE_res_GSE126779_PC3$Normalized_MFE > quantile_075_GSE126779_PC3_norm_TX_counts_MFE_df

