print(GSE115550_JQ1_50_nM_JQ1_50_nM_low_MFE_TX_counts_fraction)

p_control <- GSE115550_JQ1_50_nM_control_low_MFE_TX_counts_fraction
p_JQ1_50_nM <- GSE115550_JQ1_50_nM_JQ1_50_nM_low_MFE_TX_counts_fraction

