upregulated <- data.frame(MFE = MFE_res_GSE115550_JQ1_500_nM_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_res_GSE115550_JQ1_500_nM_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

GSE115550_JQ1_500_nM_observed_diff <- mean(MFE_res_GSE115550_JQ1_500_nM_UP$Normalized_MFE, na.rm = TRUE) - mean(MFE_res_GSE115550_JQ1_500_nM_DOWN$Normalized_MFE, na.rm = TRUE)

n_permutations <- 10000

GSE115550_JQ1_500_nM_permuted_diffs <- numeric(n_permutations)

set.seed(123)
for (i in 1:n_permutations) {
  combined_data <- combined_data %>%
    mutate(Permuted_Group = sample(Group))

  permuted_up_mean <- mean(combined_data$MFE[combined_data$Permuted_Group == "Up"], na.rm = TRUE)
  permuted_down_mean <- mean(combined_data$MFE[combined_data$Permuted_Group == "Down"], na.rm = TRUE)

  GSE115550_JQ1_500_nM_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

GSE115550_JQ1_500_nM_p_value <- (sum(abs(GSE115550_JQ1_500_nM_permuted_diffs) >= abs(GSE115550_JQ1_500_nM_observed_diff)) + 1) / (n_permutations + 1)

cat("Observed difference in GSE115550_JQ1_500_nM means MFE_UP - MFE_DOWN:", GSE115550_JQ1_500_nM_observed_diff, "\n")
cat("GSE115550_JQ1_500_nM P-value from permutation test:", GSE115550_JQ1_500_nM_p_value, "\n")

