GSE115550_JQ1_500_nM_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE115550_JQ1_500_nM_DOWN, ensembl_transcript_id_version %in% GSE115550_JQ1_500_nM_high_MFE_TX$ensembl_transcript_id_version)

GSE115550_JQ1_500_nM_total_UP <- nrow(MFE_res_GSE115550_JQ1_500_nM_UP)
GSE115550_JQ1_500_nM_total_DOWN <- nrow(MFE_res_GSE115550_JQ1_500_nM_DOWN)
GSE115550_JQ1_500_nM_count_high_MFE_UP <- nrow(GSE115550_JQ1_500_nM_high_MFE_TX_in_UP)
GSE115550_JQ1_500_nM_count_high_MFE_DOWN <- nrow(GSE115550_JQ1_500_nM_high_MFE_TX_in_DOWN)

p_UP <- GSE115550_JQ1_500_nM_count_high_MFE_UP / GSE115550_JQ1_500_nM_total_UP
p_DOWN <- GSE115550_JQ1_500_nM_count_high_MFE_DOWN / GSE115550_JQ1_500_nM_total_DOWN

P_pool <- (GSE115550_JQ1_500_nM_count_high_MFE_UP + GSE115550_JQ1_500_nM_count_high_MFE_DOWN) /
  (GSE115550_JQ1_500_nM_total_UP + GSE115550_JQ1_500_nM_total_DOWN)

Z <- (p_UP - p_DOWN) / sqrt(P_pool * (1 - P_pool) * (1/GSE115550_JQ1_500_nM_total_UP + 1/GSE115550_JQ1_500_nM_total_DOWN))

GSE115550_JQ1_500_nM_z_test_MFE_p_value <- 2 * (1 - pnorm(abs(Z)))

cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE115550_JQ1_500_nM_z_test_MFE_p_value, "\n")

GSE115550_JQ1_500_nM_high_MFE_in_UP_fraction <- GSE115550_JQ1_500_nM_count_high_MFE_UP / GSE115550_JQ1_500_nM_total_UP
GSE115550_JQ1_500_nM_high_MFE_in_DOWN_fraction <- GSE115550_JQ1_500_nM_count_high_MFE_DOWN / GSE115550_JQ1_500_nM_total_DOWN

cat("Fraction of GSE115550_JQ1_500_nM high MFE TX in UP-regulated genes:", GSE115550_JQ1_500_nM_high_MFE_in_UP_fraction, "\n")
cat("Fraction of GSE115550_JQ1_500_nM high MFE TX in DOWN-regulated genes:", GSE115550_JQ1_500_nM_high_MFE_in_DOWN_fraction, "\n")
cat("Mean of GSE115550_JQ1_500_nM high MFE TX in UP-regulated genes:", mean(GSE115550_JQ1_500_nM_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of GSE115550_JQ1_500_nM high MFE TX in DOWN-regulated genes:", mean(GSE115550_JQ1_500_nM_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of GSE115550_JQ1_500_nM high MFE TX in UP-regulated genes:", calculate_mode(GSE115550_JQ1_500_nM_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of GSE115550_JQ1_500_nM high MFE TX in DOWN-regulated genes:", calculate_mode(GSE115550_JQ1_500_nM_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")

