quantile_075_MFE_res_GSE115550_MS645_50_nM_DOWN <- quantile(MFE_res_GSE115550_MS645_50_nM_DOWN$Normalized_MFE, probs = c(0.75))
ks_test_MFE_075_above <- ks.test(MFE_res_GSE115550_MS645_50_nM_UP$Normalized_MFE[MFE_res_GSE115550_MS645_50_nM_UP$Normalized_MFE >= quantile_075_MFE_res_GSE115550_MS645_50_nM_UP],
