print(ks_test_MFE_075_above)

quantile_025_MFE_res_GSE115550_MS645_50_nM_UP <- quantile(MFE_res_GSE115550_MS645_50_nM_UP$Normalized_MFE, probs = c(0.25))
quantile_025_MFE_res_GSE115550_MS645_50_nM_DOWN <- quantile(MFE_res_GSE115550_MS645_50_nM_DOWN$Normalized_MFE, probs = c(0.25))
ks_test_MFE_025_below <- ks.test(MFE_res_GSE115550_MS645_50_nM_UP$Normalized_MFE[MFE_res_GSE115550_MS645_50_nM_UP$Normalized_MFE <= quantile_025_MFE_res_GSE115550_MS645_50_nM_UP],
                                 MFE_res_GSE115550_MS645_50_nM_DOWN$Normalized_MFE[MFE_res_GSE115550_MS645_50_nM_DOWN$Normalized_MFE <= quantile_025_MFE_res_GSE115550_MS645_50_nM_DOWN])
print(ks_test_MFE_025_below)

upregulated <- data.frame(MFE = MFE_res_GSE115550_MS645_50_nM_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_res_GSE115550_MS645_50_nM_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

GSE115550_MS645_50_nM_observed_diff <- mean(MFE_res_GSE115550_MS645_50_nM_UP$Normalized_MFE, na.rm = TRUE) - mean(MFE_res_GSE115550_MS645_50_nM_DOWN$Normalized_MFE, na.rm = TRUE)

n_permutations <- 10000

GSE115550_MS645_50_nM_permuted_diffs <- numeric(n_permutations)

combined_data <- combined_data[
  is.finite(combined_data$MFE),
  ,
  drop = FALSE
]

set.seed(123)

for (i in seq_len(n_permutations)) {

  permuted_group <- base::sample(
    combined_data$Group,
    size = nrow(combined_data),
    replace = FALSE
  )

  permuted_up_mean <- mean(
    combined_data$MFE[
      permuted_group == "Up"
    ]
  )

  permuted_down_mean <- mean(
    combined_data$MFE[
      permuted_group == "Down"
    ]
  )

  GSE115550_MS645_50_nM_permuted_diffs[i] <-
    permuted_up_mean - permuted_down_mean
}

GSE115550_MS645_50_nM_p_value <- (sum(abs(GSE115550_MS645_50_nM_permuted_diffs) >= abs(GSE115550_MS645_50_nM_observed_diff)) + 1) / (n_permutations + 1)

cat("Observed difference in GSE115550_MS645_50_nM means MFE_UP - MFE_DOWN:", GSE115550_MS645_50_nM_observed_diff, "\n")
cat("GSE115550_MS645_50_nM P-value from permutation test:", GSE115550_MS645_50_nM_p_value, "\n")

GSE115550_norm_TX_counts <- counts(dds_GSE115550, normalized=TRUE)
GSE115550_norm_TX_counts_df <- as.data.frame(GSE115550_norm_TX_counts)
GSE115550_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE115550_norm_TX_counts_df)
rownames(GSE115550_norm_TX_counts_df) <- NULL

GSE115550_norm_TX_counts_df <- GSE115550_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE115550_norm_TX_counts_df), "ensembl_transcript_id"))]

GSE115550_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE115550_norm_TX_counts_df$ensembl_transcript_id)

GSE115550_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE115550_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length,
                GSM3181856, GSM3181861, GSM3181866, GSM3181859, GSM3181864, GSM3181869,
                Normalized_MFE)

GSE115550_MS645_50_nM_norm_TX_counts_MFE_df <- GSE115550_norm_TX_counts_MFE_df %>%
