GSE115550_MS645_50_nM_high_MFE_TX <- dplyr::filter(GSE115550_MS645_50_nM_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE115550_MS645_50_nM_norm_TX_counts_MFE_df)

GSE115550_MS645_50_nM_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE115550_MS645_50_nM_UP, ensembl_transcript_id_version %in% GSE115550_MS645_50_nM_high_MFE_TX$ensembl_transcript_id_version)
GSE115550_MS645_50_nM_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE115550_MS645_50_nM_DOWN, ensembl_transcript_id_version %in% GSE115550_MS645_50_nM_high_MFE_TX$ensembl_transcript_id_version)

GSE115550_MS645_50_nM_total_UP <- nrow(MFE_res_GSE115550_MS645_50_nM_UP)
GSE115550_MS645_50_nM_total_DOWN <- nrow(MFE_res_GSE115550_MS645_50_nM_DOWN)
GSE115550_MS645_50_nM_count_high_MFE_UP <- nrow(GSE115550_MS645_50_nM_high_MFE_TX_in_UP)
GSE115550_MS645_50_nM_count_high_MFE_DOWN <- nrow(GSE115550_MS645_50_nM_high_MFE_TX_in_DOWN)

p_UP <- GSE115550_MS645_50_nM_count_high_MFE_UP / GSE115550_MS645_50_nM_total_UP
p_DOWN <- GSE115550_MS645_50_nM_count_high_MFE_DOWN / GSE115550_MS645_50_nM_total_DOWN

P_pool <- (GSE115550_MS645_50_nM_count_high_MFE_UP + GSE115550_MS645_50_nM_count_high_MFE_DOWN) /
  (GSE115550_MS645_50_nM_total_UP + GSE115550_MS645_50_nM_total_DOWN)

Z <- (p_UP - p_DOWN) / sqrt(P_pool * (1 - P_pool) * (1/GSE115550_MS645_50_nM_total_UP + 1/GSE115550_MS645_50_nM_total_DOWN))

GSE115550_MS645_50_nM_z_test_MFE_p_value <- 2 * (1 - pnorm(abs(Z)))

cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE115550_MS645_50_nM_z_test_MFE_p_value, "\n")

GSE115550_MS645_50_nM_high_MFE_in_UP_fraction <- GSE115550_MS645_50_nM_count_high_MFE_UP / GSE115550_MS645_50_nM_total_UP
GSE115550_MS645_50_nM_high_MFE_in_DOWN_fraction <- GSE115550_MS645_50_nM_count_high_MFE_DOWN / GSE115550_MS645_50_nM_total_DOWN

