p_MS645_50_nM <- GSE115550_MS645_50_nM_MS645_50_nM_low_MFE_TX_counts_fraction

P_pool <- (GSE115550_MS645_50_nM_control_low_MFE_TX_counts$total_counts_low_MFE_TX + GSE115550_MS645_50_nM_MS645_50_nM_low_MFE_TX_counts$total_counts_low_MFE_TX) /
  (GSE115550_MS645_50_nM_control_total_counts$total_counts + GSE115550_MS645_50_nM_MS645_50_nM_total_counts$total_counts)

var_control <- p_control * (1 - p_control) / GSE115550_MS645_50_nM_control_total_counts$total_counts
var_MS645_50_nM <- p_MS645_50_nM * (1 - p_MS645_50_nM) / GSE115550_MS645_50_nM_MS645_50_nM_total_counts$total_counts

P_pool_variance <- P_pool * (1 - P_pool) * (1 / GSE115550_MS645_50_nM_control_total_counts$total_counts + 1 / GSE115550_MS645_50_nM_MS645_50_nM_total_counts$total_counts)

Z <- (p_control - p_MS645_50_nM) / sqrt(P_pool_variance)

GSE115550_MS645_50_nM_z_test_counts_25_p_value <- 2 * (1 - pnorm(abs(Z)))

cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE115550_MS645_50_nM_z_test_counts_25_p_value, "\n")

cat("GSE115550_MS645_50_nM control low MFE TX as fraction of total counts:", GSE115550_MS645_50_nM_control_low_MFE_TX_counts_fraction, "\n")
cat("GSE115550_MS645_50_nM DU145 low MFE TX as fraction of total counts:", GSE115550_MS645_50_nM_MS645_50_nM_low_MFE_TX_counts_fraction, "\n")
cat("GSE115550_MS645_50_nM net change counts low MFE TX drug vs control:", GSE115550_MS645_50_nM_MS645_50_nM_low_MFE_TX_counts_fraction - GSE115550_MS645_50_nM_control_low_MFE_TX_counts_fraction, "\n")

