P_pool <- (GSE115550_MS645_500_nM_control_high_MFE_TX_counts$total_counts_high_MFE_TX + GSE115550_MS645_500_nM_MS645_500_nM_high_MFE_TX_counts$total_counts_high_MFE_TX) /
  (GSE115550_MS645_500_nM_control_total_counts$total_counts + GSE115550_MS645_500_nM_MS645_500_nM_total_counts$total_counts)

if (GSE115550_MS645_500_nM_control_total_counts$total_counts > 0 & GSE115550_MS645_500_nM_MS645_500_nM_total_counts$total_counts > 0) {
  Z <- (p_control - p_MS645_500_nM) / sqrt(P_pool * (1 - P_pool) * (1/GSE115550_MS645_500_nM_control_total_counts$total_counts + 1/GSE115550_MS645_500_nM_MS645_500_nM_total_counts$total_counts))
  GSE115550_MS645_500_nM_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(Z)))
} else {
  Z <- NA
  GSE115550_MS645_500_nM_z_test_counts_75_p_value <- NA
}

GSE115550_MS645_500_nM_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(Z)))

cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE115550_MS645_500_nM_z_test_counts_75_p_value, "\n")

cat("GSE115550_MS645_500_nM control high MFE TX as fraction of total counts:", GSE115550_MS645_500_nM_control_high_MFE_TX_counts_fraction, "\n")
cat("GSE115550_MS645_500_nM DU145 high MFE TX as fraction of total counts:", GSE115550_MS645_500_nM_MS645_500_nM_high_MFE_TX_counts_fraction, "\n")
cat("GSE115550_MS645_500_nM net change counts high MFE TX drug vs control:", GSE115550_MS645_500_nM_MS645_500_nM_high_MFE_TX_counts_fraction - GSE115550_MS645_500_nM_control_high_MFE_TX_counts_fraction, "\n")

