GSE241600_MG132_24H_total_UP <- nrow(MFE_res_GSE241600_MG132_24H_UP)
GSE241600_MG132_24H_total_DOWN <- nrow(MFE_res_GSE241600_MG132_24H_DOWN)
GSE241600_MG132_24H_count_high_MFE_UP <- nrow(GSE241600_MG132_24H_high_MFE_TX_in_UP)
GSE241600_MG132_24H_count_high_MFE_DOWN <- nrow(GSE241600_MG132_24H_high_MFE_TX_in_DOWN)

p_UP <- GSE241600_MG132_24H_count_high_MFE_UP / GSE241600_MG132_24H_total_UP
p_DOWN <- GSE241600_MG132_24H_count_high_MFE_DOWN / GSE241600_MG132_24H_total_DOWN

P_pool <- (GSE241600_MG132_24H_count_high_MFE_UP + GSE241600_MG132_24H_count_high_MFE_DOWN) /
  (GSE241600_MG132_24H_total_UP + GSE241600_MG132_24H_total_DOWN)

Z <- (p_UP - p_DOWN) / sqrt(P_pool * (1 - P_pool) * (1/GSE241600_MG132_24H_total_UP + 1/GSE241600_MG132_24H_total_DOWN))

