  dplyr::filter(log2FoldChange > -10 & log2FoldChange < 10)

Plot_GSE129944_Belinostat <- ggplot(MFE_res_GSE129944_Belinostat, aes(y=Normalized_MFE, x=log2FoldChange)) +
  geom_point(size=1.5, alpha=0.3)+
  theme_classic() +
  theme(legend.position="none") +
  geom_vline(xintercept = 0, size=0.3) +
  theme(axis.title = element_text(size = 20)) +
  theme(plot.title = element_text(size = 15)) +
  labs(y="DGfold / nt (kcal/mol)",x="Log2_FC_expression",title="GSE129944_Belinostat_Log2_FC_adj.P<0.05")
print(Plot_GSE129944_Belinostat)

MFE_res_GSE129944_Belinostat$Group <- ifelse(MFE_res_GSE129944_Belinostat$log2FoldChange > 0, "Up-regulated", "Down-regulated")

ViolinPlot_GSE129944_Belinostat <- ggplot(MFE_res_GSE129944_Belinostat, aes(x = Group, y = Normalized_MFE)) +
  geom_violin(fill = "lightgrey", color = "black", alpha = 0.8) +
  geom_boxplot(width = 0.1, fill = "white", color = "black", outlier.shape = NA) +
  theme_classic() +
  theme(axis.title = element_text(size = 20)) +
  theme(plot.title = element_text(size = 15)) +
  labs(y = "ΔGfold / nt (kcal/mol)", x = "Expression Group", title = "GSE129944_Belinostat_Log2_FC_adj.P<0.05")

print(ViolinPlot_GSE129944_Belinostat)

MFE_res_GSE129944_Belinostat_UP <- dplyr::filter(MFE_res_GSE129944_Belinostat, log2FoldChange > 0)
Mean_MFE_res_GSE129944_Belinostat_UP <- mean(MFE_res_GSE129944_Belinostat_UP$Normalized_MFE, na.rm = TRUE)

MFE_res_GSE129944_Belinostat_DOWN <- dplyr::filter(MFE_res_GSE129944_Belinostat, log2FoldChange < 0)
Mean_MFE_res_GSE129944_Belinostat_DOWN <- mean(MFE_res_GSE129944_Belinostat_DOWN$Normalized_MFE, na.rm = TRUE)

TTEST_MFE_res_GSE129944_Belinostat_all_UP_vs_DOWN <- t.test(MFE_res_GSE129944_Belinostat_DOWN$Normalized_MFE, MFE_res_GSE129944_Belinostat_UP$Normalized_MFE, paired=FALSE)
print(TTEST_MFE_res_GSE129944_Belinostat_all_UP_vs_DOWN)

ks_test_res_GSE129944_Belinostat_all_UP_vs_DOWN <- ks.test(MFE_res_GSE129944_Belinostat_DOWN$Normalized_MFE, MFE_res_GSE129944_Belinostat_UP$Normalized_MFE)
print(ks_test_res_GSE129944_Belinostat_all_UP_vs_DOWN)

quantile_075_MFE_res_GSE129944_Belinostat_UP <- quantile(MFE_res_GSE129944_Belinostat_UP$Normalized_MFE, probs = c(0.75))
quantile_075_MFE_res_GSE129944_Belinostat_DOWN <- quantile(MFE_res_GSE129944_Belinostat_DOWN$Normalized_MFE, probs = c(0.75))
ks_test_MFE_075_above <- ks.test(MFE_res_GSE129944_Belinostat_UP$Normalized_MFE[MFE_res_GSE129944_Belinostat_UP$Normalized_MFE >= quantile_075_MFE_res_GSE129944_Belinostat_UP],
                                 MFE_res_GSE129944_Belinostat_DOWN$Normalized_MFE[MFE_res_GSE129944_Belinostat_DOWN$Normalized_MFE >= quantile_075_MFE_res_GSE129944_Belinostat_DOWN])
print(ks_test_MFE_075_above)

quantile_025_MFE_res_GSE129944_Belinostat_UP <- quantile(MFE_res_GSE129944_Belinostat_UP$Normalized_MFE, probs = c(0.25))
quantile_025_MFE_res_GSE129944_Belinostat_DOWN <- quantile(MFE_res_GSE129944_Belinostat_DOWN$Normalized_MFE, probs = c(0.25))
ks_test_MFE_025_below <- ks.test(MFE_res_GSE129944_Belinostat_UP$Normalized_MFE[MFE_res_GSE129944_Belinostat_UP$Normalized_MFE <= quantile_025_MFE_res_GSE129944_Belinostat_UP],
                                 MFE_res_GSE129944_Belinostat_DOWN$Normalized_MFE[MFE_res_GSE129944_Belinostat_DOWN$Normalized_MFE <= quantile_025_MFE_res_GSE129944_Belinostat_DOWN])
print(ks_test_MFE_025_below)

upregulated <- data.frame(MFE = MFE_res_GSE129944_Belinostat_UP$Normalized_MFE, Group = "Up")
downregulated <- data.frame(MFE = MFE_res_GSE129944_Belinostat_DOWN$Normalized_MFE, Group = "Down")
combined_data <- bind_rows(upregulated, downregulated)

GSE129944_Belinostat_observed_diff <- mean(MFE_res_GSE129944_Belinostat_UP$Normalized_MFE, na.rm = TRUE) - mean(MFE_res_GSE129944_Belinostat_DOWN$Normalized_MFE, na.rm = TRUE)

n_permutations <- 10000

GSE129944_Belinostat_permuted_diffs <- numeric(n_permutations)

set.seed(123)
for (i in 1:n_permutations) {
  combined_data <- combined_data %>%
    mutate(Permuted_Group = sample(Group))

  permuted_up_mean <- mean(combined_data$MFE[combined_data$Permuted_Group == "Up"], na.rm = TRUE)
  permuted_down_mean <- mean(combined_data$MFE[combined_data$Permuted_Group == "Down"], na.rm = TRUE)

  GSE129944_Belinostat_permuted_diffs[i] <- permuted_up_mean - permuted_down_mean
}

GSE129944_Belinostat_p_value <- (sum(abs(GSE129944_Belinostat_permuted_diffs) >= abs(GSE129944_Belinostat_observed_diff)) + 1) / (n_permutations + 1)

cat("Observed difference in GSE129944_Belinostat means MFE_UP - MFE_DOWN:", GSE129944_Belinostat_observed_diff, "\n")
cat("GSE129944_Belinostat P-value from permutation test:", GSE129944_Belinostat_p_value, "\n")

GSE129944_norm_TX_counts <- counts(dds_GSE129944, normalized=TRUE)
GSE129944_norm_TX_counts_df <- as.data.frame(GSE129944_norm_TX_counts)
GSE129944_norm_TX_counts_df$ensembl_transcript_id <- rownames(GSE129944_norm_TX_counts_df)
rownames(GSE129944_norm_TX_counts_df) <- NULL

GSE129944_norm_TX_counts_df <- GSE129944_norm_TX_counts_df[, c("ensembl_transcript_id", setdiff(names(GSE129944_norm_TX_counts_df), "ensembl_transcript_id"))]

GSE129944_norm_TX_counts_df$ensembl_transcript_id <- sub("\\..*", "", GSE129944_norm_TX_counts_df$ensembl_transcript_id)

GSE129944_norm_TX_counts_MFE_df <- dplyr::inner_join(Table_ANNOTATED, GSE129944_norm_TX_counts_df, by="ensembl_transcript_id") %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length,
                GSM3728402, GSM3728403, GSM3728406, GSM3728407,
                Normalized_MFE)

GSE129944_Belinostat_norm_TX_counts_MFE_df <- GSE129944_norm_TX_counts_MFE_df %>%
  dplyr::select(ensembl_transcript_id_version, ensembl_transcript_id, ensembl_gene_id, external_gene_name, transcript_is_canonical, Transcript_length,
                GSM3728402, GSM3728403, GSM3728406, GSM3728407,
                Normalized_MFE) %>%
  dplyr::filter(ensembl_transcript_id %in% MFE_res_GSE129944_Belinostat$ensembl_transcript_id)

quantile_075_GSE129944_Belinostat_norm_TX_counts_MFE_df <- quantile(GSE129944_Belinostat_norm_TX_counts_MFE_df$Normalized_MFE, probs = c(0.75))

GSE129944_Belinostat_high_MFE_TX <- dplyr::filter(GSE129944_Belinostat_norm_TX_counts_MFE_df, Normalized_MFE > quantile_075_GSE129944_Belinostat_norm_TX_counts_MFE_df)

GSE129944_Belinostat_high_MFE_TX_in_UP <- dplyr::filter(MFE_res_GSE129944_Belinostat_UP, ensembl_transcript_id_version %in% GSE129944_Belinostat_high_MFE_TX$ensembl_transcript_id_version)
GSE129944_Belinostat_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE129944_Belinostat_DOWN, ensembl_transcript_id_version %in% GSE129944_Belinostat_high_MFE_TX$ensembl_transcript_id_version)

GSE129944_Belinostat_total_UP <- nrow(MFE_res_GSE129944_Belinostat_UP)
GSE129944_Belinostat_total_DOWN <- nrow(MFE_res_GSE129944_Belinostat_DOWN)
GSE129944_Belinostat_count_high_MFE_UP <- nrow(GSE129944_Belinostat_high_MFE_TX_in_UP)
GSE129944_Belinostat_count_high_MFE_DOWN <- nrow(GSE129944_Belinostat_high_MFE_TX_in_DOWN)

p_UP <- GSE129944_Belinostat_count_high_MFE_UP / GSE129944_Belinostat_total_UP
p_DOWN <- GSE129944_Belinostat_count_high_MFE_DOWN / GSE129944_Belinostat_total_DOWN

P_pool <- (GSE129944_Belinostat_count_high_MFE_UP + GSE129944_Belinostat_count_high_MFE_DOWN) /
  (GSE129944_Belinostat_total_UP + GSE129944_Belinostat_total_DOWN)

Z <- (p_UP - p_DOWN) / sqrt(P_pool * (1 - P_pool) * (1/GSE129944_Belinostat_total_UP + 1/GSE129944_Belinostat_total_DOWN))

GSE129944_Belinostat_z_test_MFE_p_value <- 2 * (1 - pnorm(abs(Z)))

cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE129944_Belinostat_z_test_MFE_p_value, "\n")

GSE129944_Belinostat_high_MFE_in_UP_fraction <- GSE129944_Belinostat_count_high_MFE_UP / GSE129944_Belinostat_total_UP
GSE129944_Belinostat_high_MFE_in_DOWN_fraction <- GSE129944_Belinostat_count_high_MFE_DOWN / GSE129944_Belinostat_total_DOWN

cat("Fraction of GSE129944_Belinostat high MFE TX in UP-regulated genes:", GSE129944_Belinostat_high_MFE_in_UP_fraction, "\n")
cat("Fraction of GSE129944_Belinostat high MFE TX in DOWN-regulated genes:", GSE129944_Belinostat_high_MFE_in_DOWN_fraction, "\n")
cat("Mean of GSE129944_Belinostat high MFE TX in UP-regulated genes:", mean(GSE129944_Belinostat_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mean of GSE129944_Belinostat high MFE TX in DOWN-regulated genes:", mean(GSE129944_Belinostat_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")
cat("Mode of GSE129944_Belinostat high MFE TX in UP-regulated genes:", calculate_mode(GSE129944_Belinostat_high_MFE_TX_in_UP$Normalized_MFE), "\n")
cat("Mode of GSE129944_Belinostat high MFE TX in DOWN-regulated genes:", calculate_mode(GSE129944_Belinostat_high_MFE_TX_in_DOWN$Normalized_MFE), "\n")

MFE_res_GSE129944_Belinostat$above_quantile_075 <- MFE_res_GSE129944_Belinostat$Normalized_MFE > quantile_075_GSE129944_Belinostat_norm_TX_counts_MFE_df

Plot_MFE_GSE129944 <- ggplot(MFE_res_GSE129944_Belinostat, aes(x = factor(log2FoldChange > 0), y = Normalized_MFE)) +
