GSE129944_Belinostat_DMSO_high_MFE_TX_counts_fraction <- GSE129944_Belinostat_DMSO_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE129944_Belinostat_DMSO_total_counts$total_counts
print(GSE129944_Belinostat_DMSO_high_MFE_TX_counts_fraction)

GSE129944_Belinostat_Belinostat_total_counts <- dplyr::filter(GSE129944_Belinostat_norm_TX_aggregated_data_avg_counts, condition == "Belinostat") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE129944_Belinostat_Belinostat_high_MFE_TX_counts <- dplyr::filter(GSE129944_Belinostat_norm_TX_aggregated_data_avg_counts, condition == "Belinostat") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE129944_Belinostat_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE129944_Belinostat_Belinostat_high_MFE_TX_counts_fraction <- GSE129944_Belinostat_Belinostat_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE129944_Belinostat_Belinostat_total_counts$total_counts
print(GSE129944_Belinostat_Belinostat_high_MFE_TX_counts_fraction)

p_DMSO <- GSE129944_Belinostat_DMSO_high_MFE_TX_counts_fraction
p_Belinostat <- GSE129944_Belinostat_Belinostat_high_MFE_TX_counts_fraction

P_pool <- (GSE129944_Belinostat_DMSO_high_MFE_TX_counts$total_counts_high_MFE_TX + GSE129944_Belinostat_Belinostat_high_MFE_TX_counts$total_counts_high_MFE_TX) /
  (GSE129944_Belinostat_DMSO_total_counts$total_counts + GSE129944_Belinostat_Belinostat_total_counts$total_counts)

if (GSE129944_Belinostat_DMSO_total_counts$total_counts > 0 & GSE129944_Belinostat_Belinostat_total_counts$total_counts > 0) {
  Z <- (p_DMSO - p_Belinostat) / sqrt(P_pool * (1 - P_pool) * (1/GSE129944_Belinostat_DMSO_total_counts$total_counts + 1/GSE129944_Belinostat_Belinostat_total_counts$total_counts))
  GSE129944_Belinostat_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(Z)))
} else {
  Z <- NA
  GSE129944_Belinostat_z_test_counts_75_p_value <- NA
}

GSE129944_Belinostat_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(Z)))

cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE129944_Belinostat_z_test_counts_75_p_value, "\n")

