  dplyr::filter(ensembl_transcript_id_version %in% GSE129944_Belinostat_low_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_low_MFE_TX = sum(avg_counts))

GSE129944_Belinostat_Belinostat_low_MFE_TX_counts_fraction <- GSE129944_Belinostat_Belinostat_low_MFE_TX_counts$total_counts_low_MFE_TX / GSE129944_Belinostat_Belinostat_total_counts$total_counts
print(GSE129944_Belinostat_Belinostat_low_MFE_TX_counts_fraction)

p_DMSO <- GSE129944_Belinostat_DMSO_low_MFE_TX_counts_fraction
p_Belinostat <- GSE129944_Belinostat_Belinostat_low_MFE_TX_counts_fraction

P_pool <- (GSE129944_Belinostat_DMSO_low_MFE_TX_counts$total_counts_low_MFE_TX + GSE129944_Belinostat_Belinostat_low_MFE_TX_counts$total_counts_low_MFE_TX) /
  (GSE129944_Belinostat_DMSO_total_counts$total_counts + GSE129944_Belinostat_Belinostat_total_counts$total_counts)

var_DMSO <- p_DMSO * (1 - p_DMSO) / GSE129944_Belinostat_DMSO_total_counts$total_counts
var_Belinostat <- p_Belinostat * (1 - p_Belinostat) / GSE129944_Belinostat_Belinostat_total_counts$total_counts

P_pool_variance <- P_pool * (1 - P_pool) * (1 / GSE129944_Belinostat_DMSO_total_counts$total_counts + 1 / GSE129944_Belinostat_Belinostat_total_counts$total_counts)

Z <- (p_DMSO - p_Belinostat) / sqrt(P_pool_variance)

GSE129944_Belinostat_z_test_counts_25_p_value <- 2 * (1 - pnorm(abs(Z)))

cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE129944_Belinostat_z_test_counts_25_p_value, "\n")

