GSE129944_17_AAG_high_MFE_TX_in_DOWN <- dplyr::filter(MFE_res_GSE129944_17_AAG_DOWN, ensembl_transcript_id_version %in% GSE129944_17_AAG_high_MFE_TX$ensembl_transcript_id_version)

GSE129944_17_AAG_total_UP <- nrow(MFE_res_GSE129944_17_AAG_UP)
GSE129944_17_AAG_total_DOWN <- nrow(MFE_res_GSE129944_17_AAG_DOWN)
GSE129944_17_AAG_count_high_MFE_UP <- nrow(GSE129944_17_AAG_high_MFE_TX_in_UP)
GSE129944_17_AAG_count_high_MFE_DOWN <- nrow(GSE129944_17_AAG_high_MFE_TX_in_DOWN)

p_UP <- GSE129944_17_AAG_count_high_MFE_UP / GSE129944_17_AAG_total_UP
p_DOWN <- GSE129944_17_AAG_count_high_MFE_DOWN / GSE129944_17_AAG_total_DOWN

P_pool <- (GSE129944_17_AAG_count_high_MFE_UP + GSE129944_17_AAG_count_high_MFE_DOWN) /
  (GSE129944_17_AAG_total_UP + GSE129944_17_AAG_total_DOWN)

Z <- (p_UP - p_DOWN) / sqrt(P_pool * (1 - P_pool) * (1/GSE129944_17_AAG_total_UP + 1/GSE129944_17_AAG_total_DOWN))

GSE129944_17_AAG_z_test_MFE_p_value <- 2 * (1 - pnorm(abs(Z)))

cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE129944_17_AAG_z_test_MFE_p_value, "\n")

