  )

GSE163249_Vorinostat_long_data <- GSE163249_Vorinostat_long_data %>%
  dplyr::mutate(condition = ifelse(replicate %in% c("GSM4975597", "GSM4975599"), "DMSO", "Vorinostat"))

GSE163249_Vorinostat_norm_TX_aggregated_data_avg_counts <- GSE163249_Vorinostat_long_data %>%
  group_by(ensembl_transcript_id_version, condition, Normalized_MFE) %>%
  summarise(
    avg_counts = mean(counts, na.rm = TRUE),
    .groups = 'drop'
  )

GSE163249_Vorinostat_MFE_all_TX_75_percentile <- quantile(GSE163249_Vorinostat_norm_TX_aggregated_data_avg_counts$Normalized_MFE, 0.75)

GSE163249_Vorinostat_high_MFE_TX_total <- dplyr::filter(GSE163249_Vorinostat_norm_TX_counts_MFE_df, Normalized_MFE > GSE163249_Vorinostat_MFE_all_TX_75_percentile)

GSE163249_Vorinostat_DMSO_total_counts <- dplyr::filter(GSE163249_Vorinostat_norm_TX_aggregated_data_avg_counts, condition == "DMSO") %>%
  dplyr::summarise(total_counts = sum(avg_counts, na.rm = TRUE))

GSE163249_Vorinostat_DMSO_high_MFE_TX_counts <- dplyr::filter(GSE163249_Vorinostat_norm_TX_aggregated_data_avg_counts, condition == "DMSO") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE163249_Vorinostat_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE163249_Vorinostat_DMSO_high_MFE_TX_counts_fraction <- GSE163249_Vorinostat_DMSO_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE163249_Vorinostat_DMSO_total_counts$total_counts
print(GSE163249_Vorinostat_DMSO_high_MFE_TX_counts_fraction)

GSE163249_Vorinostat_Vorinostat_total_counts <- dplyr::filter(GSE163249_Vorinostat_norm_TX_aggregated_data_avg_counts, condition == "Vorinostat") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE163249_Vorinostat_Vorinostat_high_MFE_TX_counts <- dplyr::filter(GSE163249_Vorinostat_norm_TX_aggregated_data_avg_counts, condition == "Vorinostat") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE163249_Vorinostat_high_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_high_MFE_TX = sum(avg_counts))

GSE163249_Vorinostat_Vorinostat_high_MFE_TX_counts_fraction <- GSE163249_Vorinostat_Vorinostat_high_MFE_TX_counts$total_counts_high_MFE_TX / GSE163249_Vorinostat_Vorinostat_total_counts$total_counts
print(GSE163249_Vorinostat_Vorinostat_high_MFE_TX_counts_fraction)

p_DMSO <- GSE163249_Vorinostat_DMSO_high_MFE_TX_counts_fraction
p_Vorinostat <- GSE163249_Vorinostat_Vorinostat_high_MFE_TX_counts_fraction

P_pool <- (GSE163249_Vorinostat_DMSO_high_MFE_TX_counts$total_counts_high_MFE_TX + GSE163249_Vorinostat_Vorinostat_high_MFE_TX_counts$total_counts_high_MFE_TX) /
  (GSE163249_Vorinostat_DMSO_total_counts$total_counts + GSE163249_Vorinostat_Vorinostat_total_counts$total_counts)

if (GSE163249_Vorinostat_DMSO_total_counts$total_counts > 0 & GSE163249_Vorinostat_Vorinostat_total_counts$total_counts > 0) {
  Z <- (p_DMSO - p_Vorinostat) / sqrt(P_pool * (1 - P_pool) * (1/GSE163249_Vorinostat_DMSO_total_counts$total_counts + 1/GSE163249_Vorinostat_Vorinostat_total_counts$total_counts))
  GSE163249_Vorinostat_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(Z)))
} else {
  Z <- NA
  GSE163249_Vorinostat_z_test_counts_75_p_value <- NA
}

GSE163249_Vorinostat_z_test_counts_75_p_value <- 2 * (1 - pnorm(abs(Z)))

cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE163249_Vorinostat_z_test_counts_75_p_value, "\n")

cat("GSE163249_Vorinostat DMSO high MFE TX as fraction of total counts:", GSE163249_Vorinostat_DMSO_high_MFE_TX_counts_fraction, "\n")
cat("GSE163249_Vorinostat high MFE TX as fraction of total counts:", GSE163249_Vorinostat_Vorinostat_high_MFE_TX_counts_fraction, "\n")
cat("GSE163249_Vorinostat net change counts high MFE TX drug vs DMSO:", GSE163249_Vorinostat_Vorinostat_high_MFE_TX_counts_fraction - GSE163249_Vorinostat_DMSO_high_MFE_TX_counts_fraction, "\n")

