GSE163249_Vorinostat_combined_plots

GSE163249_Vorinostat_MFE_all_TX_25_percentile <- quantile(GSE163249_Vorinostat_norm_TX_aggregated_data_avg_counts$Normalized_MFE, 0.25)

GSE163249_Vorinostat_low_MFE_TX_total <- dplyr::filter(GSE163249_Vorinostat_norm_TX_counts_MFE_df, Normalized_MFE < GSE163249_Vorinostat_MFE_all_TX_25_percentile)

GSE163249_Vorinostat_DMSO_total_counts <- dplyr::filter(GSE163249_Vorinostat_norm_TX_aggregated_data_avg_counts, condition == "DMSO") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE163249_Vorinostat_DMSO_low_MFE_TX_counts <- dplyr::filter(GSE163249_Vorinostat_norm_TX_aggregated_data_avg_counts, condition == "DMSO") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE163249_Vorinostat_low_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_low_MFE_TX = sum(avg_counts))

GSE163249_Vorinostat_DMSO_low_MFE_TX_counts_fraction <- GSE163249_Vorinostat_DMSO_low_MFE_TX_counts$total_counts_low_MFE_TX / GSE163249_Vorinostat_DMSO_total_counts$total_counts
print(GSE163249_Vorinostat_DMSO_low_MFE_TX_counts_fraction)

GSE163249_Vorinostat_Vorinostat_total_counts <- dplyr::filter(GSE163249_Vorinostat_norm_TX_aggregated_data_avg_counts, condition == "Vorinostat") %>%
  dplyr::summarise(total_counts = sum(avg_counts))

GSE163249_Vorinostat_Vorinostat_low_MFE_TX_counts <- dplyr::filter(GSE163249_Vorinostat_norm_TX_aggregated_data_avg_counts, condition == "Vorinostat") %>%
  dplyr::filter(ensembl_transcript_id_version %in% GSE163249_Vorinostat_low_MFE_TX_total$ensembl_transcript_id_version) %>%
  dplyr::summarise(total_counts_low_MFE_TX = sum(avg_counts))

GSE163249_Vorinostat_Vorinostat_low_MFE_TX_counts_fraction <- GSE163249_Vorinostat_Vorinostat_low_MFE_TX_counts$total_counts_low_MFE_TX / GSE163249_Vorinostat_Vorinostat_total_counts$total_counts
print(GSE163249_Vorinostat_Vorinostat_low_MFE_TX_counts_fraction)

p_DMSO <- GSE163249_Vorinostat_DMSO_low_MFE_TX_counts_fraction
p_Vorinostat <- GSE163249_Vorinostat_Vorinostat_low_MFE_TX_counts_fraction

P_pool <- (GSE163249_Vorinostat_DMSO_low_MFE_TX_counts$total_counts_low_MFE_TX + GSE163249_Vorinostat_Vorinostat_low_MFE_TX_counts$total_counts_low_MFE_TX) /
  (GSE163249_Vorinostat_DMSO_total_counts$total_counts + GSE163249_Vorinostat_Vorinostat_total_counts$total_counts)

var_DMSO <- p_DMSO * (1 - p_DMSO) / GSE163249_Vorinostat_DMSO_total_counts$total_counts
var_Vorinostat <- p_Vorinostat * (1 - p_Vorinostat) / GSE163249_Vorinostat_Vorinostat_total_counts$total_counts

P_pool_variance <- P_pool * (1 - P_pool) * (1 / GSE163249_Vorinostat_DMSO_total_counts$total_counts + 1 / GSE163249_Vorinostat_Vorinostat_total_counts$total_counts)

Z <- (p_DMSO - p_Vorinostat) / sqrt(P_pool_variance)

GSE163249_Vorinostat_z_test_counts_25_p_value <- 2 * (1 - pnorm(abs(Z)))

cat("Two-proportion Z-test statistic:", Z, "\n")
cat("Two-proportion Z-test p-value:", GSE163249_Vorinostat_z_test_counts_25_p_value, "\n")

cat("GSE163249_Vorinostat DMSO low MFE TX as fraction of total counts:", GSE163249_Vorinostat_DMSO_low_MFE_TX_counts_fraction, "\n")
cat("GSE163249_Vorinostat low MFE TX as fraction of total counts:", GSE163249_Vorinostat_Vorinostat_low_MFE_TX_counts_fraction, "\n")
cat("GSE163249_Vorinostat net change counts low MFE TX drug vs DMSO:", GSE163249_Vorinostat_Vorinostat_low_MFE_TX_counts_fraction - GSE163249_Vorinostat_DMSO_low_MFE_TX_counts_fraction, "\n")

